INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C1','math',3,2,'u2',2,'곱셈구구로 몫 구하기와 (몇십) ÷ (몇) 내림 없음 — 나누는 수의 단에서 몫을 찾고, 몇십은 10 카드 몇 장으로 보아 (몇) ÷ (몇)의 몫을 10배 하기',ARRAY['4수01-07']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C2','math',3,2,'u2',3,'(몇십) ÷ (몇) 내림 있음 — 십의 자리를 나누고 남은 10 카드를 1 카드 10장으로 바꾸어(아래로 내려) 다시 나누기',ARRAY['4수01-07']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C3','math',3,2,'u2',4,'(몇십몇) ÷ (몇) 내림 없음 — 십의 자리와 일의 자리를 차례로 나누어 몫을 그 자리 위에 쓰기',ARRAY['4수01-07']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C4','math',3,2,'u2',4,'나눗셈 어림하기 — 나누어지는 수를 나누기 쉬운 몇십·몇백으로 보아 몫이 얼마쯤일지, 몫이 어느 두 수 사이에 있을지 가늠하고 계산한 몫과 견주기',ARRAY['4수01-07']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C5','math',3,2,'u2',5,'(몇십몇) ÷ (몇) 내림 있음 — 십의 자리를 나누고 남은 수를 일의 자리 위로 내려 함께 다시 나누기',ARRAY['4수01-07']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C6','math',3,2,'u2',6,'나머지와 나누어떨어짐 — 똑같이 나누고 남는 수가 나머지이고, 나머지가 0이면 나누어떨어진다고 하며, 나머지는 언제나 나누는 수보다 작음을 알기',ARRAY['4수01-07']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C7','math',3,2,'u2',7,'나머지가 있는 (몇십몇) ÷ (몇)과 계산 확인 — 몫이 두 자리인 나눗셈의 몫과 나머지를 구하고, 나누는 수 × 몫 + 나머지 = 나누어지는 수로 확인하기',ARRAY['4수01-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C8','math',3,2,'u2',8,'(세 자리 수) ÷ (몇) 몫이 세 자리 — 몇백은 (몇) ÷ (몇)의 몫을 100배로 보고, 백의 자리부터 차례로 나누며 나눌 수 없는 자리의 몫에 0 쓰기',ARRAY['4수01-07']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C9','math',3,2,'u2',9,'(세 자리 수) ÷ (몇) 몫이 두 자리 — 백의 자리가 나누는 수보다 작으면 십의 자리까지 함께 보아 나누고, 몫이 몇 자리일지 어림해 확인하기',ARRAY['4수01-07']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C10','math',3,2,'u2',10,'나눗셈으로 문제 해결하기 — 상황을 나눗셈식으로 세우고, 몫(한 묶음·한 사람 몫)과 나머지(남는 것)가 각각 무엇을 뜻하는지 읽어 알맞게 답하기',ARRAY['4수01-07']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X01','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C8']::text[],'몇십·몇백을 나눌 때 몫의 0을 빠뜨린다(60 ÷ 3 = 2, 800 ÷ 4 = 2)','몇십이면 몫도 몇십') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X02','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C8']::text[],'몫에 0을 더 붙인다(60 ÷ 3 = 200, 30 ÷ 2 = 150)','자리에 맞추어 몫 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X03','math',3,'u2',ARRAY['M3-2-u2-C2','M3-2-u2-C5','M3-2-u2-C7','M3-2-u2-C9']::text[],'윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다(30 ÷ 2 = 10, 45 ÷ 3 = 11)','남은 수는 아래로 내리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X04','math',3,'u2',ARRAY['M3-2-u2-C3','M3-2-u2-C5']::text[],'몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다(93 ÷ 3 = 13)','높은 자리부터 그 자리 위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X05','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C9']::text[],'나머지를 나누는 수보다 크거나 같게 남긴다(257 ÷ 4 = 63 … 5)','나머지 < 나누는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X06','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7']::text[],'몫과 나머지를 바꾸어 쓴다(25 ÷ 4 = 1 … 6)','묶음 수가 몫, 남은 것이 나머지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X07','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C10']::text[],'나머지를 빠뜨리고 몫만 쓰거나, 남는 것이 있는데 나누어떨어진다고 한다','남은 것까지 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X08','math',3,'u2',ARRAY['M3-2-u2-C7']::text[],'확인할 때 나누는 수 대신 나머지를 몫에 곱한다(99 ÷ 8 = 12 … 3 → 3 × 12 + 8)','나누는 수 × 몫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X09','math',3,'u2',ARRAY['M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9']::text[],'확인할 때 나머지를 더하지 않는다(나누는 수 × 몫만 견준다)','+ 나머지까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X10','math',3,'u2',ARRAY['M3-2-u2-C8','M3-2-u2-C9']::text[],'나눌 수 없는 가운데 자리의 몫 0을 빠뜨린다(307 ÷ 3 = 12 … 1)','나눌 수 없으면 몫에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X11','math',3,'u2',ARRAY['M3-2-u2-C8']::text[],'몫의 0을 끝에 붙여 자리가 어긋난다(615 ÷ 6 = 120 … 15)','0은 그 자리에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X12','math',3,'u2',ARRAY['M3-2-u2-C9']::text[],'백의 자리가 나누는 수보다 작은데 몫을 세 자리로 쓴다(258 ÷ 4 = 640 …)','백의 자리 < 나누는 수면 몫은 두 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X13','math',3,'u2',ARRAY['M3-2-u2-C10','M3-2-u2-C6','M3-2-u2-C7']::text[],'문제에서 몫을 묻는지 나머지를 묻는지 바꾸어 답하거나, 남는 것을 위해 하나 더 필요한 경우를 놓친다','묻는 것에 밑줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X14','math',3,'u2',ARRAY['M3-2-u2-C10','M3-2-u2-C1','M3-2-u2-C3']::text[],'똑같이 나누는 상황에 나눗셈 대신 곱셈·뺄셈 식을 세운다(96개를 3모둠에 → 96 × 3, 96 − 3)','똑같이 나누면 ÷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X15','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C3','M3-2-u2-C5','M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9','M3-2-u2-C10','M3-2-u2-C6']::text[],'곱셈구구나 빼기에서 실수해 몫이 1 크거나 작다','나누는 수 × 몫으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X16','math',3,'u2',ARRAY['M3-2-u2-C4','M3-2-u2-C9']::text[],'어림할 때 나누기 쉬운 수로 바꾸지 않거나 몫의 자리 수를 잘못 가늠한다','나누기 쉬운 몇십·몇백으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X17','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C3','M3-2-u2-C4','M3-2-u2-C5','M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9','M3-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는, 큰↔작은, 몫↔나머지','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X18','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C10']::text[],'나누어떨어진다는 뜻을 헷갈린다(나머지가 0일 때가 아니라 몫이 0일 때라고 생각한다)','나머지 0 = 나누어떨어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#1','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'sa','auto','18 ÷ 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"18 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 6의 단에서 18을 찾아요.","6 × 3 = 18 — 그래서 18 ÷ 6 = 3이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"42 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나누는 수 6의 단에서 42를 찾아요.","6 × 7 = 42 — 그래서 42 ÷ 6 = 7이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null},{"stem":"32 ÷ 8은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 8의 단에서 32를 찾아요.","8 × 4 = 32 — 그래서 32 ÷ 8 = 4예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#2','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'mc','auto','42 ÷ 7의 몫을 구할 때 쓸 수 있는 곱셈구구는 어느 것인가요?',ARRAY['M3-2-u2-X15']::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"mc","stem":"42 ÷ 7의 몫을 구할 때 쓸 수 있는 곱셈구구는 어느 것인가요?","options":[{"t":"7 × 6 = 42","correct":true},{"t":"7 × 7 = 49","mis":"M3-2-u2-X15"},{"t":"6 × 6 = 36","mis":"M3-2-u2-X15"},{"t":"8 × 6 = 48","mis":"M3-2-u2-X15"}],"explanation":["나누는 수가 7 — 7단에서 42를 찾아요.","7 × 6 = 42예요.","그래서 42 ÷ 7 = 6이에요."],"variant_rule":{"alt":[{"stem":"12 ÷ 6의 몫을 구할 때 쓸 수 있는 곱셈구구는 어느 것인가요?","options":[{"t":"6 × 2 = 12","correct":true},{"t":"6 × 3 = 18","mis":"M3-2-u2-X15"},{"t":"2 × 2 = 4","mis":"M3-2-u2-X15"},{"t":"7 × 2 = 14","mis":"M3-2-u2-X15"}],"explanation":["나누는 수가 6 — 6단에서 12를 찾아요.","6 × 2 = 12예요.","그래서 12 ÷ 6 = 2예요."],"asset":null},{"stem":"45 ÷ 5의 몫을 구할 때 쓸 수 있는 곱셈구구는 어느 것인가요?","options":[{"t":"5 × 9 = 45","correct":true},{"t":"5 × 10 = 50","mis":"M3-2-u2-X15"},{"t":"9 × 9 = 81","mis":"M3-2-u2-X15"},{"t":"6 × 9 = 54","mis":"M3-2-u2-X15"}],"explanation":["나누는 수가 5 — 5단에서 45를 찾아요.","5 × 9 = 45예요.","그래서 45 ÷ 5 = 9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#3','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'sa','auto','6 ÷ 3 = 2예요. 그러면 60 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"6 ÷ 3 = 2예요. 그러면 60 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 60 ÷ 3 = 20이에요."],"variant_rule":{"alt":[{"stem":"6 ÷ 2 = 3이에요. 그러면 60 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","3의 10배 — 60 ÷ 2 = 30이에요."],"asset":null},{"stem":"8 ÷ 2 = 4예요. 그러면 80 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["80은 8의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","4의 10배 — 80 ÷ 2 = 40이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#4','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'mc','auto','80 ÷ 2는 얼마인가요?',ARRAY['M3-2-u2-X01','M3-2-u2-X02']::text[],true,'{"seq":4,"concept":"M3-2-u2-C1","difficulty":1,"kind":"mc","stem":"80 ÷ 2는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M3-2-u2-X01"},{"t":"400","mis":"M3-2-u2-X02"},{"t":"45","mis":"M3-2-u2-X02"}],"explanation":["80은 10 카드 8장 — 8 ÷ 2 = 4예요.","나누어지는 수가 10배면 몫도 10배예요.","80 ÷ 2 = 40 — 확인: 2 × 40 = 80이에요."],"variant_rule":{"alt":[{"stem":"20 ÷ 2는 얼마인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M3-2-u2-X01"},{"t":"100","mis":"M3-2-u2-X02"},{"t":"15","mis":"M3-2-u2-X02"}],"explanation":["20은 10 카드 2장 — 2 ÷ 2 = 1이에요.","나누어지는 수가 10배면 몫도 10배예요.","20 ÷ 2 = 10 — 확인: 2 × 10 = 20이에요."],"asset":null},{"stem":"80 ÷ 4는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M3-2-u2-X01"},{"t":"200","mis":"M3-2-u2-X02"},{"t":"25","mis":"M3-2-u2-X02"}],"explanation":["80은 10 카드 8장 — 8 ÷ 4 = 2예요.","나누어지는 수가 10배면 몫도 10배예요.","80 ÷ 4 = 20 — 확인: 4 × 20 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#5','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'sa','auto','60은 10 카드 6장이에요. 10 카드를 3곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C1","difficulty":2,"kind":"sa","stem":"60은 10 카드 6장이에요. 10 카드를 3곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.","answer":["2"],"explanation":["10 카드 6장을 3곳에 한 장씩 차례로 놓아요.","6 ÷ 3 = 2예요 — 한 곳에 2장씩.","10 카드 2장은 20 — 60 ÷ 3 = 20이에요."],"variant_rule":{"alt":[{"stem":"30은 10 카드 3장이에요. 10 카드를 3곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.","answer":["1"],"explanation":["10 카드 3장을 3곳에 한 장씩 차례로 놓아요.","3 ÷ 3 = 1이에요 — 한 곳에 1장씩.","10 카드 1장은 10 — 30 ÷ 3 = 10이에요."],"asset":null},{"stem":"90은 10 카드 9장이에요. 10 카드를 9곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.","answer":["1"],"explanation":["10 카드 9장을 9곳에 한 장씩 차례로 놓아요.","9 ÷ 9 = 1이에요 — 한 곳에 1장씩.","10 카드 1장은 10 — 90 ÷ 9 = 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#6','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'mc','auto','금잔화 모종 60개를 화단 3곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X01']::text[],true,'{"seq":6,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"금잔화 모종 60개를 화단 3곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?","options":[{"t":"20개","correct":true},{"t":"57개","mis":"M3-2-u2-X14"},{"t":"180개","mis":"M3-2-u2-X14"},{"t":"2개","mis":"M3-2-u2-X01"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 60 ÷ 3으로 세워요.","나누어지는 수가 10배면 몫도 10배예요.","60 ÷ 3 = 20 — 20개예요."],"variant_rule":{"alt":[{"stem":"손수건 50장을 5명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요?","options":[{"t":"10장","correct":true},{"t":"45장","mis":"M3-2-u2-X14"},{"t":"250장","mis":"M3-2-u2-X14"},{"t":"1장","mis":"M3-2-u2-X01"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 50 ÷ 5로 세워요.","나누어지는 수가 10배면 몫도 10배예요.","50 ÷ 5 = 10 — 10장이에요."],"asset":null},{"stem":"약과 70개를 어르신 7분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요?","options":[{"t":"10개","correct":true},{"t":"63개","mis":"M3-2-u2-X14"},{"t":"490개","mis":"M3-2-u2-X14"},{"t":"1개","mis":"M3-2-u2-X01"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 70 ÷ 7로 세워요.","나누어지는 수가 10배면 몫도 10배예요.","70 ÷ 7 = 10 — 10개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#7','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'ox','auto','70 ÷ 7 = 1이에요.',ARRAY['M3-2-u2-X01']::text[],true,'{"seq":7,"concept":"M3-2-u2-C1","difficulty":2,"kind":"ox","stem":"70 ÷ 7 = 1이에요.","answer":"X","reason_options":[{"t":"70은 7의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"mis":"M3-2-u2-X01","explanation":["7 ÷ 7 = 1이에요.","70은 7의 10배 — 몫도 10배인 10이에요.","1은 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":70,"b":7,"upto":0},"variant_rule":{"alt":[{"stem":"60 ÷ 3 = 2예요.","answer":"X","reason_options":[{"t":"60은 6의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"explanation":["6 ÷ 3 = 2예요.","60은 6의 10배 — 몫도 10배인 20이에요.","2는 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":60,"b":3,"upto":0}},{"stem":"90 ÷ 3 = 3이에요.","answer":"X","reason_options":[{"t":"90은 9의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"explanation":["9 ÷ 3 = 3이에요.","90은 9의 10배 — 몫도 10배인 30이에요.","3은 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":90,"b":3,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#8','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'sa','auto','80 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C1","difficulty":2,"kind":"sa","stem":"80 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 0 → 몫 0.","80 ÷ 2 = 40 — 십의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":80,"b":2,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"80 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 0 → 몫 0.","80 ÷ 4 = 20 — 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":80,"b":4,"hide":[["q",0]]}},{"stem":"60 ÷ 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 0 → 몫 0.","60 ÷ 3 = 20 — 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":60,"b":3,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#9','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C1","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"40 ÷ 2","r":"20"},{"l":"80 ÷ 2","r":"40"},{"l":"80 ÷ 8","r":"10"}],"mis":"M3-2-u2-X01","explanation":["높은 자리부터 차례로 나누어요.","40 ÷ 2 = 20, 80 ÷ 2 = 40, 80 ÷ 8 = 10.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"60 ÷ 2","r":"30"},{"l":"30 ÷ 3","r":"10"},{"l":"80 ÷ 2","r":"40"}],"explanation":["높은 자리부터 차례로 나누어요.","60 ÷ 2 = 30, 30 ÷ 3 = 10, 80 ÷ 2 = 40.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"60 ÷ 3","r":"20"},{"l":"90 ÷ 9","r":"10"},{"l":"60 ÷ 2","r":"30"}],"explanation":["높은 자리부터 차례로 나누어요.","60 ÷ 3 = 20, 90 ÷ 9 = 10, 60 ÷ 2 = 30.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_basic#10','math',3,2,'u2','L02','g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',3,'error','auto','90 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X01','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C1","difficulty":3,"kind":"error","stem":"90 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「90 ÷ 3 = 3이야」","correct":true,"mis_target":"M3-2-u2-X01"},{"t":"은우 — 「90 ÷ 3 = 30이야」","mis":"M3-2-u2-X17"},{"t":"지유 — 「90 ÷ 3은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["나누어지는 수가 10배면 몫도 10배예요.","90 ÷ 3 = 30.","도윤이 잘못 말했어요 — 몇십이면 몫도 몇십."],"variant_rule":{"alt":[{"stem":"50 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「50 ÷ 5 = 100이야」","correct":true,"mis_target":"M3-2-u2-X02"},{"t":"태오 — 「50 ÷ 5 = 10이야」","mis":"M3-2-u2-X17"},{"t":"은우 — 「확인하면 5 × 10 = 50이야」","mis":"M3-2-u2-X17"}],"explanation":["나누어지는 수가 10배면 몫도 10배예요.","50 ÷ 5 = 10.","하린이 잘못 말했어요 — 자리에 맞추어 몫 쓰기."],"asset":null},{"stem":"60 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「60 ÷ 3 = 2야」","correct":true,"mis_target":"M3-2-u2-X01"},{"t":"시우 — 「60 ÷ 3 = 20이야」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「60 ÷ 3은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["나누어지는 수가 10배면 몫도 10배예요.","60 ÷ 3 = 20.","은우가 잘못 말했어요 — 몇십이면 몫도 몇십."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#1','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',2,'mc','auto','60 ÷ 3 = 20을 세로셈으로 쓸 때 몫의 십의 자리 2는 무엇을 나타내나요?',ARRAY['M3-2-u2-X01','M3-2-u2-X14','M3-2-u2-X02']::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"60 ÷ 3 = 20을 세로셈으로 쓸 때 몫의 십의 자리 2는 무엇을 나타내나요?","options":[{"t":"10 카드 2장(20)","correct":true},{"t":"1 카드 2장(2)","mis":"M3-2-u2-X01"},{"t":"10 카드 6장(60)","mis":"M3-2-u2-X14"},{"t":"100 카드 2장(200)","mis":"M3-2-u2-X02"}],"explanation":["몫은 나누어지는 수의 자리에 맞추어 써요.","십의 자리 6 ÷ 3 = 2 — 10 카드 2장씩이에요.","그래서 몫의 십의 자리 2는 20을 나타내요."],"asset":{"type":"ldiv","a":60,"b":3},"variant_rule":{"alt":[{"stem":"60 ÷ 2 = 30을 세로셈으로 쓸 때 몫의 십의 자리 3은 무엇을 나타내나요?","options":[{"t":"10 카드 3장(30)","correct":true},{"t":"1 카드 3장(3)","mis":"M3-2-u2-X01"},{"t":"10 카드 6장(60)","mis":"M3-2-u2-X14"},{"t":"100 카드 3장(300)","mis":"M3-2-u2-X02"}],"explanation":["몫은 나누어지는 수의 자리에 맞추어 써요.","십의 자리 6 ÷ 2 = 3 — 10 카드 3장씩이에요.","그래서 몫의 십의 자리 3은 30을 나타내요."],"asset":{"type":"ldiv","a":60,"b":2}},{"stem":"50 ÷ 5 = 10을 세로셈으로 쓸 때 몫의 십의 자리 1은 무엇을 나타내나요?","options":[{"t":"10 카드 1장(10)","correct":true},{"t":"1 카드 1장(1)","mis":"M3-2-u2-X01"},{"t":"10 카드 5장(50)","mis":"M3-2-u2-X14"},{"t":"100 카드 1장(100)","mis":"M3-2-u2-X02"}],"explanation":["몫은 나누어지는 수의 자리에 맞추어 써요.","십의 자리 5 ÷ 5 = 1 — 10 카드 1장씩이에요.","그래서 몫의 십의 자리 1은 10을 나타내요."],"asset":{"type":"ldiv","a":50,"b":5}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#2','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',2,'sa','auto','봉사 활동을 가는 학생 72명이 버스 9대에 똑같이 나누어 타려고 해요. 한 대에 몇 명씩 타나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":2,"kind":"sa","stem":"봉사 활동을 가는 학생 72명이 버스 9대에 똑같이 나누어 타려고 해요. 한 대에 몇 명씩 타나요? 숫자로 쓰세요.","answer":["8"],"explanation":["똑같이 나누는 상황 — 나눗셈식 72 ÷ 9로 세워요.","9 × 8 = 72 — 그래서 72 ÷ 9 = 8이에요.","72 ÷ 9 = 8 — 8명이에요."],"variant_rule":{"alt":[{"stem":"봉사 활동 배지 21개를 3모둠에 똑같이 나누어 주려고 해요. 한 모둠은 몇 개를 받나요? 숫자로 쓰세요.","answer":["7"],"explanation":["똑같이 나누는 상황 — 나눗셈식 21 ÷ 3으로 세워요.","3 × 7 = 21 — 그래서 21 ÷ 3 = 7이에요.","21 ÷ 3 = 7 — 7개예요."],"asset":null},{"stem":"금잔화 모종 12개를 화단 4곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요? 숫자로 쓰세요.","answer":["3"],"explanation":["똑같이 나누는 상황 — 나눗셈식 12 ÷ 4로 세워요.","4 × 3 = 12 — 그래서 12 ÷ 4 = 3이에요.","12 ÷ 4 = 3 — 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#3','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 80 ÷ 4 ○ 90 ÷ 3',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C1","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 80 ÷ 4 ○ 90 ÷ 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["80 ÷ 4의 몫은 20이에요.","90 ÷ 3의 몫은 30이에요.","20 < 30 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 30 ÷ 3 ○ 60 ÷ 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["30 ÷ 3의 몫은 10이에요.","60 ÷ 3의 몫은 20이에요.","10 < 20 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 40 ÷ 4 ○ 80 ÷ 8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["40 ÷ 4의 몫은 10이에요.","80 ÷ 8의 몫은 10이에요.","10 < 10 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#4','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'sa','auto','하랑이 60 ÷ 2를 계산하고 몫을 3이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C1","difficulty":3,"kind":"sa","stem":"하랑이 60 ÷ 2를 계산하고 몫을 3이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["하랑 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","나누어지는 수가 10배면 몫도 10배예요.","바른 몫은 30 — 확인: 2 × 30 = 60이에요."],"variant_rule":{"alt":[{"stem":"시우가 50 ÷ 5를 계산하고 몫을 1이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["시우 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","나누어지는 수가 10배면 몫도 10배예요.","바른 몫은 10 — 확인: 5 × 10 = 50이에요."],"asset":null},{"stem":"시우가 60 ÷ 6을 계산하고 몫을 1이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["시우 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","나누어지는 수가 10배면 몫도 10배예요.","바른 몫은 10 — 확인: 6 × 10 = 60이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#5','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'mc','auto','9 ÷ 3 = 3이에요. 그러면 90 ÷ 3은 얼마인가요?',ARRAY['M3-2-u2-X01','M3-2-u2-X02']::text[],true,'{"seq":5,"concept":"M3-2-u2-C1","difficulty":3,"kind":"mc","stem":"9 ÷ 3 = 3이에요. 그러면 90 ÷ 3은 얼마인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M3-2-u2-X01"},{"t":"300","mis":"M3-2-u2-X02"},{"t":"35","mis":"M3-2-u2-X02"}],"explanation":["90은 9의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","3의 10배 — 90 ÷ 3 = 30이에요."],"variant_rule":{"alt":[{"stem":"4 ÷ 2 = 2예요. 그러면 40 ÷ 2는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M3-2-u2-X01"},{"t":"200","mis":"M3-2-u2-X02"},{"t":"25","mis":"M3-2-u2-X02"}],"explanation":["40은 4의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 40 ÷ 2 = 20이에요."],"asset":null},{"stem":"8 ÷ 4 = 2예요. 그러면 80 ÷ 4는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M3-2-u2-X01"},{"t":"200","mis":"M3-2-u2-X02"},{"t":"25","mis":"M3-2-u2-X02"}],"explanation":["80은 8의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 80 ÷ 4 = 20이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#6','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'sa','auto','90 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C1","difficulty":3,"kind":"sa","stem":"90 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 3을 세운 자리 — 3 × 3 = 9예요.","90 ÷ 3 = 30 — 확인: 3 × 30 = 90이에요."],"asset":{"type":"ldiv","a":90,"b":3,"hide":[["r",0]]},"variant_rule":{"alt":[{"stem":"60 ÷ 6의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 1을 세운 자리 — 6 × 1 = 6이에요.","60 ÷ 6 = 10 — 확인: 6 × 10 = 60이에요."],"asset":{"type":"ldiv","a":60,"b":6,"hide":[["r",0]]}},{"stem":"30 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 1을 세운 자리 — 3 × 1 = 3이에요.","30 ÷ 3 = 10 — 확인: 3 × 10 = 30이에요."],"asset":{"type":"ldiv","a":30,"b":3,"hide":[["r",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#7','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'error','auto','56 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C1","difficulty":3,"kind":"error","stem":"56 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「56 ÷ 8 = 8이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"은우 — 「56 ÷ 8 = 7이야」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「56 ÷ 8은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["8 × 7 = 56 — 그래서 56 ÷ 8 = 7이에요.","56 ÷ 8 = 7.","도윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"63 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「63 ÷ 7 = 8이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「63 ÷ 7 = 9야」","mis":"M3-2-u2-X17"},{"t":"하랑 — 「확인하면 7 × 9 = 63이야」","mis":"M3-2-u2-X17"}],"explanation":["7 × 9 = 63 — 그래서 63 ÷ 7 = 9예요.","63 ÷ 7 = 9.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"10 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「10 ÷ 5 = 3이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"하랑 — 「10 ÷ 5 = 2야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「10 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["5 × 2 = 10 — 그래서 10 ÷ 5 = 2예요.","10 ÷ 5 = 2.","은우가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#8','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'essay','teacher','봉사 활동을 가는 학생 60명이 버스 3대에 똑같이 나누어 타요. 60 ÷ 3을 10 카드로 구하는 방법과 6 ÷ 3을 이용하는 방법으로 각각 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C1","difficulty":4,"kind":"essay","stem":"봉사 활동을 가는 학생 60명이 버스 3대에 똑같이 나누어 타요. 60 ÷ 3을 10 카드로 구하는 방법과 6 ÷ 3을 이용하는 방법으로 각각 설명해 보세요.","answer_guide":{"answer":"예: ① 60은 10 카드 6장이다. 6장을 3곳에 한 장씩 놓으면 한 곳에 2장씩이고, 10 카드 2장은 20이다. ② 6 ÷ 3 = 2이고 60은 6의 10배이므로 몫도 10배가 되어 20이다. 한 대에 20명씩 탄다.","scoring_points":["10 카드 6장을 3곳에 나누어 20을 구했는가","6 ÷ 3 = 2의 10배로 설명했는가","한 대에 20명이라고 답했는가"]},"explanation":["10 카드 6장 → 3곳에 2장씩 = 20.","6 ÷ 3 = 2 → 10배 20.","60 ÷ 3 = 20."],"asset":{"type":"ldiv","a":60,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#9','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'essay','teacher','은우는 80 ÷ 2 = 4라고 했어요. 은우의 답이 맞는지 판단하고, 바른 몫을 구해 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C1","difficulty":4,"kind":"essay","stem":"은우는 80 ÷ 2 = 4라고 했어요. 은우의 답이 맞는지 판단하고, 바른 몫을 구해 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 80은 10 카드 8장이므로 2곳에 나누면 한 곳에 10 카드 4장, 곧 40이다. 8 ÷ 2 = 4의 10배이므로 몫도 40이다. 몫의 일의 자리에 0을 써야 한다. 확인하면 2 × 40 = 80이다.","scoring_points":["틀렸다고 판단했는가","몫이 10배인 40이라고 설명했는가","2 × 40 = 80으로 확인했는가"]},"explanation":["8 ÷ 2 = 4.","80은 8의 10배 → 몫 40.","2 × 40 = 80."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L02_challenge#10','math',3,2,'u2','L02','g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'sa','auto','어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 320이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C1","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 320이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["어떤 수 × 4 = 320 → 어떤 수는 320 ÷ 4 = 80이에요.","바르게 계산하면 80 ÷ 4.","80 ÷ 4 = 20 — 몫은 20이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 270이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["어떤 수 × 3 = 270 → 어떤 수는 270 ÷ 3 = 90이에요.","바르게 계산하면 90 ÷ 3.","90 ÷ 3 = 30 — 몫은 30이에요."],"asset":null},{"stem":"어떤 수를 2로 나누어야 하는데 잘못하여 2를 곱했더니 120이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["어떤 수 × 2 = 120 → 어떤 수는 120 ÷ 2 = 60이에요.","바르게 계산하면 60 ÷ 2.","60 ÷ 2 = 30 — 몫은 30이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#1','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'sa','auto','30 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"30 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 확인: 2 × 15 = 30이에요."],"variant_rule":{"alt":[{"stem":"70 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 확인: 5 × 14 = 70이에요."],"asset":null},{"stem":"50 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 확인: 2 × 25 = 50이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#2','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'sa','auto','30 ÷ 2를 10 카드로 나누어요. 10 카드 3장을 2곳에 한 장씩 놓고 남은 10 카드 1장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"30 ÷ 2를 10 카드로 나누어요. 10 카드 3장을 2곳에 한 장씩 놓고 남은 10 카드 1장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["10 카드 3장을 2곳에 나누면 한 곳에 1장씩, 1장이 남아요.","남은 10 카드 1장 = 1 카드 10장.","1 카드 10장을 2곳에 나누면 5장씩 — 한 곳에 10 + 5 = 15예요."],"variant_rule":{"alt":[{"stem":"90 ÷ 5를 10 카드로 나누어요. 10 카드 9장을 5곳에 한 장씩 놓고 남은 10 카드 4장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["10 카드 9장을 5곳에 나누면 한 곳에 1장씩, 4장이 남아요.","남은 10 카드 4장 = 1 카드 40장.","1 카드 40장을 5곳에 나누면 8장씩 — 한 곳에 10 + 8 = 18이에요."],"asset":null},{"stem":"80 ÷ 5를 10 카드로 나누어요. 10 카드 8장을 5곳에 한 장씩 놓고 남은 10 카드 3장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["10 카드 8장을 5곳에 나누면 한 곳에 1장씩, 3장이 남아요.","남은 10 카드 3장 = 1 카드 30장.","1 카드 30장을 5곳에 나누면 6장씩 — 한 곳에 10 + 6 = 16이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#3','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'mc','auto','50 ÷ 2는 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"mc","stem":"50 ÷ 2는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"20","mis":"M3-2-u2-X03"},{"t":"26","mis":"M3-2-u2-X15"},{"t":"24","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 확인: 2 × 25 = 50이에요."],"variant_rule":{"alt":[{"stem":"30 ÷ 2는 얼마인가요?","options":[{"t":"15","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"16","mis":"M3-2-u2-X15"},{"t":"14","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 확인: 2 × 15 = 30이에요."],"asset":null},{"stem":"80 ÷ 5는 얼마인가요?","options":[{"t":"16","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"17","mis":"M3-2-u2-X15"},{"t":"15","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 확인: 5 × 16 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#4','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'mc','auto','70 ÷ 5를 10 카드로 나누면 한 곳에 놓이는 카드는 어느 것인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X06']::text[],true,'{"seq":4,"concept":"M3-2-u2-C2","difficulty":1,"kind":"mc","stem":"70 ÷ 5를 10 카드로 나누면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 1장, 1 카드 4장","correct":true},{"t":"10 카드 1장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 4장, 1 카드 1장","mis":"M3-2-u2-X04"},{"t":"10 카드 1장, 1 카드 2장","mis":"M3-2-u2-X06"}],"explanation":["10 카드 7장을 5곳에 나누면 1장씩, 2장 남아요.","남은 2장을 1 카드 20장으로 바꾸어 나누면 4장씩.","한 곳에 10 카드 1장, 1 카드 4장 — 14예요."],"variant_rule":{"alt":[{"stem":"90 ÷ 2를 10 카드로 나누면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 4장, 1 카드 5장","correct":true},{"t":"10 카드 4장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 5장, 1 카드 4장","mis":"M3-2-u2-X04"},{"t":"10 카드 4장, 1 카드 1장","mis":"M3-2-u2-X06"}],"explanation":["10 카드 9장을 2곳에 나누면 4장씩, 1장 남아요.","남은 1장을 1 카드 10장으로 바꾸어 나누면 5장씩.","한 곳에 10 카드 4장, 1 카드 5장 — 45예요."],"asset":null},{"stem":"80 ÷ 5를 10 카드로 나누면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 1장, 1 카드 6장","correct":true},{"t":"10 카드 1장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 6장, 1 카드 1장","mis":"M3-2-u2-X04"},{"t":"10 카드 1장, 1 카드 3장","mis":"M3-2-u2-X06"}],"explanation":["10 카드 8장을 5곳에 나누면 1장씩, 3장 남아요.","남은 3장을 1 카드 30장으로 바꾸어 나누면 6장씩.","한 곳에 10 카드 1장, 1 카드 6장 — 16이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#5','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'sa','auto','70 ÷ 5를 50과 20으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"70 ÷ 5를 50과 20으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["14"],"explanation":["70을 50과 20으로 갈라요 — 둘 다 5로 나누어떨어져요.","50 ÷ 5 = 10, 20 ÷ 5 = 4예요.","10 + 4 = 14 — 70 ÷ 5의 몫이에요."],"asset":{"type":"expr_grid","rows":[["50 ÷ 5","=","10"],["20 ÷ 5","=","4"],["10 + 4","=",null]]},"variant_rule":{"alt":[{"stem":"70 ÷ 2를 60과 10으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["70을 60과 10으로 갈라요 — 둘 다 2로 나누어떨어져요.","60 ÷ 2 = 30, 10 ÷ 2 = 5예요.","30 + 5 = 35 — 70 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 2","=","30"],["10 ÷ 2","=",null],["30 + □","=","35"]]}},{"stem":"60 ÷ 5를 50과 10으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["60을 50과 10으로 갈라요 — 둘 다 5로 나누어떨어져요.","50 ÷ 5 = 10, 10 ÷ 5 = 2예요.","10 + 2 = 12 — 60 ÷ 5의 몫이에요."],"asset":{"type":"expr_grid","rows":[["50 ÷ 5","=",null],["10 ÷ 5","=","2"],["□ + 2","=","12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#6','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'mc','auto','금잔화 모종 30개를 화단 2곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03']::text[],true,'{"seq":6,"concept":"M3-2-u2-C2","difficulty":2,"kind":"mc","stem":"금잔화 모종 30개를 화단 2곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?","options":[{"t":"15개","correct":true},{"t":"28개","mis":"M3-2-u2-X14"},{"t":"60개","mis":"M3-2-u2-X14"},{"t":"10개","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 30 ÷ 2로 세워요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 15개예요."],"variant_rule":{"alt":[{"stem":"손수건 70장을 5명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요?","options":[{"t":"14장","correct":true},{"t":"65장","mis":"M3-2-u2-X14"},{"t":"350장","mis":"M3-2-u2-X14"},{"t":"10장","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 70 ÷ 5로 세워요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 14장이에요."],"asset":null},{"stem":"약과 50개를 어르신 2분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요?","options":[{"t":"25개","correct":true},{"t":"48개","mis":"M3-2-u2-X14"},{"t":"100개","mis":"M3-2-u2-X14"},{"t":"20개","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 50 ÷ 2로 세워요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 25개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#7','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'ox','auto','30 ÷ 2 = 10이에요.',ARRAY['M3-2-u2-X03']::text[],true,'{"seq":7,"concept":"M3-2-u2-C2","difficulty":2,"kind":"ox","stem":"30 ÷ 2 = 10이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"mis":"M3-2-u2-X03","explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 30 ÷ 2 = 15.","남은 수는 아래로 내리기 — 확인: 2 × 15 = 30이에요."],"asset":{"type":"ldiv","a":30,"b":2,"upto":0},"variant_rule":{"alt":[{"stem":"90 ÷ 5 = 10이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","바르게 계산하면 90 ÷ 5 = 18.","남은 수는 아래로 내리기 — 확인: 5 × 18 = 90이에요."],"asset":{"type":"ldiv","a":90,"b":5,"upto":0}},{"stem":"50 ÷ 2 = 20이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 50 ÷ 2 = 25.","남은 수는 아래로 내리기 — 확인: 2 × 25 = 50이에요."],"asset":{"type":"ldiv","a":50,"b":2,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#8','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'sa','auto','80 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"80 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":80,"b":5,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"60 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 4 → 몫 5.","60 ÷ 4 = 15 — 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":60,"b":4,"hide":[["q",0]]}},{"stem":"90 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":90,"b":6,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#9','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C2","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"50 ÷ 2","r":"25"},{"l":"90 ÷ 5","r":"18"},{"l":"70 ÷ 5","r":"14"}],"mis":"M3-2-u2-X03","explanation":["높은 자리부터 차례로 나누어요.","50 ÷ 2 = 25, 90 ÷ 5 = 18, 70 ÷ 5 = 14.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"90 ÷ 6","r":"15"},{"l":"90 ÷ 5","r":"18"},{"l":"80 ÷ 5","r":"16"}],"explanation":["높은 자리부터 차례로 나누어요.","90 ÷ 6 = 15, 90 ÷ 5 = 18, 80 ÷ 5 = 16.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"90 ÷ 2","r":"45"},{"l":"80 ÷ 5","r":"16"},{"l":"70 ÷ 5","r":"14"}],"explanation":["높은 자리부터 차례로 나누어요.","90 ÷ 2 = 45, 80 ÷ 5 = 16, 70 ÷ 5 = 14.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_basic#10','math',3,2,'u2','L03','g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',3,'error','auto','90 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"90 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「90 ÷ 6 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지유 — 「90 ÷ 6 = 15야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「90 ÷ 6은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15.","하랑이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"70 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「70 ÷ 5 = 15야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"서윤 — 「70 ÷ 5 = 14야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「확인하면 5 × 14 = 70이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14.","하랑이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"30 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「30 ÷ 2 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지유 — 「30 ÷ 2 = 15야」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「30 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15.","하랑이 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#1','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',2,'sa','auto','70 ÷ 5에서 십의 자리 7을 5로 나누면 몫 1이 서고 2가 남아요. 남은 2를 일의 자리 0과 함께 보면 몇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"70 ÷ 5에서 십의 자리 7을 5로 나누면 몫 1이 서고 2가 남아요. 남은 2를 일의 자리 0과 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["남은 2는 십의 자리에서 남은 것이라 20을 뜻해요.","20 + 0 = 20이에요.","20 ÷ 5 = 4 — 몫은 1과 4를 이어 14예요."],"asset":{"type":"ldiv","a":70,"b":5,"hide":[["r",1]]},"variant_rule":{"alt":[{"stem":"70 ÷ 2에서 십의 자리 7을 2로 나누면 몫 3이 서고 1이 남아요. 남은 1을 일의 자리 0과 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["남은 1은 십의 자리에서 남은 것이라 10을 뜻해요.","10 + 0 = 10이에요.","10 ÷ 2 = 5 — 몫은 3과 5를 이어 35예요."],"asset":{"type":"ldiv","a":70,"b":2,"hide":[["r",1]]}},{"stem":"50 ÷ 2에서 십의 자리 5를 2로 나누면 몫 2가 서고 1이 남아요. 남은 1을 일의 자리 0과 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["남은 1은 십의 자리에서 남은 것이라 10을 뜻해요.","10 + 0 = 10이에요.","10 ÷ 2 = 5 — 몫은 2와 5를 이어 25예요."],"asset":{"type":"ldiv","a":50,"b":2,"hide":[["r",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#2','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',2,'sa','auto','봉사 활동을 가는 학생 80명이 버스 5대에 똑같이 나누어 타려고 해요. 한 대에 몇 명씩 타나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"봉사 활동을 가는 학생 80명이 버스 5대에 똑같이 나누어 타려고 해요. 한 대에 몇 명씩 타나요? 숫자로 쓰세요.","answer":["16"],"explanation":["똑같이 나누는 상황 — 나눗셈식 80 ÷ 5로 세워요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 16명이에요."],"variant_rule":{"alt":[{"stem":"봉사 활동 배지 30개를 2모둠에 똑같이 나누어 주려고 해요. 한 모둠은 몇 개를 받나요? 숫자로 쓰세요.","answer":["15"],"explanation":["똑같이 나누는 상황 — 나눗셈식 30 ÷ 2로 세워요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 15개예요."],"asset":null},{"stem":"금잔화 모종 70개를 화단 2곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요? 숫자로 쓰세요.","answer":["35"],"explanation":["똑같이 나누는 상황 — 나눗셈식 70 ÷ 2로 세워요.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","70 ÷ 2 = 35 — 35개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#3','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 70 ÷ 5 ○ 90 ÷ 6',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 70 ÷ 5 ○ 90 ÷ 6","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["70 ÷ 5의 몫은 14예요.","90 ÷ 6의 몫은 15예요.","14 < 15 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 50 ÷ 2 ○ 60 ÷ 5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["50 ÷ 2의 몫은 25예요.","60 ÷ 5의 몫은 12예요.","25 > 12 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 30 ÷ 2 ○ 60 ÷ 5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["30 ÷ 2의 몫은 15예요.","60 ÷ 5의 몫은 12예요.","15 > 12 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#4','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'sa','auto','시우가 90 ÷ 5를 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C2","difficulty":3,"kind":"sa","stem":"시우가 90 ÷ 5를 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["시우 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","바른 몫은 18 — 확인: 5 × 18 = 90이에요."],"variant_rule":{"alt":[{"stem":"시우가 90 ÷ 6을 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["시우 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","바른 몫은 15 — 확인: 6 × 15 = 90이에요."],"asset":null},{"stem":"지유가 70 ÷ 2를 계산하고 몫을 30이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["지유 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바른 몫은 35 — 확인: 2 × 35 = 70이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#5','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'sa','auto','90 ÷ 6의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C2","difficulty":3,"kind":"sa","stem":"90 ÷ 6의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 5를 세운 자리 — 6 × 5 = 30이에요.","90 ÷ 6 = 15 — 확인: 6 × 15 = 90이에요."],"asset":{"type":"ldiv","a":90,"b":6,"hide":[["r",2]]},"variant_rule":{"alt":[{"stem":"30 ÷ 2의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 5를 세운 자리 — 2 × 5 = 10이에요.","30 ÷ 2 = 15 — 확인: 2 × 15 = 30이에요."],"asset":{"type":"ldiv","a":30,"b":2,"hide":[["r",2]]}},{"stem":"90 ÷ 5의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 8을 세운 자리 — 5 × 8 = 40이에요.","90 ÷ 5 = 18 — 확인: 5 × 18 = 90이에요."],"asset":{"type":"ldiv","a":90,"b":5,"hide":[["r",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#6','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'error','auto','70 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"70 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「70 ÷ 2 = 30이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"서윤 — 「70 ÷ 2 = 35야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「70 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","70 ÷ 2 = 35.","태오가 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"60 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「60 ÷ 4 = 16이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"하랑 — 「60 ÷ 4 = 15야」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「확인하면 4 × 15 = 60이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 4 → 몫 5.","60 ÷ 4 = 15.","도윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「60 ÷ 5 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"시우 — 「60 ÷ 5 = 12야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「60 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","60 ÷ 5 = 12.","은우가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#7','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'sa','auto','어떤 수를 2로 나누어야 하는데 잘못하여 2를 곱했더니 60이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C2","difficulty":3,"kind":"sa","stem":"어떤 수를 2로 나누어야 하는데 잘못하여 2를 곱했더니 60이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["어떤 수 × 2 = 60 → 어떤 수는 60 ÷ 2 = 30이에요.","바르게 계산하면 30 ÷ 2.","30 ÷ 2 = 15 — 몫은 15예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 2로 나누어야 하는데 잘못하여 2를 곱했더니 100이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["어떤 수 × 2 = 100 → 어떤 수는 100 ÷ 2 = 50이에요.","바르게 계산하면 50 ÷ 2.","50 ÷ 2 = 25 — 몫은 25예요."],"asset":null},{"stem":"어떤 수를 5로 나누어야 하는데 잘못하여 5를 곱했더니 350이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["어떤 수 × 5 = 350 → 어떤 수는 350 ÷ 5 = 70이에요.","바르게 계산하면 70 ÷ 5.","70 ÷ 5 = 14 — 몫은 14예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#8','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'essay','teacher','금잔화 모종 30개를 화단 2곳에 똑같이 나누어 심어요. 10 카드와 1 카드를 써서 30 ÷ 2를 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C2","difficulty":4,"kind":"essay","stem":"금잔화 모종 30개를 화단 2곳에 똑같이 나누어 심어요. 10 카드와 1 카드를 써서 30 ÷ 2를 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30은 10 카드 3장이다. 2곳에 한 장씩 놓으면 한 곳에 1장씩 놓이고 1장이 남는다. 남은 10 카드 1장을 1 카드 10장으로 바꾸어 2곳에 나누면 5장씩이다. 한 곳에 10 카드 1장과 1 카드 5장, 곧 15개씩 심는다.","scoring_points":["10 카드 3장을 나누고 1장이 남는다고 했는가","남은 10 카드를 1 카드 10장으로 바꾸어 나누었는가","15개라고 답했는가"]},"explanation":["10 카드 3장 → 2곳에 1장씩, 1장 남음.","1 카드 10장 → 2곳에 5장씩.","10 + 5 = 15."],"asset":{"type":"ldiv","a":30,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#9','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'essay','teacher','시우는 70 ÷ 5를 「7 ÷ 5 = 1 … 2이니 몫은 10」이라고 했어요. 시우가 무엇을 빠뜨렸는지 찾고 바른 몫을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C2","difficulty":4,"kind":"essay","stem":"시우는 70 ÷ 5를 「7 ÷ 5 = 1 … 2이니 몫은 10」이라고 했어요. 시우가 무엇을 빠뜨렸는지 찾고 바른 몫을 구해 보세요.","answer_guide":{"answer":"예: 십의 자리에서 남은 2를 버렸다. 남은 2는 20을 뜻하므로 일의 자리로 내려 20 ÷ 5 = 4를 더 구해야 한다. 몫은 10 + 4 = 14이다. 확인하면 5 × 14 = 70이다.","scoring_points":["남은 2(20)를 내리지 않았다고 찾았는가","20 ÷ 5 = 4를 구했는가","14를 구하고 확인했는가"]},"explanation":["7 ÷ 5 = 1 … 2 — 남은 2는 20.","20 ÷ 5 = 4.","70 ÷ 5 = 14 — 5 × 14 = 70."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L03_challenge#10','math',3,2,'u2','L03','g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'sa','auto','어떤 수를 5로 나누었더니 몫이 18이고 나누어떨어졌어요. 어떤 수를 6으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C2","difficulty":4,"kind":"sa","stem":"어떤 수를 5로 나누었더니 몫이 18이고 나누어떨어졌어요. 어떤 수를 6으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["어떤 수 = 5 × 18 = 90이에요.","90 ÷ 6 — 십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 몫은 15예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 2로 나누었더니 몫이 35이고 나누어떨어졌어요. 어떤 수를 5로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["어떤 수 = 2 × 35 = 70이에요.","70 ÷ 5 — 십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 몫은 14예요."],"asset":null},{"stem":"어떤 수를 6으로 나누었더니 몫이 15이고 나누어떨어졌어요. 어떤 수를 5로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["어떤 수 = 6 × 15 = 90이에요.","90 ÷ 5 — 십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","90 ÷ 5 = 18 — 몫은 18이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#1','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'sa','auto','26 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"26 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 6 ÷ 2 → 몫 3.","26 ÷ 2 = 13 — 확인: 2 × 13 = 26이에요."],"variant_rule":{"alt":[{"stem":"64 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 4 ÷ 2 → 몫 2.","64 ÷ 2 = 32 — 확인: 2 × 32 = 64예요."],"asset":null},{"stem":"66 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 6 ÷ 2 → 몫 3.","66 ÷ 2 = 33 — 확인: 2 × 33 = 66이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#2','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'mc','auto','93 ÷ 3은 얼마인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"93 ÷ 3은 얼마인가요?","options":[{"t":"31","correct":true},{"t":"13","mis":"M3-2-u2-X04"},{"t":"32","mis":"M3-2-u2-X15"},{"t":"30","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","93 ÷ 3 = 31 — 확인: 3 × 31 = 93이에요."],"variant_rule":{"alt":[{"stem":"48 ÷ 4는 얼마인가요?","options":[{"t":"12","correct":true},{"t":"21","mis":"M3-2-u2-X04"},{"t":"13","mis":"M3-2-u2-X15"},{"t":"11","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 4 → 몫 1 · 일의 자리 8 ÷ 4 → 몫 2.","48 ÷ 4 = 12 — 확인: 4 × 12 = 48이에요."],"asset":null},{"stem":"68 ÷ 2는 얼마인가요?","options":[{"t":"34","correct":true},{"t":"43","mis":"M3-2-u2-X04"},{"t":"35","mis":"M3-2-u2-X15"},{"t":"33","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 8 ÷ 2 → 몫 4.","68 ÷ 2 = 34 — 확인: 2 × 34 = 68이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#3','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C4',1,'mc','auto','26 ÷ 2를 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":3,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"26 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 10 = 20, 2 × 20 = 40 — 26은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 13이에요."],"variant_rule":{"alt":[{"stem":"44 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"20과 30 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"30보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 300 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 20 = 40, 2 × 30 = 60 — 44는 그 사이에 있어요.","그래서 몫은 20과 30 사이 — 실제 몫 22예요."],"asset":null},{"stem":"39 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 39는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 13이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#4','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'sa','auto','84 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"84 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","84 ÷ 4 = 21 — 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":84,"b":4,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"99 ÷ 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 9 ÷ 3 → 몫 3.","99 ÷ 3 = 33 — 일의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":99,"b":3,"hide":[["q",1]]}},{"stem":"84 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 4 ÷ 2 → 몫 2.","84 ÷ 2 = 42 — 일의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":84,"b":2,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#5','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'mc','auto','금잔화 모종 39개를 화단 3곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X04']::text[],true,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":2,"kind":"mc","stem":"금잔화 모종 39개를 화단 3곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?","options":[{"t":"13개","correct":true},{"t":"36개","mis":"M3-2-u2-X14"},{"t":"117개","mis":"M3-2-u2-X14"},{"t":"31개","mis":"M3-2-u2-X04"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 39 ÷ 3으로 세워요.","십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 9 ÷ 3 → 몫 3.","39 ÷ 3 = 13 — 13개예요."],"variant_rule":{"alt":[{"stem":"손수건 69장을 3명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요?","options":[{"t":"23장","correct":true},{"t":"66장","mis":"M3-2-u2-X14"},{"t":"207장","mis":"M3-2-u2-X14"},{"t":"32장","mis":"M3-2-u2-X04"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 69 ÷ 3으로 세워요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 9 ÷ 3 → 몫 3.","69 ÷ 3 = 23 — 23장이에요."],"asset":null},{"stem":"약과 86개를 어르신 2분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요?","options":[{"t":"43개","correct":true},{"t":"84개","mis":"M3-2-u2-X14"},{"t":"172개","mis":"M3-2-u2-X14"},{"t":"34개","mis":"M3-2-u2-X04"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 86 ÷ 2로 세워요.","십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 6 ÷ 2 → 몫 3.","86 ÷ 2 = 43 — 43개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#6','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'ox','auto','93 ÷ 3 = 13이에요.',ARRAY['M3-2-u2-X04']::text[],true,'{"seq":6,"concept":"M3-2-u2-C3","difficulty":2,"kind":"ox","stem":"93 ÷ 3 = 13이에요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"mis":"M3-2-u2-X04","explanation":["십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","바르게 계산하면 93 ÷ 3 = 31.","높은 자리부터 그 자리 위에 — 확인: 3 × 31 = 93이에요."],"variant_rule":{"alt":[{"stem":"48 ÷ 2 = 42예요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"explanation":["십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 8 ÷ 2 → 몫 4.","바르게 계산하면 48 ÷ 2 = 24.","높은 자리부터 그 자리 위에 — 확인: 2 × 24 = 48이에요."],"asset":null},{"stem":"62 ÷ 2 = 13이에요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"explanation":["십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 2 ÷ 2 → 몫 1.","바르게 계산하면 62 ÷ 2 = 31.","높은 자리부터 그 자리 위에 — 확인: 2 × 31 = 62예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#7','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C4',2,'ox','auto','84 ÷ 4를 계산했더니 몫이 210이 나왔어요. 어림해 보면 알맞은 몫이에요.',ARRAY['M3-2-u2-X16']::text[],true,'{"seq":7,"concept":"M3-2-u2-C4","difficulty":2,"kind":"ox","stem":"84 ÷ 4를 계산했더니 몫이 210이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"mis":"M3-2-u2-X16","explanation":["4 × 20 = 80, 4 × 30 = 120 — 몫은 20과 30 사이예요.","210은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 21 — 확인: 4 × 21 = 84예요."],"variant_rule":{"alt":[{"stem":"62 ÷ 2를 계산했더니 몫이 310이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["2 × 30 = 60, 2 × 40 = 80 — 몫은 30과 40 사이예요.","310은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 31 — 확인: 2 × 31 = 62예요."],"asset":null},{"stem":"46 ÷ 2를 계산했더니 몫이 230이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["2 × 20 = 40, 2 × 30 = 60 — 몫은 20과 30 사이예요.","230은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 23 — 확인: 2 × 23 = 46이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#8','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'sa','auto','84 ÷ 4를 80과 4로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"84 ÷ 4를 80과 4로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["84를 80과 4로 갈라요 — 둘 다 4로 나누어떨어져요.","80 ÷ 4 = 20, 4 ÷ 4 = 1이에요.","20 + 1 = 21 — 84 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["80 ÷ 4","=","20"],["4 ÷ 4","=",null],["20 + □","=","21"]]},"variant_rule":{"alt":[{"stem":"82 ÷ 2를 80과 2로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["82를 80과 2로 갈라요 — 둘 다 2로 나누어떨어져요.","80 ÷ 2 = 40, 2 ÷ 2 = 1이에요.","40 + 1 = 41 — 82 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["80 ÷ 2","=",null],["2 ÷ 2","=","1"],["□ + 1","=","41"]]}},{"stem":"63 ÷ 3을 60과 3으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["21"],"explanation":["63을 60과 3으로 갈라요 — 둘 다 3으로 나누어떨어져요.","60 ÷ 3 = 20, 3 ÷ 3 = 1이에요.","20 + 1 = 21 — 63 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 3","=","20"],["3 ÷ 3","=","1"],["20 + 1","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#9','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C3","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"62 ÷ 2","r":"31"},{"l":"84 ÷ 2","r":"42"},{"l":"66 ÷ 6","r":"11"}],"mis":"M3-2-u2-X04","explanation":["높은 자리부터 차례로 나누어요.","62 ÷ 2 = 31, 84 ÷ 2 = 42, 66 ÷ 6 = 11.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"99 ÷ 3","r":"33"},{"l":"26 ÷ 2","r":"13"},{"l":"84 ÷ 4","r":"21"}],"explanation":["높은 자리부터 차례로 나누어요.","99 ÷ 3 = 33, 26 ÷ 2 = 13, 84 ÷ 4 = 21.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"66 ÷ 6","r":"11"},{"l":"93 ÷ 3","r":"31"},{"l":"88 ÷ 2","r":"44"}],"explanation":["높은 자리부터 차례로 나누어요.","66 ÷ 6 = 11, 93 ÷ 3 = 31, 88 ÷ 2 = 44.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_basic#10','math',3,2,'u2','L04','g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',3,'error','auto','96 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C3","difficulty":3,"kind":"error","stem":"96 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「96 ÷ 3 = 33이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「96 ÷ 3 = 32야」","mis":"M3-2-u2-X17"},{"t":"은우 — 「확인하면 3 × 32 = 96이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 6 ÷ 3 → 몫 2.","96 ÷ 3 = 32.","하린이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"99 ÷ 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「99 ÷ 9 = 12야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"하린 — 「99 ÷ 9 = 11이야」","mis":"M3-2-u2-X17"},{"t":"지유 — 「99 ÷ 9는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 9 ÷ 9 → 몫 1.","99 ÷ 9 = 11.","하랑이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"68 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「68 ÷ 2 = 35야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"도윤 — 「68 ÷ 2 = 34야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「확인하면 2 × 34 = 68이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 8 ÷ 2 → 몫 4.","68 ÷ 2 = 34.","태오가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#1','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C4',2,'ox','auto','39 ÷ 3을 계산했더니 몫이 130이 나왔어요. 어림해 보면 알맞은 몫이에요.',ARRAY['M3-2-u2-X16']::text[],true,'{"seq":1,"concept":"M3-2-u2-C4","difficulty":2,"kind":"ox","stem":"39 ÷ 3을 계산했더니 몫이 130이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"mis":"M3-2-u2-X16","explanation":["3 × 10 = 30, 3 × 20 = 60 — 몫은 10과 20 사이예요.","130은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 13 — 확인: 3 × 13 = 39예요."],"variant_rule":{"alt":[{"stem":"66 ÷ 3을 계산했더니 몫이 220이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["3 × 20 = 60, 3 × 30 = 90 — 몫은 20과 30 사이예요.","220은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 22 — 확인: 3 × 22 = 66이에요."],"asset":null},{"stem":"62 ÷ 2를 계산했더니 몫이 310이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["2 × 30 = 60, 2 × 40 = 80 — 몫은 30과 40 사이예요.","310은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 31 — 확인: 2 × 31 = 62예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#2','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',2,'sa','auto','손수건 88장을 4명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"손수건 88장을 4명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요? 숫자로 쓰세요.","answer":["22"],"explanation":["똑같이 나누는 상황 — 나눗셈식 88 ÷ 4로 세워요.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 8 ÷ 4 → 몫 2.","88 ÷ 4 = 22 — 22장이에요."],"variant_rule":{"alt":[{"stem":"약과 39개를 어르신 3분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요? 숫자로 쓰세요.","answer":["13"],"explanation":["똑같이 나누는 상황 — 나눗셈식 39 ÷ 3으로 세워요.","십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 9 ÷ 3 → 몫 3.","39 ÷ 3 = 13 — 13개예요."],"asset":null},{"stem":"도서관 책 68권을 책장 2칸에 똑같이 나누어 꽂으려고 해요. 한 칸에 몇 권씩 꽂나요? 숫자로 쓰세요.","answer":["34"],"explanation":["똑같이 나누는 상황 — 나눗셈식 68 ÷ 2로 세워요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 8 ÷ 2 → 몫 4.","68 ÷ 2 = 34 — 34권이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#3','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 69 ÷ 3 ○ 88 ÷ 4',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C3","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 69 ÷ 3 ○ 88 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["69 ÷ 3의 몫은 23이에요.","88 ÷ 4의 몫은 22예요.","23 > 22 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 39 ÷ 3 ○ 55 ÷ 5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["39 ÷ 3의 몫은 13이에요.","55 ÷ 5의 몫은 11이에요.","13 > 11 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 28 ÷ 2 ○ 48 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["28 ÷ 2의 몫은 14예요.","48 ÷ 4의 몫은 12예요.","14 > 12 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#4','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'sa','auto','지유가 84 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":3,"kind":"sa","stem":"지유가 84 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["지유 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","바른 몫은 21 — 확인: 4 × 21 = 84예요."],"variant_rule":{"alt":[{"stem":"지유가 64 ÷ 2를 계산하고 몫을 23이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["지유 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 4 ÷ 2 → 몫 2.","바른 몫은 32 — 확인: 2 × 32 = 64예요."],"asset":null},{"stem":"서윤이 46 ÷ 2를 계산하고 몫을 32라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["서윤 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 6 ÷ 2 → 몫 3.","바른 몫은 23 — 확인: 2 × 23 = 46이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#5','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'sa','auto','96 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":3,"kind":"sa","stem":"96 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 2를 세운 자리 — 3 × 2 = 6이에요.","96 ÷ 3 = 32 — 확인: 3 × 32 = 96이에요."],"asset":{"type":"ldiv","a":96,"b":3,"hide":[["r",2]]},"variant_rule":{"alt":[{"stem":"84 ÷ 4의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 1을 세운 자리 — 4 × 1 = 4예요.","84 ÷ 4 = 21 — 확인: 4 × 21 = 84예요."],"asset":{"type":"ldiv","a":84,"b":4,"hide":[["r",2]]}},{"stem":"28 ÷ 2의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 4를 세운 자리 — 2 × 4 = 8이에요.","28 ÷ 2 = 14 — 확인: 2 × 14 = 28이에요."],"asset":{"type":"ldiv","a":28,"b":2,"hide":[["r",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#6','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'error','auto','48 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C3","difficulty":3,"kind":"error","stem":"48 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「48 ÷ 4 = 13이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「48 ÷ 4 = 12야」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「확인하면 4 × 12 = 48이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 4 ÷ 4 → 몫 1 · 일의 자리 8 ÷ 4 → 몫 2.","48 ÷ 4 = 12.","은우가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"22 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「22 ÷ 2 = 12야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"은우 — 「22 ÷ 2 = 11이야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「22 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 2 ÷ 2 → 몫 1.","22 ÷ 2 = 11.","하린이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"42 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「42 ÷ 2 = 22야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「42 ÷ 2 = 21이야」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「확인하면 2 × 21 = 42야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 2 ÷ 2 → 몫 1.","42 ÷ 2 = 21.","은우가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#7','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C4',3,'mc','auto','66 ÷ 3을 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":7,"concept":"M3-2-u2-C4","difficulty":3,"kind":"mc","stem":"66 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"20과 30 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"30보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 300 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 20 = 60, 3 × 30 = 90 — 66은 그 사이에 있어요.","그래서 몫은 20과 30 사이 — 실제 몫 22예요."],"variant_rule":{"alt":[{"stem":"88 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"40과 50 사이","correct":true},{"t":"40보다 작아요","mis":"M3-2-u2-X16"},{"t":"50보다 커요","mis":"M3-2-u2-X16"},{"t":"400과 500 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 40 = 80, 2 × 50 = 100 — 88은 그 사이에 있어요.","그래서 몫은 40과 50 사이 — 실제 몫 44예요."],"asset":null},{"stem":"26 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 10 = 20, 2 × 20 = 40 — 26은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 13이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#8','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C4',4,'essay','teacher','배지 26개를 2명이 똑같이 나누어 가져요. 계산하기 전에 한 명이 가지는 배지 수를 어림하고, 26 ÷ 2를 계산한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C4","difficulty":4,"kind":"essay","stem":"배지 26개를 2명이 똑같이 나누어 가져요. 계산하기 전에 한 명이 가지는 배지 수를 어림하고, 26 ÷ 2를 계산한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 배지가 20개면 한 명이 10개, 30개면 15개이므로 10개와 15개 사이일 것이다. 십의 자리 2 ÷ 2 = 1, 일의 자리 6 ÷ 2 = 3이므로 몫은 13이다. 13은 어림한 10과 15 사이에 있다.","scoring_points":["20 ÷ 2와 30 ÷ 2로 사이를 어림했는가","자리마다 나누어 13을 구했는가","어림한 사이에 드는지 견주었는가"]},"explanation":["20 ÷ 2 = 10, 30 ÷ 2 = 15.","2 ÷ 2 = 1, 6 ÷ 2 = 3 → 13.","13은 10과 15 사이."],"asset":{"type":"ldiv","a":26,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#9','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',4,'essay','teacher','도윤이는 93 ÷ 3을 13이라고 했어요. 도윤이의 답이 맞는지 판단하고 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C3","difficulty":4,"kind":"essay","stem":"도윤이는 93 ÷ 3을 13이라고 했어요. 도윤이의 답이 맞는지 판단하고 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 십의 자리 9 ÷ 3 = 3은 몫의 십의 자리에, 일의 자리 3 ÷ 3 = 1은 몫의 일의 자리에 써야 하므로 몫은 31이다. 도윤이는 몫을 거꾸로 썼다. 3 × 13 = 39이므로 93이 아니다.","scoring_points":["틀렸다고 판단했는가","몫을 자리에 맞추어 31로 구했는가","곱셈으로 확인했는가"]},"explanation":["9 ÷ 3 = 3 → 몫의 십의 자리.","3 ÷ 3 = 1 → 몫의 일의 자리.","93 ÷ 3 = 31 — 3 × 31 = 93."],"asset":{"type":"ldiv","a":93,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L04_challenge#10','math',3,2,'u2','L04','g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',4,'sa','auto','어떤 수를 3으로 나누었더니 몫이 22이고 나누어떨어졌어요. 어떤 수를 2로 나누면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C3","difficulty":4,"kind":"sa","stem":"어떤 수를 3으로 나누었더니 몫이 22이고 나누어떨어졌어요. 어떤 수를 2로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["어떤 수 = 3 × 22 = 66이에요.","66 ÷ 2 — 십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 6 ÷ 2 → 몫 3.","66 ÷ 2 = 33 — 몫은 33이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 2로 나누었더니 몫이 24이고 나누어떨어졌어요. 어떤 수를 4로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["어떤 수 = 2 × 24 = 48이에요.","48 ÷ 4 — 십의 자리 4 ÷ 4 → 몫 1 · 일의 자리 8 ÷ 4 → 몫 2.","48 ÷ 4 = 12 — 몫은 12예요."],"asset":null},{"stem":"어떤 수를 4로 나누었더니 몫이 21이고 나누어떨어졌어요. 어떤 수를 2로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["어떤 수 = 4 × 21 = 84예요.","84 ÷ 2 — 십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 4 ÷ 2 → 몫 2.","84 ÷ 2 = 42 — 몫은 42예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#1','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'sa','auto','45 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"45 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","45 ÷ 3 = 15 — 확인: 3 × 15 = 45예요."],"variant_rule":{"alt":[{"stem":"64 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 4 → 몫 6.","64 ÷ 4 = 16 — 확인: 4 × 16 = 64예요."],"asset":null},{"stem":"91 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 21 ÷ 7 → 몫 3.","91 ÷ 7 = 13 — 확인: 7 × 13 = 91이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#2','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'sa','auto','52 ÷ 4에서 십의 자리 5를 4로 나누면 몫 1이 서고 1이 남아요. 남은 1을 일의 자리 2와 함께 보면 몇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"52 ÷ 4에서 십의 자리 5를 4로 나누면 몫 1이 서고 1이 남아요. 남은 1을 일의 자리 2와 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["남은 1은 십의 자리에서 남은 것이라 10을 뜻해요.","10 + 2 = 12예요.","12 ÷ 4 = 3 — 몫은 1과 3을 이어 13이에요."],"asset":{"type":"ldiv","a":52,"b":4,"hide":[["r",1]]},"variant_rule":{"alt":[{"stem":"64 ÷ 4에서 십의 자리 6을 4로 나누면 몫 1이 서고 2가 남아요. 남은 2를 일의 자리 4와 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["남은 2는 십의 자리에서 남은 것이라 20을 뜻해요.","20 + 4 = 24예요.","24 ÷ 4 = 6 — 몫은 1과 6을 이어 16이에요."],"asset":{"type":"ldiv","a":64,"b":4,"hide":[["r",1]]}},{"stem":"96 ÷ 6에서 십의 자리 9를 6으로 나누면 몫 1이 서고 3이 남아요. 남은 3을 일의 자리 6과 함께 보면 몇인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["남은 3은 십의 자리에서 남은 것이라 30을 뜻해요.","30 + 6 = 36이에요.","36 ÷ 6 = 6 — 몫은 1과 6을 이어 16이에요."],"asset":{"type":"ldiv","a":96,"b":6,"hide":[["r",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#3','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'mc','auto','87 ÷ 3은 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"mc","stem":"87 ÷ 3은 얼마인가요?","options":[{"t":"29","correct":true},{"t":"22","mis":"M3-2-u2-X03"},{"t":"92","mis":"M3-2-u2-X04"},{"t":"30","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","87 ÷ 3 = 29 — 확인: 3 × 29 = 87이에요."],"variant_rule":{"alt":[{"stem":"54 ÷ 3은 얼마인가요?","options":[{"t":"18","correct":true},{"t":"11","mis":"M3-2-u2-X03"},{"t":"81","mis":"M3-2-u2-X04"},{"t":"19","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 3 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 3 → 몫 8.","54 ÷ 3 = 18 — 확인: 3 × 18 = 54예요."],"asset":null},{"stem":"72 ÷ 2는 얼마인가요?","options":[{"t":"36","correct":true},{"t":"31","mis":"M3-2-u2-X03"},{"t":"63","mis":"M3-2-u2-X04"},{"t":"37","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","72 ÷ 2 = 36 — 확인: 2 × 36 = 72예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#4','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C4',1,'mc','auto','76 ÷ 4를 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":4,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"76 ÷ 4를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","4 × 10 = 40, 4 × 20 = 80 — 76은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 19예요."],"variant_rule":{"alt":[{"stem":"42 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 42는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 14예요."],"asset":null},{"stem":"45 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 45는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 15예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#5','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'sa','auto','36 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"36 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 2 → 몫 8.","36 ÷ 2 = 18 — 일의 자리 숫자는 8이에요."],"asset":{"type":"ldiv","a":36,"b":2,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"52 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","52 ÷ 4 = 13 — 일의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":52,"b":4,"hide":[["q",1]]}},{"stem":"81 ÷ 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 21 ÷ 3 → 몫 7.","81 ÷ 3 = 27 — 일의 자리 숫자는 7이에요."],"asset":{"type":"ldiv","a":81,"b":3,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#6','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'mc','auto','종이꽃 76개를 4개씩 묶어 꽃다발을 만들려고 해요. 꽃다발은 몇 다발이 되나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03']::text[],true,'{"seq":6,"concept":"M3-2-u2-C5","difficulty":2,"kind":"mc","stem":"종이꽃 76개를 4개씩 묶어 꽃다발을 만들려고 해요. 꽃다발은 몇 다발이 되나요?","options":[{"t":"19다발","correct":true},{"t":"72다발","mis":"M3-2-u2-X14"},{"t":"304다발","mis":"M3-2-u2-X14"},{"t":"11다발","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 76 ÷ 4로 세워요.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 36 ÷ 4 → 몫 9.","76 ÷ 4 = 19 — 19다발이에요."],"variant_rule":{"alt":[{"stem":"클립 72개를 6명에게 똑같이 나누어 주려고 해요. 한 명은 몇 개를 받나요?","options":[{"t":"12개","correct":true},{"t":"66개","mis":"M3-2-u2-X14"},{"t":"432개","mis":"M3-2-u2-X14"},{"t":"10개","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 72 ÷ 6으로 세워요.","십의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 6 → 몫 2.","72 ÷ 6 = 12 — 12개예요."],"asset":null},{"stem":"봉사 활동을 가는 학생 96명이 버스 8대에 똑같이 나누어 타려고 해요. 한 대에 몇 명씩 타나요?","options":[{"t":"12명","correct":true},{"t":"88명","mis":"M3-2-u2-X14"},{"t":"768명","mis":"M3-2-u2-X14"},{"t":"10명","mis":"M3-2-u2-X03"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 96 ÷ 8로 세워요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 8 → 몫 2.","96 ÷ 8 = 12 — 12명이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#7','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'ox','auto','45 ÷ 3 = 11이에요.',ARRAY['M3-2-u2-X03']::text[],true,'{"seq":7,"concept":"M3-2-u2-C5","difficulty":2,"kind":"ox","stem":"45 ÷ 3 = 11이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"mis":"M3-2-u2-X03","explanation":["십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","바르게 계산하면 45 ÷ 3 = 15.","남은 수는 아래로 내리기 — 확인: 3 × 15 = 45예요."],"asset":{"type":"ldiv","a":45,"b":3,"upto":0},"variant_rule":{"alt":[{"stem":"34 ÷ 2 = 12예요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 14 ÷ 2 → 몫 7.","바르게 계산하면 34 ÷ 2 = 17.","남은 수는 아래로 내리기 — 확인: 2 × 17 = 34예요."],"asset":{"type":"ldiv","a":34,"b":2,"upto":0}},{"stem":"65 ÷ 5 = 11이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 5 → 몫 3.","바르게 계산하면 65 ÷ 5 = 13.","남은 수는 아래로 내리기 — 확인: 5 × 13 = 65예요."],"asset":{"type":"ldiv","a":65,"b":5,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#8','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'sa','auto','52 ÷ 4를 40과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"52 ÷ 4를 40과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["52를 40과 12로 갈라요 — 둘 다 4로 나누어떨어져요.","40 ÷ 4 = 10, 12 ÷ 4 = 3이에요.","10 + 3 = 13 — 52 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["40 ÷ 4","=",null],["12 ÷ 4","=","3"],["□ + 3","=","13"]]},"variant_rule":{"alt":[{"stem":"48 ÷ 3을 30과 18로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["16"],"explanation":["48을 30과 18로 갈라요 — 둘 다 3으로 나누어떨어져요.","30 ÷ 3 = 10, 18 ÷ 3 = 6이에요.","10 + 6 = 16 — 48 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["30 ÷ 3","=","10"],["18 ÷ 3","=","6"],["10 + 6","=",null]]}},{"stem":"78 ÷ 3을 60과 18로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["78을 60과 18로 갈라요 — 둘 다 3으로 나누어떨어져요.","60 ÷ 3 = 20, 18 ÷ 3 = 6이에요.","20 + 6 = 26 — 78 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 3","=","20"],["18 ÷ 3","=",null],["20 + □","=","26"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#9','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C5","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"72 ÷ 3","r":"24"},{"l":"78 ÷ 2","r":"39"},{"l":"58 ÷ 2","r":"29"}],"mis":"M3-2-u2-X03","explanation":["높은 자리부터 차례로 나누어요.","72 ÷ 3 = 24, 78 ÷ 2 = 39, 58 ÷ 2 = 29.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"76 ÷ 2","r":"38"},{"l":"72 ÷ 6","r":"12"},{"l":"74 ÷ 2","r":"37"}],"explanation":["높은 자리부터 차례로 나누어요.","76 ÷ 2 = 38, 72 ÷ 6 = 12, 74 ÷ 2 = 37.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"54 ÷ 2","r":"27"},{"l":"52 ÷ 2","r":"26"},{"l":"52 ÷ 4","r":"13"}],"explanation":["높은 자리부터 차례로 나누어요.","54 ÷ 2 = 27, 52 ÷ 2 = 26, 52 ÷ 4 = 13.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_basic#10','math',3,2,'u2','L05','g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',3,'error','auto','87 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C5","difficulty":3,"kind":"error","stem":"87 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「87 ÷ 3 = 22야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"도윤 — 「87 ÷ 3 = 29야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「87 ÷ 3은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","87 ÷ 3 = 29.","하린이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"72 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「72 ÷ 3 = 42야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"서윤 — 「72 ÷ 3 = 24야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「확인하면 3 × 24 = 72야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 3 → 몫 4.","72 ÷ 3 = 24.","시우가 잘못 말했어요 — 높은 자리부터 그 자리 위에."],"asset":null},{"stem":"92 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「92 ÷ 4 = 20이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"도윤 — 「92 ÷ 4 = 23이야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「92 ÷ 4는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","92 ÷ 4 = 23.","은우가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#1','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',2,'sa','auto','87 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"87 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["27"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 9를 세운 자리 — 3 × 9 = 27이에요.","87 ÷ 3 = 29 — 확인: 3 × 29 = 87이에요."],"asset":{"type":"ldiv","a":87,"b":3,"hide":[["r",2]]},"variant_rule":{"alt":[{"stem":"58 ÷ 2의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 2를 세운 자리 — 2 × 2 = 4예요.","58 ÷ 2 = 29 — 확인: 2 × 29 = 58이에요."],"asset":{"type":"ldiv","a":58,"b":2,"hide":[["r",0]]}},{"stem":"57 ÷ 3의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["몫을 한 자리 세울 때마다 나누는 수 × 그 몫을 아래에 써서 빼요.","이 줄은 몫 1을 세운 자리 — 3 × 1 = 3이에요.","57 ÷ 3 = 19 — 확인: 3 × 19 = 57이에요."],"asset":{"type":"ldiv","a":57,"b":3,"hide":[["r",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#2','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C4',2,'ox','auto','52 ÷ 4를 계산했더니 몫이 130이 나왔어요. 어림해 보면 알맞은 몫이에요.',ARRAY['M3-2-u2-X16']::text[],true,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":2,"kind":"ox","stem":"52 ÷ 4를 계산했더니 몫이 130이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"mis":"M3-2-u2-X16","explanation":["4 × 10 = 40, 4 × 20 = 80 — 몫은 10과 20 사이예요.","130은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 13 — 확인: 4 × 13 = 52예요."],"variant_rule":{"alt":[{"stem":"75 ÷ 5를 계산했더니 몫이 150이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["5 × 10 = 50, 5 × 20 = 100 — 몫은 10과 20 사이예요.","150은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 15 — 확인: 5 × 15 = 75예요."],"asset":null},{"stem":"96 ÷ 8을 계산했더니 몫이 120이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["8 × 10 = 80, 8 × 20 = 160 — 몫은 10과 20 사이예요.","120은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 12 — 확인: 8 × 12 = 96이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#3','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 72 ÷ 4 ○ 75 ÷ 5',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 72 ÷ 4 ○ 75 ÷ 5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["72 ÷ 4의 몫은 18이에요.","75 ÷ 5의 몫은 15예요.","18 > 15 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 81 ÷ 3 ○ 96 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["81 ÷ 3의 몫은 27이에요.","96 ÷ 4의 몫은 24예요.","27 > 24 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 95 ÷ 5 ○ 64 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["95 ÷ 5의 몫은 19예요.","64 ÷ 4의 몫은 16이에요.","19 > 16 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#4','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','은우가 76 ÷ 4를 계산하고 몫을 11이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"은우가 76 ÷ 4를 계산하고 몫을 11이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["은우 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 36 ÷ 4 → 몫 9.","바른 몫은 19 — 확인: 4 × 19 = 76이에요."],"variant_rule":{"alt":[{"stem":"서윤이 92 ÷ 2를 계산하고 몫을 41이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["서윤 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","바른 몫은 46 — 확인: 2 × 46 = 92예요."],"asset":null},{"stem":"서윤이 91 ÷ 7을 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["서윤 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 21 ÷ 7 → 몫 3.","바른 몫은 13 — 확인: 7 × 13 = 91이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#5','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','도서관 책 95권을 책장 5칸에 똑같이 나누어 꽂으려고 해요. 한 칸에 몇 권씩 꽂나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"도서관 책 95권을 책장 5칸에 똑같이 나누어 꽂으려고 해요. 한 칸에 몇 권씩 꽂나요? 숫자로 쓰세요.","answer":["19"],"explanation":["똑같이 나누는 상황 — 나눗셈식 95 ÷ 5로 세워요.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 45 ÷ 5 → 몫 9.","95 ÷ 5 = 19 — 19권이에요."],"variant_rule":{"alt":[{"stem":"색종이 38장을 2모둠에 똑같이 나누어 주려고 해요. 한 모둠은 몇 장씩 받나요? 숫자로 쓰세요.","answer":["19"],"explanation":["똑같이 나누는 상황 — 나눗셈식 38 ÷ 2로 세워요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 2 → 몫 9.","38 ÷ 2 = 19 — 19장이에요."],"asset":null},{"stem":"옥수수 85개를 5봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 몇 개씩 담나요? 숫자로 쓰세요.","answer":["17"],"explanation":["똑같이 나누는 상황 — 나눗셈식 85 ÷ 5로 세워요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 35 ÷ 5 → 몫 7.","85 ÷ 5 = 17 — 17개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#6','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'error','auto','84 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C5","difficulty":3,"kind":"error","stem":"84 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「84 ÷ 6 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"시우 — 「84 ÷ 6 = 14야」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「84 ÷ 6은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 6 → 몫 4.","84 ÷ 6 = 14.","지유가 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"52 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「52 ÷ 4 = 31이야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"태오 — 「52 ÷ 4 = 13이야」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「확인하면 4 × 13 = 52야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","52 ÷ 4 = 13.","하랑이 잘못 말했어요 — 높은 자리부터 그 자리 위에."],"asset":null},{"stem":"72 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「72 ÷ 2 = 31이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"하랑 — 「72 ÷ 2 = 36이야」","mis":"M3-2-u2-X17"},{"t":"지유 — 「72 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","72 ÷ 2 = 36.","태오가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#7','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 135가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 135가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["어떤 수 × 3 = 135 → 어떤 수는 135 ÷ 3 = 45예요.","바르게 계산하면 45 ÷ 3.","45 ÷ 3 = 15 — 몫은 15예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 208이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["어떤 수 × 4 = 208 → 어떤 수는 208 ÷ 4 = 52예요.","바르게 계산하면 52 ÷ 4.","52 ÷ 4 = 13 — 몫은 13이에요."],"asset":null},{"stem":"어떤 수를 6으로 나누어야 하는데 잘못하여 6을 곱했더니 504가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["어떤 수 × 6 = 504 → 어떤 수는 504 ÷ 6 = 84예요.","바르게 계산하면 84 ÷ 6.","84 ÷ 6 = 14 — 몫은 14예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#8','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'essay','teacher','손수건 45장을 3명이 똑같이 나누어 가져요. 45 ÷ 3을 세로셈으로 계산하는 방법을 쓰고, 십의 자리에서 남은 수를 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C5","difficulty":4,"kind":"essay","stem":"손수건 45장을 3명이 똑같이 나누어 가져요. 45 ÷ 3을 세로셈으로 계산하는 방법을 쓰고, 십의 자리에서 남은 수를 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: 십의 자리 4를 3으로 나누면 몫 1이 서고 1이 남는다. 남은 1은 10을 뜻하므로 일의 자리 5 위로 내려 15로 보고 15 ÷ 3 = 5를 구한다. 몫은 15이고 한 명이 15장씩 가진다. 확인하면 3 × 15 = 45이다.","scoring_points":["4 ÷ 3 = 1 … 1을 구했는가","남은 1을 내려 15로 보고 다시 나누었는가","15장이라고 답하고 확인했는가"]},"explanation":["4 ÷ 3 → 몫 1, 1 남음.","남은 1을 내려 15 ÷ 3 = 5.","45 ÷ 3 = 15 — 3 × 15 = 45."],"asset":{"type":"ldiv","a":45,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#9','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'essay','teacher','하랑이는 87 ÷ 3을 「8 ÷ 3 = 2 … 2, 7 ÷ 3 = 2 … 1이니 몫은 22」라고 했어요. 하랑이의 잘못을 찾고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C5","difficulty":4,"kind":"essay","stem":"하랑이는 87 ÷ 3을 「8 ÷ 3 = 2 … 2, 7 ÷ 3 = 2 … 1이니 몫은 22」라고 했어요. 하랑이의 잘못을 찾고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 십의 자리에서 남은 2를 일의 자리로 내리지 않고 일의 자리 7만 따로 나누었다. 남은 2를 7과 함께 27로 보면 27 ÷ 3 = 9이다. 몫은 29이다. 확인하면 3 × 29 = 87이다.","scoring_points":["남은 2를 내리지 않았다고 찾았는가","27 ÷ 3 = 9를 구했는가","29를 구하고 확인했는가"]},"explanation":["8 ÷ 3 → 몫 2, 2 남음.","남은 2를 내려 27 ÷ 3 = 9.","87 ÷ 3 = 29 — 3 × 29 = 87."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L05_challenge#10','math',3,2,'u2','L05','g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'sa','auto','어떤 수를 4로 나누었더니 몫이 18이고 나누어떨어졌어요. 어떤 수를 3으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C5","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누었더니 몫이 18이고 나누어떨어졌어요. 어떤 수를 3으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["어떤 수 = 4 × 18 = 72예요.","72 ÷ 3 — 십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 3 → 몫 4.","72 ÷ 3 = 24 — 몫은 24예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 3으로 나누었더니 몫이 24이고 나누어떨어졌어요. 어떤 수를 6으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["어떤 수 = 3 × 24 = 72예요.","72 ÷ 6 — 십의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 6 → 몫 2.","72 ÷ 6 = 12 — 몫은 12예요."],"asset":null},{"stem":"어떤 수를 6으로 나누었더니 몫이 13이고 나누어떨어졌어요. 어떤 수를 3으로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["어떤 수 = 6 × 13 = 78이에요.","78 ÷ 3 — 십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 18 ÷ 3 → 몫 6.","78 ÷ 3 = 26 — 몫은 26이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#1','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'sa','auto','25 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"25 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 4의 단에서 25보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 나머지 1은 나누는 수 4보다 작아요."],"variant_rule":{"alt":[{"stem":"38 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나누는 수 5의 단에서 38보다 크지 않은 가장 큰 곱을 찾아요.","5 × 7 = 35 — 몫 7, 38 − 35 = 3이 남아요.","38 ÷ 5 = 7 … 3 — 나머지 3은 나누는 수 5보다 작아요."],"asset":null},{"stem":"26 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나누는 수 5의 단에서 26보다 크지 않은 가장 큰 곱을 찾아요.","5 × 5 = 25 — 몫 5, 26 − 25 = 1이 남아요.","26 ÷ 5 = 5 … 1 — 나머지 1은 나누는 수 5보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#2','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'sa','auto','25 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"25 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 4의 단에서 25보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 나머지 1은 나누는 수 4보다 작아요."],"variant_rule":{"alt":[{"stem":"55 ÷ 9의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 9의 단에서 55보다 크지 않은 가장 큰 곱을 찾아요.","9 × 6 = 54 — 몫 6, 55 − 54 = 1이 남아요.","55 ÷ 9 = 6 … 1 — 나머지 1은 나누는 수 9보다 작아요."],"asset":null},{"stem":"67 ÷ 8의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 8의 단에서 67보다 크지 않은 가장 큰 곱을 찾아요.","8 × 8 = 64 — 몫 8, 67 − 64 = 3이 남아요.","67 ÷ 8 = 8 … 3 — 나머지 3은 나누는 수 8보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#3','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'mc','auto','16 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":3,"concept":"M3-2-u2-C6","difficulty":1,"kind":"mc","stem":"16 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 … 1","correct":true},{"t":"4 … 4","mis":"M3-2-u2-X05"},{"t":"1 … 5","mis":"M3-2-u2-X06"},{"t":"5","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 3의 단에서 16보다 크지 않은 가장 큰 곱을 찾아요.","3 × 5 = 15 — 몫 5, 16 − 15 = 1이 남아요.","16 ÷ 3 = 5 … 1 — 나머지 1은 나누는 수 3보다 작아요."],"variant_rule":{"alt":[{"stem":"40 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 … 4","correct":true},{"t":"3 … 13","mis":"M3-2-u2-X05"},{"t":"4","mis":"M3-2-u2-X07"},{"t":"4 … 5","mis":"M3-2-u2-X15"}],"explanation":["나누는 수 9의 단에서 40보다 크지 않은 가장 큰 곱을 찾아요.","9 × 4 = 36 — 몫 4, 40 − 36 = 4가 남아요.","40 ÷ 9 = 4 … 4 — 나머지 4는 나누는 수 9보다 작아요."],"asset":null},{"stem":"36 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 … 1","correct":true},{"t":"4 … 8","mis":"M3-2-u2-X05"},{"t":"1 … 5","mis":"M3-2-u2-X06"},{"t":"5","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 7의 단에서 36보다 크지 않은 가장 큰 곱을 찾아요.","7 × 5 = 35 — 몫 5, 36 − 35 = 1이 남아요.","36 ÷ 7 = 5 … 1 — 나머지 1은 나누는 수 7보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#4','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'sa','auto','어떤 수를 4로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"어떤 수를 4로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나머지가 4가 되면 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 4보다 작아요.","가장 큰 나머지는 3이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나머지가 6이 되면 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 6보다 작아요.","가장 큰 나머지는 5예요."],"asset":null},{"stem":"어떤 수를 8로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나머지가 8이 되면 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 8보다 작아요.","가장 큰 나머지는 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#5','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'mc','auto','손수건 25장을 4명이 똑같이 나누어 가지려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":5,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"손수건 25장을 4명이 똑같이 나누어 가지려고 해요. 어떻게 되나요?","options":[{"t":"6장씩, 1장 남아요","correct":true},{"t":"5장씩, 5장 남아요","mis":"M3-2-u2-X05"},{"t":"1장씩, 6장 남아요","mis":"M3-2-u2-X06"},{"t":"6장씩, 2장 남아요","mis":"M3-2-u2-X15"}],"explanation":["25 ÷ 4 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 6장씩, 1장 남아요."],"variant_rule":{"alt":[{"stem":"약과 47개를 어르신 6분께 똑같이 나누어 드리려고 해요. 어떻게 되나요?","options":[{"t":"7개씩, 5개 남아요","correct":true},{"t":"6개씩, 11개 남아요","mis":"M3-2-u2-X05"},{"t":"5개씩, 7개 남아요","mis":"M3-2-u2-X06"},{"t":"8개씩, 4개 남아요","mis":"M3-2-u2-X15"}],"explanation":["47 ÷ 6 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","6 × 7 = 42 — 몫 7, 47 − 42 = 5가 남아요.","47 ÷ 6 = 7 … 5 — 7개씩, 5개 남아요."],"asset":null},{"stem":"도서관 책 58권을 책장 8칸에 똑같이 나누어 꽂으려고 해요. 어떻게 되나요?","options":[{"t":"7권씩, 2권 남아요","correct":true},{"t":"6권씩, 10권 남아요","mis":"M3-2-u2-X05"},{"t":"2권씩, 7권 남아요","mis":"M3-2-u2-X06"},{"t":"7권씩, 3권 남아요","mis":"M3-2-u2-X15"}],"explanation":["58 ÷ 8 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","8 × 7 = 56 — 몫 7, 58 − 56 = 2가 남아요.","58 ÷ 8 = 7 … 2 — 7권씩, 2권 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#6','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'mc','auto','어떤 수를 4로 나눌 때 나머지가 될 수 없는 수는 어느 것인가요?',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"어떤 수를 4로 나눌 때 나머지가 될 수 없는 수는 어느 것인가요?","options":[{"t":"5","correct":true},{"t":"1","mis":"M3-2-u2-X05"},{"t":"2","mis":"M3-2-u2-X05"},{"t":"3","mis":"M3-2-u2-X05"}],"explanation":["나머지는 나누는 수 4보다 작아야 해요.","그래서 나머지는 0부터 3까지 — 0이면 나누어떨어져요.","5는 4보다 작지 않아 나머지가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나눌 때 나머지가 될 수 없는 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"3","mis":"M3-2-u2-X05"},{"t":"4","mis":"M3-2-u2-X05"},{"t":"5","mis":"M3-2-u2-X05"}],"explanation":["나머지는 나누는 수 6보다 작아야 해요.","그래서 나머지는 0부터 5까지 — 0이면 나누어떨어져요.","6은 6보다 작지 않아 나머지가 될 수 없어요."],"asset":null},{"stem":"어떤 수를 7로 나눌 때 나머지가 될 수 없는 수는 어느 것인가요?","options":[{"t":"8","correct":true},{"t":"0","mis":"M3-2-u2-X18"},{"t":"3","mis":"M3-2-u2-X05"},{"t":"4","mis":"M3-2-u2-X05"}],"explanation":["나머지는 나누는 수 7보다 작아야 해요.","그래서 나머지는 0부터 6까지 — 0이면 나누어떨어져요.","8은 7보다 작지 않아 나머지가 될 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#7','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'ox','auto','42 ÷ 5는 몫이 8이라 나누어떨어지는 나눗셈이에요.',ARRAY['M3-2-u2-X18']::text[],true,'{"seq":7,"concept":"M3-2-u2-C6","difficulty":2,"kind":"ox","stem":"42 ÷ 5는 몫이 8이라 나누어떨어지는 나눗셈이에요.","answer":"X","reason_options":[{"t":"나머지가 2가 있어서","correct":true},{"t":"몫이 있으면 나누어떨어지는 것이라서","mis":"M3-2-u2-X18"}],"mis":"M3-2-u2-X18","explanation":["나누어떨어진다는 것은 나머지가 0이라는 뜻이에요.","42 ÷ 5 = 8 … 2.","나머지가 2라 나누어떨어지지 않아요."],"variant_rule":{"alt":[{"stem":"23 ÷ 9는 몫이 2라 나누어떨어지는 나눗셈이에요.","answer":"X","reason_options":[{"t":"나머지가 5가 있어서","correct":true},{"t":"몫이 있으면 나누어떨어지는 것이라서","mis":"M3-2-u2-X18"}],"explanation":["나누어떨어진다는 것은 나머지가 0이라는 뜻이에요.","23 ÷ 9 = 2 … 5.","나머지가 5라 나누어떨어지지 않아요."],"asset":null},{"stem":"48 ÷ 9는 몫이 5라 나누어떨어지는 나눗셈이에요.","answer":"X","reason_options":[{"t":"나머지가 3이 있어서","correct":true},{"t":"몫이 있으면 나누어떨어지는 것이라서","mis":"M3-2-u2-X18"}],"explanation":["나누어떨어진다는 것은 나머지가 0이라는 뜻이에요.","48 ÷ 9 = 5 … 3.","나머지가 3이라 나누어떨어지지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#8','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],true,'{"seq":8,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"23 ÷ 3","mis":"M3-2-u2-X07"},{"t":"16 ÷ 7","mis":"M3-2-u2-X07"},{"t":"51 ÷ 7","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0이면 나누어떨어진다고 해요.","24 ÷ 4 = 6이에요 — 나머지가 없어요.","나머지는 23 ÷ 3 → 2, 16 ÷ 7 → 2, 51 ÷ 7 → 2."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"54 ÷ 6","correct":true},{"t":"73 ÷ 8","mis":"M3-2-u2-X07"},{"t":"33 ÷ 4","mis":"M3-2-u2-X07"},{"t":"15 ÷ 4","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0이면 나누어떨어진다고 해요.","54 ÷ 6 = 9예요 — 나머지가 없어요.","나머지는 73 ÷ 8 → 1, 33 ÷ 4 → 1, 15 ÷ 4 → 3."],"asset":null},{"stem":"이번에는 다른 수예요. 나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"56 ÷ 8","correct":true},{"t":"28 ÷ 6","mis":"M3-2-u2-X07"},{"t":"37 ÷ 7","mis":"M3-2-u2-X07"},{"t":"50 ÷ 7","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0이면 나누어떨어진다고 해요.","56 ÷ 8 = 7이에요 — 나머지가 없어요.","나머지는 28 ÷ 6 → 4, 37 ÷ 7 → 2, 50 ÷ 7 → 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#9','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'ox','auto','클립 25개를 4개씩 묶었더니 6묶음이 되고 1개가 남았어요. 이것을 25 ÷ 4 = 1 … 6으로 나타내요.',ARRAY['M3-2-u2-X06']::text[],true,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"ox","stem":"클립 25개를 4개씩 묶었더니 6묶음이 되고 1개가 남았어요. 이것을 25 ÷ 4 = 1 … 6으로 나타내요.","answer":"X","reason_options":[{"t":"묶음 수가 몫, 남은 것이 나머지라서","correct":true},{"t":"앞에 쓰는 수가 남은 것이라서","mis":"M3-2-u2-X06"}],"mis":"M3-2-u2-X06","explanation":["4개씩 6묶음 — 몫은 6이에요.","남은 1개 — 나머지는 1이에요.","25 ÷ 4 = 6 … 1 — 몫과 나머지를 바꾸어 쓰면 안 돼요."],"variant_rule":{"alt":[{"stem":"사탕 39개를 4개씩 묶었더니 9묶음이 되고 3개가 남았어요. 이것을 39 ÷ 4 = 3 … 9로 나타내요.","answer":"X","reason_options":[{"t":"묶음 수가 몫, 남은 것이 나머지라서","correct":true},{"t":"앞에 쓰는 수가 남은 것이라서","mis":"M3-2-u2-X06"}],"explanation":["4개씩 9묶음 — 몫은 9예요.","남은 3개 — 나머지는 3이에요.","39 ÷ 4 = 9 … 3 — 몫과 나머지를 바꾸어 쓰면 안 돼요."],"asset":null},{"stem":"종이꽃 87개를 9개씩 묶었더니 9묶음이 되고 6개가 남았어요. 이것을 87 ÷ 9 = 6 … 9로 나타내요.","answer":"X","reason_options":[{"t":"묶음 수가 몫, 남은 것이 나머지라서","correct":true},{"t":"앞에 쓰는 수가 남은 것이라서","mis":"M3-2-u2-X06"}],"explanation":["9개씩 9묶음 — 몫은 9예요.","남은 6개 — 나머지는 6이에요.","87 ÷ 9 = 9 … 6 — 몫과 나머지를 바꾸어 쓰면 안 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_basic#10','math',3,2,'u2','L06','g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',3,'error','auto','42 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C6","difficulty":3,"kind":"error","stem":"42 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「42 ÷ 5 = 9 … 1」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태오 — 「42 ÷ 5 = 8 … 2」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「확인하면 5 × 8 + 2 = 42」","mis":"M3-2-u2-X17"}],"explanation":["5 × 8 = 40 — 몫 8, 42 − 40 = 2가 남아요.","42 ÷ 5 = 8 … 2.","하린이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"34 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「34 ÷ 7 = 5 … 5」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태오 — 「34 ÷ 7 = 4 … 6」","mis":"M3-2-u2-X17"},{"t":"시우 — 「나머지 6은 7보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["7 × 4 = 28 — 몫 4, 34 − 28 = 6이 남아요.","34 ÷ 7 = 4 … 6.","지유가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"28 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「28 ÷ 6 = 5 … 3」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태오 — 「28 ÷ 6 = 4 … 4」","mis":"M3-2-u2-X17"},{"t":"도윤 — 「확인하면 6 × 4 + 4 = 28」","mis":"M3-2-u2-X17"}],"explanation":["6 × 4 = 24 — 몫 4, 28 − 24 = 4가 남아요.","28 ÷ 6 = 4 … 4.","하린이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#1','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',2,'mc','auto','클립 60개를 8명에게 똑같이 나누어 주려고 해요. 나누어 주고 남는 클립은 몇 개인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X05','M3-2-u2-X15']::text[],true,'{"seq":1,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"클립 60개를 8명에게 똑같이 나누어 주려고 해요. 나누어 주고 남는 클립은 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"7개","mis":"M3-2-u2-X13"},{"t":"12개","mis":"M3-2-u2-X05"},{"t":"5개","mis":"M3-2-u2-X15"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 60 ÷ 8.","8 × 7 = 56 — 몫 7, 60 − 56 = 4가 남아요.","60 ÷ 8 = 7 … 4 — 남는 것은 4개예요."],"variant_rule":{"alt":[{"stem":"봉사 활동 배지 14개를 5모둠에 똑같이 나누어 주려고 해요. 나누어 주고 남는 배지는 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"9개","mis":"M3-2-u2-X05"},{"t":"1개","mis":"M3-2-u2-X13"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 14 ÷ 5.","5 × 2 = 10 — 몫 2, 14 − 10 = 4가 남아요.","14 ÷ 5 = 2 … 4 — 남는 것은 4개예요."],"asset":null},{"stem":"금잔화 모종 15개를 화단 2곳에 똑같이 나누어 심으려고 해요. 심고 남는 모종은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"7개","mis":"M3-2-u2-X13"},{"t":"3개","mis":"M3-2-u2-X05"},{"t":"2개","mis":"M3-2-u2-X05"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 15 ÷ 2.","2 × 7 = 14 — 몫 7, 15 − 14 = 1이 남아요.","15 ÷ 2 = 7 … 1 — 남는 것은 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#2','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',2,'sa','auto','10 ÷ 3, 11 ÷ 3, 12 ÷ 3의 나머지는 차례로 1, 2, 0이에요. 13 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"10 ÷ 3, 11 ÷ 3, 12 ÷ 3의 나머지는 차례로 1, 2, 0이에요. 13 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누어지는 수가 1씩 커지면 나머지도 1씩 커지다가 3이 되기 전에 0으로 돌아가요.","13 ÷ 3 = 4 … 1.","나머지는 언제나 3보다 작게 되풀이돼요."],"variant_rule":{"alt":[{"stem":"13 ÷ 4, 14 ÷ 4, 15 ÷ 4의 나머지는 차례로 1, 2, 3이에요. 16 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["나누어지는 수가 1씩 커지면 나머지도 1씩 커지다가 4가 되기 전에 0으로 돌아가요.","16 ÷ 4 = 4 … 0.","나머지는 언제나 4보다 작게 되풀이돼요."],"asset":null},{"stem":"21 ÷ 5, 22 ÷ 5, 23 ÷ 5의 나머지는 차례로 1, 2, 3이에요. 24 ÷ 5의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누어지는 수가 1씩 커지면 나머지도 1씩 커지다가 5가 되기 전에 0으로 돌아가요.","24 ÷ 5 = 4 … 4.","나머지는 언제나 5보다 작게 되풀이돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#3','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'mc','auto','14 ÷ 5, 22 ÷ 4, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"14 ÷ 5, 22 ÷ 4, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"14 ÷ 5","correct":true},{"t":"22 ÷ 4","mis":"M3-2-u2-X15"},{"t":"64 ÷ 9","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","14 ÷ 5 = 2 … 4, 22 ÷ 4 = 5 … 2, 64 ÷ 9 = 7 … 1.","나머지가 가장 큰 것은 14 ÷ 5 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"19 ÷ 4, 29 ÷ 6, 52 ÷ 8 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"29 ÷ 6","correct":true},{"t":"19 ÷ 4","mis":"M3-2-u2-X15"},{"t":"52 ÷ 8","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","19 ÷ 4 = 4 … 3, 29 ÷ 6 = 4 … 5, 52 ÷ 8 = 6 … 4.","나머지가 가장 큰 것은 29 ÷ 6 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null},{"stem":"23 ÷ 6, 30 ÷ 4, 50 ÷ 7 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"23 ÷ 6","correct":true},{"t":"30 ÷ 4","mis":"M3-2-u2-X17"},{"t":"50 ÷ 7","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","23 ÷ 6 = 3 … 5, 30 ÷ 4 = 7 … 2, 50 ÷ 7 = 7 … 1.","나머지가 가장 큰 것은 23 ÷ 6 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#4','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'sa','auto','옥수수 38개를 5봉지에 똑같이 나누어 담으려고 해요. 담고 남는 옥수수는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C6","difficulty":3,"kind":"sa","stem":"옥수수 38개를 5봉지에 똑같이 나누어 담으려고 해요. 담고 남는 옥수수는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 38 ÷ 5.","5 × 7 = 35 — 몫 7, 38 − 35 = 3이 남아요.","38 ÷ 5 = 7 … 3 — 남는 것은 3개예요."],"variant_rule":{"alt":[{"stem":"종이꽃 15개를 7개씩 묶어 꽃다발을 만들려고 해요. 꽃다발을 만들고 남는 종이꽃은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 15 ÷ 7.","7 × 2 = 14 — 몫 2, 15 − 14 = 1이 남아요.","15 ÷ 7 = 2 … 1 — 남는 것은 1개예요."],"asset":null},{"stem":"클립 26개를 3명에게 똑같이 나누어 주려고 해요. 나누어 주고 남는 클립은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 26 ÷ 3.","3 × 8 = 24 — 몫 8, 26 − 24 = 2가 남아요.","26 ÷ 3 = 8 … 2 — 남는 것은 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#5','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'mc','auto','59 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":5,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"59 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 … 3","correct":true},{"t":"7 … 10","mis":"M3-2-u2-X05"},{"t":"3 … 8","mis":"M3-2-u2-X06"},{"t":"8","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 7의 단에서 59보다 크지 않은 가장 큰 곱을 찾아요.","7 × 8 = 56 — 몫 8, 59 − 56 = 3이 남아요.","59 ÷ 7 = 8 … 3 — 나머지 3은 나누는 수 7보다 작아요."],"variant_rule":{"alt":[{"stem":"17 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 … 1","correct":true},{"t":"1 … 9","mis":"M3-2-u2-X05"},{"t":"1 … 2","mis":"M3-2-u2-X06"},{"t":"2","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 8의 단에서 17보다 크지 않은 가장 큰 곱을 찾아요.","8 × 2 = 16 — 몫 2, 17 − 16 = 1이 남아요.","17 ÷ 8 = 2 … 1 — 나머지 1은 나누는 수 8보다 작아요."],"asset":null},{"stem":"16 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 … 7","correct":true},{"t":"7 … 1","mis":"M3-2-u2-X06"},{"t":"1","mis":"M3-2-u2-X07"},{"t":"1 … 8","mis":"M3-2-u2-X15"}],"explanation":["나누는 수 9의 단에서 16보다 크지 않은 가장 큰 곱을 찾아요.","9 × 1 = 9 — 몫 1, 16 − 9 = 7이 남아요.","16 ÷ 9 = 1 … 7 — 나머지 7은 나누는 수 9보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#6','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'ox','auto','30 ÷ 4 = 6 … 6이에요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":3,"kind":"ox","stem":"30 ÷ 4 = 6 … 6이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["4 × 7 = 28 — 몫 7, 30 − 28 = 2가 남아요.","바르게 계산하면 30 ÷ 4 = 7 … 2.","나머지 < 나누는 수 — 확인: 4 × 7 + 2 = 30이에요."],"asset":{"type":"ldiv","a":30,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"26 ÷ 3 = 7 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["3 × 8 = 24 — 몫 8, 26 − 24 = 2가 남아요.","바르게 계산하면 26 ÷ 3 = 8 … 2.","나머지 < 나누는 수 — 확인: 3 × 8 + 2 = 26이에요."],"asset":{"type":"ldiv","a":26,"b":3,"upto":0}},{"stem":"11 ÷ 2 = 4 … 3이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["2 × 5 = 10 — 몫 5, 11 − 10 = 1이 남아요.","바르게 계산하면 11 ÷ 2 = 5 … 1.","나머지 < 나누는 수 — 확인: 2 × 5 + 1 = 11이에요."],"asset":{"type":"ldiv","a":11,"b":2,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#7','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'error','auto','38 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C6","difficulty":3,"kind":"error","stem":"38 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「38 ÷ 5 = 7 … 4」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"은우 — 「38 ÷ 5 = 7 … 3」","mis":"M3-2-u2-X17"},{"t":"하랑 — 「나머지 3은 5보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["5 × 7 = 35 — 몫 7, 38 − 35 = 3이 남아요.","38 ÷ 5 = 7 … 3.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"15 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「15 ÷ 4 = 2 … 7」","correct":true,"mis_target":"M3-2-u2-X05"},{"t":"은우 — 「15 ÷ 4 = 3 … 3」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 4 × 3 + 3 = 15」","mis":"M3-2-u2-X17"}],"explanation":["4 × 3 = 12 — 몫 3, 15 − 12 = 3이 남아요.","15 ÷ 4 = 3 … 3.","하랑이 잘못 말했어요 — 나머지 < 나누는 수."],"asset":null},{"stem":"31 ÷ 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「31 ÷ 9 = 3 … 5」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"도윤 — 「31 ÷ 9 = 3 … 4」","mis":"M3-2-u2-X17"},{"t":"하랑 — 「나머지 4는 9보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["9 × 3 = 27 — 몫 3, 31 − 27 = 4가 남아요.","31 ÷ 9 = 3 … 4.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#8','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'essay','teacher','종이꽃 25개를 4개씩 묶어 꽃다발을 만들어요. 꽃다발 수와 남는 종이꽃 수를 구하고, 나눗셈식으로 나타내어 몫과 나머지가 무엇인지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"종이꽃 25개를 4개씩 묶어 꽃다발을 만들어요. 꽃다발 수와 남는 종이꽃 수를 구하고, 나눗셈식으로 나타내어 몫과 나머지가 무엇인지 설명해 보세요.","answer_guide":{"answer":"예: 4개씩 묶으면 6다발이 되고 1개가 남는다. 25 ÷ 4 = 6 … 1이고 6은 몫, 1은 나머지이다. 24 ÷ 4 = 6은 나머지가 0이라 나누어떨어지지만 25 ÷ 4는 1이 남아 나누어떨어지지 않는다.","scoring_points":["6다발과 1개를 구했는가","25 ÷ 4 = 6 … 1로 쓰고 몫·나머지를 말했는가","나누어떨어짐과 견주었는가"]},"explanation":["4 × 6 = 24, 25 − 24 = 1.","25 ÷ 4 = 6 … 1.","6은 몫, 1은 나머지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#9','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'essay','teacher','하린이는 31 ÷ 4 = 6 … 7이라고 했어요. 하린이의 답이 맞는지 판단하고, 나머지와 나누는 수를 견주어 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"하린이는 31 ÷ 4 = 6 … 7이라고 했어요. 하린이의 답이 맞는지 판단하고, 나머지와 나누는 수를 견주어 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 나머지 7은 나누는 수 4보다 커서 4개씩 한 묶음을 더 만들 수 있다. 바르게 하면 31 ÷ 4 = 7 … 3이다. 확인하면 4 × 7 + 3 = 31이다.","scoring_points":["틀렸다고 판단했는가","나머지는 나누는 수보다 작아야 한다고 설명했는가","7 … 3을 구하고 확인했는가"]},"explanation":["나머지 7 ≥ 4 — 한 묶음 더.","31 ÷ 4 = 7 … 3.","4 × 7 + 3 = 31."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L06_challenge#10','math',3,2,'u2','L06','g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'sa','auto','어떤 수를 7로 나누었더니 몫이 4이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C6","difficulty":4,"kind":"sa","stem":"어떤 수를 7로 나누었더니 몫이 4이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","7 × 4 = 28, 28 + 6 = 34예요.","확인: 34 ÷ 7 = 4 … 6."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었더니 몫이 7이고 나머지가 5가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","6 × 7 = 42, 42 + 5 = 47이에요.","확인: 47 ÷ 6 = 7 … 5."],"asset":null},{"stem":"어떤 수를 8로 나누었더니 몫이 7이고 나머지가 3이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["59"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","8 × 7 = 56, 56 + 3 = 59예요.","확인: 59 ÷ 8 = 7 … 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#1','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','67 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"67 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","67 ÷ 5 = 13 … 2 — 확인: 5 × 13 + 2 = 67이에요."],"variant_rule":{"alt":[{"stem":"94 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 7 → 몫 3.","94 ÷ 7 = 13 … 3 — 확인: 7 × 13 + 3 = 94예요."],"asset":null},{"stem":"45 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 4 → 몫 1 · 일의 자리 5 ÷ 4 → 몫 1.","45 ÷ 4 = 11 … 1 — 확인: 4 × 11 + 1 = 45예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#2','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','73 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"73 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","73 ÷ 3 = 24 … 1 — 확인: 3 × 24 + 1 = 73이에요."],"variant_rule":{"alt":[{"stem":"62 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 6 → 몫 1 · 일의 자리 2는 6으로 나눌 수 없어 몫 0.","62 ÷ 6 = 10 … 2 — 확인: 6 × 10 + 2 = 62예요."],"asset":null},{"stem":"29 ÷ 2의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 9 ÷ 2 → 몫 4.","29 ÷ 2 = 14 … 1 — 확인: 2 × 14 + 1 = 29예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#3','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'mc','auto','82 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":3,"concept":"M3-2-u2-C7","difficulty":1,"kind":"mc","stem":"82 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 … 5","correct":true},{"t":"10 … 12","mis":"M3-2-u2-X05"},{"t":"5 … 11","mis":"M3-2-u2-X06"},{"t":"11","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 7 → 몫 1.","82 ÷ 7 = 11 … 5 — 확인: 7 × 11 + 5 = 82예요."],"variant_rule":{"alt":[{"stem":"99 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"12 … 3","correct":true},{"t":"11 … 11","mis":"M3-2-u2-X05"},{"t":"3 … 12","mis":"M3-2-u2-X06"},{"t":"12","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 8 → 몫 2.","99 ÷ 8 = 12 … 3 — 확인: 8 × 12 + 3 = 99예요."],"asset":null},{"stem":"97 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10 … 7","correct":true},{"t":"9 … 16","mis":"M3-2-u2-X05"},{"t":"7 … 10","mis":"M3-2-u2-X06"},{"t":"10","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 7은 9로 나눌 수 없어 몫 0.","97 ÷ 9 = 10 … 7 — 확인: 9 × 10 + 7 = 97이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#4','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["나누는 수 × 몫 = 3 × 14 = 42예요.","여기에 나머지 2를 더하면 44예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 14","=",null],["□ + 2","=","44"]]},"variant_rule":{"alt":[{"stem":"93 ÷ 8 = 11 … 5를 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["93"],"explanation":["나누는 수 × 몫 = 8 × 11 = 88이에요.","여기에 나머지 5를 더하면 93이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["8 × 11","=","88"],["88 + 5","=",null]]}},{"stem":"99 ÷ 8 = 12 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["96"],"explanation":["나누는 수 × 몫 = 8 × 12 = 96이에요.","여기에 나머지 3을 더하면 99예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["8 × 12","=",null],["□ + 3","=","99"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#5','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'sa','auto','67 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"67 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","67 ÷ 5 = 13 … 2 — 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":67,"b":5,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"93 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 4 → 몫 3.","93 ÷ 4 = 23 … 1 — 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":93,"b":4,"hide":[["q",0]]}},{"stem":"85 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 5 ÷ 2 → 몫 2.","85 ÷ 2 = 42 … 1 — 십의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":85,"b":2,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#6','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'mc','auto','색종이 67장을 5모둠에 똑같이 나누어 주려고 해요. 나누어 주고 남는 색종이는 몇 장인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X05']::text[],true,'{"seq":6,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"색종이 67장을 5모둠에 똑같이 나누어 주려고 해요. 나누어 주고 남는 색종이는 몇 장인가요?","options":[{"t":"2장","correct":true},{"t":"13장","mis":"M3-2-u2-X13"},{"t":"7장","mis":"M3-2-u2-X05"},{"t":"3장","mis":"M3-2-u2-X13"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 67 ÷ 5.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","67 ÷ 5 = 13 … 2 — 남는 것은 2장이에요."],"variant_rule":{"alt":[{"stem":"옥수수 99개를 7봉지에 똑같이 나누어 담으려고 해요. 담고 남는 옥수수는 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"14개","mis":"M3-2-u2-X13"},{"t":"8개","mis":"M3-2-u2-X05"},{"t":"6개","mis":"M3-2-u2-X13"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 99 ÷ 7.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 7 → 몫 4.","99 ÷ 7 = 14 … 1 — 남는 것은 1개예요."],"asset":null},{"stem":"종이꽃 76개를 3개씩 묶어 꽃다발을 만들려고 해요. 꽃다발을 만들고 남는 종이꽃은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"25개","mis":"M3-2-u2-X13"},{"t":"4개","mis":"M3-2-u2-X05"},{"t":"2개","mis":"M3-2-u2-X13"}],"explanation":["똑같이 나누고 남는 것은 나머지예요 — 76 ÷ 3.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 16 ÷ 3 → 몫 5.","76 ÷ 3 = 25 … 1 — 남는 것은 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#7','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'mc','auto','99 ÷ 8 = 12 … 3을 바르게 계산했는지 확인하는 식은 어느 것인가요?',ARRAY['M3-2-u2-X08','M3-2-u2-X09','M3-2-u2-X14']::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"99 ÷ 8 = 12 … 3을 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"8 × 12 + 3 = 99","correct":true},{"t":"3 × 12 + 8 = 44","mis":"M3-2-u2-X08"},{"t":"8 × 12 = 96","mis":"M3-2-u2-X09"},{"t":"8 + 12 + 3 = 23","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수 × 몫에 나머지를 더해요.","8 × 12 = 96, 96 + 3 = 99예요.","나누어지는 수 99와 같으니 바르게 계산했어요."],"variant_rule":{"alt":[{"stem":"93 ÷ 8 = 11 … 5를 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"8 × 11 + 5 = 93","correct":true},{"t":"5 × 11 + 8 = 63","mis":"M3-2-u2-X08"},{"t":"8 × 11 = 88","mis":"M3-2-u2-X09"},{"t":"8 + 11 + 5 = 24","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수 × 몫에 나머지를 더해요.","8 × 11 = 88, 88 + 5 = 93이에요.","나누어지는 수 93과 같으니 바르게 계산했어요."],"asset":null},{"stem":"50 ÷ 3 = 16 … 2를 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"3 × 16 + 2 = 50","correct":true},{"t":"2 × 16 + 3 = 35","mis":"M3-2-u2-X08"},{"t":"3 × 16 = 48","mis":"M3-2-u2-X09"},{"t":"3 + 16 + 2 = 21","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수 × 몫에 나머지를 더해요.","3 × 16 = 48, 48 + 2 = 50이에요.","나누어지는 수 50과 같으니 바르게 계산했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#8','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C4',2,'mc','auto','73 ÷ 3을 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":8,"concept":"M3-2-u2-C4","difficulty":2,"kind":"mc","stem":"73 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"20과 30 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"30보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 300 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 20 = 60, 3 × 30 = 90 — 73은 그 사이에 있어요.","그래서 몫은 20과 30 사이 — 실제 몫 24예요."],"variant_rule":{"alt":[{"stem":"61 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"30과 40 사이","correct":true},{"t":"30보다 작아요","mis":"M3-2-u2-X16"},{"t":"40보다 커요","mis":"M3-2-u2-X16"},{"t":"300과 400 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 30 = 60, 2 × 40 = 80 — 61은 그 사이에 있어요.","그래서 몫은 30과 40 사이 — 실제 몫 30이에요."],"asset":null},{"stem":"98 ÷ 9를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","9 × 10 = 90, 9 × 20 = 180 — 98은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#9','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'match','auto','나눗셈식과 몫 … 나머지를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C7","difficulty":2,"kind":"match","stem":"나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"92 ÷ 8","r":"11 … 4"},{"l":"96 ÷ 7","r":"13 … 5"},{"l":"95 ÷ 9","r":"10 … 5"}],"mis":"M3-2-u2-X03","explanation":["높은 자리부터 차례로 나누어요.","92 ÷ 8 = 11 … 4, 96 ÷ 7 = 13 … 5, 95 ÷ 9 = 10 … 5.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"79 ÷ 7","r":"11 … 2"},{"l":"50 ÷ 4","r":"12 … 2"},{"l":"97 ÷ 6","r":"16 … 1"}],"explanation":["높은 자리부터 차례로 나누어요.","79 ÷ 7 = 11 … 2, 50 ÷ 4 = 12 … 2, 97 ÷ 6 = 16 … 1.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"72 ÷ 7","r":"10 … 2"},{"l":"83 ÷ 2","r":"41 … 1"},{"l":"86 ÷ 4","r":"21 … 2"}],"explanation":["높은 자리부터 차례로 나누어요.","72 ÷ 7 = 10 … 2, 83 ÷ 2 = 41 … 1, 86 ÷ 4 = 21 … 2.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_basic#10','math',3,2,'u2','L07','g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',3,'error','auto','73 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":3,"kind":"error","stem":"73 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「73 ÷ 3 = 21 … 1」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"하랑 — 「73 ÷ 3 = 24 … 1」","mis":"M3-2-u2-X17"},{"t":"태오 — 「나머지 1은 3보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","73 ÷ 3 = 24 … 1.","하린이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"67 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「67 ÷ 2 = 32 … 3」","correct":true,"mis_target":"M3-2-u2-X05"},{"t":"시우 — 「67 ÷ 2 = 33 … 1」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「확인하면 2 × 33 + 1 = 67」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 7 ÷ 2 → 몫 3.","67 ÷ 2 = 33 … 1.","도윤이 잘못 말했어요 — 나머지 < 나누는 수."],"asset":null},{"stem":"81 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「81 ÷ 7 = 10 … 4」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"도윤 — 「81 ÷ 7 = 11 … 4」","mis":"M3-2-u2-X17"},{"t":"지유 — 「나머지 4는 7보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 11 ÷ 7 → 몫 1.","81 ÷ 7 = 11 … 4.","은우가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#1','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',2,'error','auto','99 ÷ 8 = 12 … 3을 확인한 방법이에요. 잘못 확인한 친구는 누구인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X17']::text[],true,'{"seq":1,"concept":"M3-2-u2-C7","difficulty":2,"kind":"error","stem":"99 ÷ 8 = 12 … 3을 확인한 방법이에요. 잘못 확인한 친구는 누구인가요?","options":[{"t":"하랑 — 「8 × 12 = 96 — 99와 달라 틀렸어」","correct":true,"mis_target":"M3-2-u2-X09"},{"t":"태오 — 「8 × 12 + 3 = 99 — 맞아」","mis":"M3-2-u2-X17"},{"t":"하린 — 「나머지 3은 8보다 작고 8 × 12 + 3 = 99라 맞아」","mis":"M3-2-u2-X17"}],"explanation":["확인: 나누는 수 × 몫 + 나머지 = 나누어지는 수.","8 × 12 + 3 = 99예요.","하랑은 나머지를 더하지 않았어요."],"variant_rule":{"alt":[{"stem":"95 ÷ 2 = 47 … 1을 확인한 방법이에요. 잘못 확인한 친구는 누구인가요?","options":[{"t":"은우 — 「1 × 47 + 2 = 49 — 틀렸어」","correct":true,"mis_target":"M3-2-u2-X08"},{"t":"도윤 — 「2 × 47 + 1 = 95 — 맞아」","mis":"M3-2-u2-X17"},{"t":"태오 — 「나머지 1은 2보다 작고 2 × 47 + 1 = 95라 맞아」","mis":"M3-2-u2-X17"}],"explanation":["확인: 나누는 수 × 몫 + 나머지 = 나누어지는 수.","2 × 47 + 1 = 95예요.","은우는 나누는 수 대신 나머지를 곱했어요."],"asset":null},{"stem":"97 ÷ 2 = 48 … 1을 확인한 방법이에요. 잘못 확인한 친구는 누구인가요?","options":[{"t":"서윤 — 「2 × 48 = 96 — 97과 달라 틀렸어」","correct":true,"mis_target":"M3-2-u2-X09"},{"t":"하린 — 「2 × 48 + 1 = 97 — 맞아」","mis":"M3-2-u2-X17"},{"t":"은우 — 「나머지 1은 2보다 작고 2 × 48 + 1 = 97이라 맞아」","mis":"M3-2-u2-X17"}],"explanation":["확인: 나누는 수 × 몫 + 나머지 = 나누어지는 수.","2 × 48 + 1 = 97이에요.","서윤은 나머지를 더하지 않았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#2','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',2,'mc','auto','도서관 책 92권을 책장 8칸에 똑같이 나누어 꽂으려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":2,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"도서관 책 92권을 책장 8칸에 똑같이 나누어 꽂으려고 해요. 어떻게 되나요?","options":[{"t":"11권씩, 4권 남아요","correct":true},{"t":"10권씩, 12권 남아요","mis":"M3-2-u2-X05"},{"t":"4권씩, 11권 남아요","mis":"M3-2-u2-X06"},{"t":"11권씩, 5권 남아요","mis":"M3-2-u2-X15"}],"explanation":["92 ÷ 8 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 8 → 몫 1.","92 ÷ 8 = 11 … 4 — 11권씩, 4권 남아요."],"variant_rule":{"alt":[{"stem":"색종이 67장을 6모둠에 똑같이 나누어 주려고 해요. 어떻게 되나요?","options":[{"t":"11장씩, 1장 남아요","correct":true},{"t":"10장씩, 7장 남아요","mis":"M3-2-u2-X05"},{"t":"1장씩, 11장 남아요","mis":"M3-2-u2-X06"},{"t":"11장씩, 2장 남아요","mis":"M3-2-u2-X15"}],"explanation":["67 ÷ 6 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","십의 자리 6 ÷ 6 → 몫 1 · 일의 자리 7 ÷ 6 → 몫 1.","67 ÷ 6 = 11 … 1 — 11장씩, 1장 남아요."],"asset":null},{"stem":"옥수수 95개를 7봉지에 똑같이 나누어 담으려고 해요. 어떻게 되나요?","options":[{"t":"13개씩, 4개 남아요","correct":true},{"t":"12개씩, 11개 남아요","mis":"M3-2-u2-X05"},{"t":"4개씩, 13개 남아요","mis":"M3-2-u2-X06"},{"t":"13개씩, 5개 남아요","mis":"M3-2-u2-X15"}],"explanation":["95 ÷ 7 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 25 ÷ 7 → 몫 3.","95 ÷ 7 = 13 … 4 — 13개씩, 4개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#3','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'sa','auto','어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","7 × 13 = 91, 91 + 4 = 95예요.","확인: 95 ÷ 7 = 13 … 4."],"variant_rule":{"alt":[{"stem":"어떤 수를 2로 나누었더니 몫이 16이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","2 × 16 = 32, 32 + 1 = 33이에요.","확인: 33 ÷ 2 = 16 … 1."],"asset":null},{"stem":"어떤 수를 2로 나누었더니 몫이 38이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["77"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","2 × 38 = 76, 76 + 1 = 77이에요.","확인: 77 ÷ 2 = 38 … 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#4','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'sa','auto','은우가 91 ÷ 9를 계산하고 몫을 1이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"은우가 91 ÷ 9를 계산하고 몫을 1이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["은우 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 1은 9로 나눌 수 없어 몫 0.","바른 몫은 10 — 확인: 9 × 10 + 1 = 91이에요."],"variant_rule":{"alt":[{"stem":"시우가 98 ÷ 6을 계산하고 몫을 11이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["시우 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 38 ÷ 6 → 몫 6.","바른 몫은 16 — 확인: 6 × 16 + 2 = 98이에요."],"asset":null},{"stem":"시우가 38 ÷ 3을 계산하고 몫을 13이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["시우 — 곱셈구구나 빼기에서 실수해 몫이 1 크거나 작다.","십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 8 ÷ 3 → 몫 2.","바른 몫은 12 — 확인: 3 × 12 + 2 = 38이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#5','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'ox','auto','78 ÷ 5 = 14 … 8이에요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":5,"concept":"M3-2-u2-C7","difficulty":3,"kind":"ox","stem":"78 ÷ 5 = 14 … 8이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 28 ÷ 5 → 몫 5.","바르게 계산하면 78 ÷ 5 = 15 … 3.","나머지 < 나누는 수 — 확인: 5 × 15 + 3 = 78이에요."],"asset":{"type":"ldiv","a":78,"b":5,"upto":0},"variant_rule":{"alt":[{"stem":"69 ÷ 4 = 16 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 4 → 몫 7.","바르게 계산하면 69 ÷ 4 = 17 … 1.","나머지 < 나누는 수 — 확인: 4 × 17 + 1 = 69예요."],"asset":{"type":"ldiv","a":69,"b":4,"upto":0}},{"stem":"98 ÷ 5 = 18 … 8이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 48 ÷ 5 → 몫 9.","바르게 계산하면 98 ÷ 5 = 19 … 3.","나머지 < 나누는 수 — 확인: 5 × 19 + 3 = 98이에요."],"asset":{"type":"ldiv","a":98,"b":5,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#6','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 86 ÷ 3 ○ 93 ÷ 4',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C7","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 86 ÷ 3 ○ 93 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["86 ÷ 3의 몫은 28이에요.","93 ÷ 4의 몫은 23이에요.","28 > 23 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 87 ÷ 8 ○ 83 ÷ 5","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["87 ÷ 8의 몫은 10이에요.","83 ÷ 5의 몫은 16이에요.","10 < 16 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 80 ÷ 7 ○ 31 ÷ 2","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["80 ÷ 7의 몫은 11이에요.","31 ÷ 2의 몫은 15예요.","11 < 15 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#7','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'error','auto','95 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":3,"kind":"error","stem":"95 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「95 ÷ 4 = 32 … 3」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"하랑 — 「95 ÷ 4 = 23 … 3」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 4 × 23 + 3 = 95」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 15 ÷ 4 → 몫 3.","95 ÷ 4 = 23 … 3.","도윤이 잘못 말했어요 — 높은 자리부터 그 자리 위에."],"variant_rule":{"alt":[{"stem":"40 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「40 ÷ 3 = 10 … 1」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"시우 — 「40 ÷ 3 = 13 … 1」","mis":"M3-2-u2-X17"},{"t":"하린 — 「나머지 1은 3보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 3 → 몫 3.","40 ÷ 3 = 13 … 1.","서윤이 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null},{"stem":"62 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「62 ÷ 5 = 21 … 2」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"도윤 — 「62 ÷ 5 = 12 … 2」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 5 × 12 + 2 = 62」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 5 → 몫 2.","62 ÷ 5 = 12 … 2.","하린이 잘못 말했어요 — 높은 자리부터 그 자리 위에."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#8','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'essay','teacher','약과 67개를 어르신 5분께 똑같이 나누어 드려요. 67 ÷ 5를 세로셈으로 계산하고, 계산이 맞는지 확인하는 방법까지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"약과 67개를 어르신 5분께 똑같이 나누어 드려요. 67 ÷ 5를 세로셈으로 계산하고, 계산이 맞는지 확인하는 방법까지 써 보세요.","answer_guide":{"answer":"예: 십의 자리 6 ÷ 5 = 1 … 1, 남은 1을 내려 17 ÷ 5 = 3 … 2이다. 67 ÷ 5 = 13 … 2이므로 한 분께 13개씩 드리고 2개가 남는다. 확인: 5 × 13 = 65, 65 + 2 = 67이다.","scoring_points":["13 … 2를 구했는가","5 × 13 + 2 = 67로 확인했는가","13개씩, 2개 남는다고 답했는가"]},"explanation":["6 ÷ 5 → 1, 1 남음 · 17 ÷ 5 → 3, 2 남음.","67 ÷ 5 = 13 … 2.","5 × 13 + 2 = 67."],"asset":{"type":"ldiv","a":67,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#9','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'essay','teacher','지유는 99 ÷ 8 = 12 … 3을 「3 × 12 + 8 = 44」로 확인하고 틀렸다고 했어요. 지유의 확인에서 잘못된 점을 찾고 바르게 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"지유는 99 ÷ 8 = 12 … 3을 「3 × 12 + 8 = 44」로 확인하고 틀렸다고 했어요. 지유의 확인에서 잘못된 점을 찾고 바르게 확인해 보세요.","answer_guide":{"answer":"예: 나누는 수 8 대신 나머지 3을 몫에 곱하고 8을 더했다. 바르게 확인하면 나누는 수 × 몫 + 나머지 = 8 × 12 + 3 = 96 + 3 = 99이므로 계산은 맞다.","scoring_points":["나누는 수와 나머지를 바꾸었다고 찾았는가","8 × 12 + 3으로 확인했는가","99가 되어 맞다고 판단했는가"]},"explanation":["확인 = 나누는 수 × 몫 + 나머지.","8 × 12 = 96, 96 + 3 = 99.","99 ÷ 8 = 12 … 3은 맞아요."],"asset":{"type":"expr_grid","rows":[["8 × 12","=","96"],["96 + 3","=","99"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L07_challenge#10','math',3,2,'u2','L07','g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'mc','auto','곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":4,"kind":"mc","stem":"곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"50개","correct":true},{"t":"48개","mis":"M3-2-u2-X09"},{"t":"46개","mis":"M3-2-u2-X14"},{"t":"64개","mis":"M3-2-u2-X08"}],"explanation":["8접시에 6개씩 — 8 × 6 = 48개.","남은 2개를 더해요.","48 + 2 = 50 — 모두 50개예요."],"variant_rule":{"alt":[{"stem":"약과를 7봉지에 9개씩 담았더니 3개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"66개","correct":true},{"t":"63개","mis":"M3-2-u2-X09"},{"t":"60개","mis":"M3-2-u2-X14"},{"t":"84개","mis":"M3-2-u2-X08"}],"explanation":["7봉지에 9개씩 — 7 × 9 = 63개.","남은 3개를 더해요.","63 + 3 = 66 — 모두 66개예요."],"asset":null},{"stem":"종이꽃을 6바구니에 12개씩 담았더니 4개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"76개","correct":true},{"t":"72개","mis":"M3-2-u2-X09"},{"t":"68개","mis":"M3-2-u2-X14"},{"t":"96개","mis":"M3-2-u2-X08"}],"explanation":["6바구니에 12개씩 — 6 × 12 = 72개.","남은 4개를 더해요.","72 + 4 = 76 — 모두 76개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#1','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','8 ÷ 4 = 2예요. 그러면 800 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"8 ÷ 4 = 2예요. 그러면 800 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["800은 8의 100배예요.","나누어지는 수가 100배가 되면 몫도 100배가 돼요.","2의 100배 — 800 ÷ 4 = 200이에요."],"variant_rule":{"alt":[{"stem":"8 ÷ 8 = 1이에요. 그러면 800 ÷ 8은 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["800은 8의 100배예요.","나누어지는 수가 100배가 되면 몫도 100배가 돼요.","1의 100배 — 800 ÷ 8 = 100이에요."],"asset":null},{"stem":"4 ÷ 2 = 2예요. 그러면 400 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["400은 4의 100배예요.","나누어지는 수가 100배가 되면 몫도 100배가 돼요.","2의 100배 — 400 ÷ 2 = 200이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#2','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','840 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"840 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["420"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8 ÷ 2 → 몫 4 · 십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 0 → 몫 0.","840 ÷ 2 = 420 — 확인: 2 × 420 = 840이에요."],"variant_rule":{"alt":[{"stem":"900 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["900은 100이 9개 — 9 ÷ 9 = 1이에요.","나누어지는 수가 100배면 몫도 100배예요.","900 ÷ 9 = 100 — 확인: 9 × 100 = 900이에요."],"asset":null},{"stem":"600 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["600은 100이 6개 — 6 ÷ 6 = 1이에요.","나누어지는 수가 100배면 몫도 100배예요.","600 ÷ 6 = 100 — 확인: 6 × 100 = 600이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#3','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','307 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"307 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","307 ÷ 3 = 102 … 1 — 확인: 3 × 102 + 1 = 307이에요."],"variant_rule":{"alt":[{"stem":"920 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 2는 9로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 20 ÷ 9 → 몫 2.","920 ÷ 9 = 102 … 2 — 확인: 9 × 102 + 2 = 920이에요."],"asset":null},{"stem":"804 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8 ÷ 8 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 4는 8로 나눌 수 없어 몫 0.","804 ÷ 8 = 100 … 4 — 확인: 8 × 100 + 4 = 804예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#4','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','307 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"307 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","307 ÷ 3 = 102 … 1 — 확인: 3 × 102 + 1 = 307이에요."],"variant_rule":{"alt":[{"stem":"919 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 19 ÷ 3 → 몫 6.","919 ÷ 3 = 306 … 1 — 확인: 3 × 306 + 1 = 919예요."],"asset":null},{"stem":"960 ÷ 9의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 6은 9로 나눌 수 없어 몫 0, 6 남음 · 남은 6을 내려 60 ÷ 9 → 몫 6.","960 ÷ 9 = 106 … 6 — 확인: 9 × 106 + 6 = 960이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#5','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'mc','auto','605 ÷ 2의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":5,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"605 ÷ 2의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 5 ÷ 2 → 몫 2.","몫 302 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":605,"b":2,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"813 ÷ 2의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 8 ÷ 2 → 몫 4 · 십의 자리 1은 2로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 13 ÷ 2 → 몫 6.","몫 406 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":813,"b":2,"hide":[["q",1]]}},{"stem":"937 ÷ 9의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 3은 9로 나눌 수 없어 몫 0, 3 남음 · 남은 3을 내려 37 ÷ 9 → 몫 4.","몫 104 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":937,"b":9,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#6','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'ox','auto','307 ÷ 3 = 12 … 1이에요.',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":6,"concept":"M3-2-u2-C8","difficulty":2,"kind":"ox","stem":"307 ÷ 3 = 12 … 1이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","바르게 계산하면 307 ÷ 3 = 102 … 1.","나눌 수 없으면 몫에 0 — 확인: 3 × 102 + 1 = 307이에요."],"asset":{"type":"ldiv","a":307,"b":3,"upto":0},"variant_rule":{"alt":[{"stem":"607 ÷ 2 = 33 … 1이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 2 → 몫 3.","바르게 계산하면 607 ÷ 2 = 303 … 1.","나눌 수 없으면 몫에 0 — 확인: 2 × 303 + 1 = 607이에요."],"asset":{"type":"ldiv","a":607,"b":2,"upto":0}},{"stem":"616 ÷ 3 = 25 … 1이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 16 ÷ 3 → 몫 5.","바르게 계산하면 616 ÷ 3 = 205 … 1.","나눌 수 없으면 몫에 0 — 확인: 3 × 205 + 1 = 616이에요."],"asset":{"type":"ldiv","a":616,"b":3,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#7','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'sa','auto','638 ÷ 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"638 ÷ 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 8 ÷ 3 → 몫 2.","638 ÷ 3 = 212 … 2 — 백의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":638,"b":3,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"689 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 5 → 몫 3, 3 남음 · 남은 3을 내려 39 ÷ 5 → 몫 7.","689 ÷ 5 = 137 … 4 — 백의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":689,"b":5,"hide":[["q",0]]}},{"stem":"977 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 17 ÷ 2 → 몫 8, 1 남음 · 남은 1을 내려 17 ÷ 2 → 몫 8.","977 ÷ 2 = 488 … 1 — 백의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":977,"b":2,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#8','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'mc','auto','클립 367개를 3명에게 똑같이 나누어 주려고 해요. 한 명은 몇 개를 받나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X14']::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"클립 367개를 3명에게 똑같이 나누어 주려고 해요. 한 명은 몇 개를 받나요?","options":[{"t":"122개","correct":true},{"t":"1개","mis":"M3-2-u2-X13"},{"t":"364개","mis":"M3-2-u2-X14"},{"t":"1101개","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 367 ÷ 3으로 세워요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 7 ÷ 3 → 몫 2.","367 ÷ 3 = 122 … 1 — 122개예요. (1개 남아요.)"],"variant_rule":{"alt":[{"stem":"봉사 활동 배지 761개를 3모둠에 똑같이 나누어 주려고 해요. 한 모둠은 몇 개를 받나요?","options":[{"t":"253개","correct":true},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"758개","mis":"M3-2-u2-X14"},{"t":"2283개","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 761 ÷ 3으로 세워요.","백의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 16 ÷ 3 → 몫 5, 1 남음 · 남은 1을 내려 11 ÷ 3 → 몫 3.","761 ÷ 3 = 253 … 2 — 253개예요. (2개 남아요.)"],"asset":null},{"stem":"금잔화 모종 978개를 화단 5곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?","options":[{"t":"195개","correct":true},{"t":"3개","mis":"M3-2-u2-X13"},{"t":"973개","mis":"M3-2-u2-X14"},{"t":"4890개","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 978 ÷ 5로 세워요.","백의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 47 ÷ 5 → 몫 9, 2 남음 · 남은 2를 내려 28 ÷ 5 → 몫 5.","978 ÷ 5 = 195 … 3 — 195개예요. (3개 남아요.)"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#9','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'sa','auto','638 ÷ 3 = 212 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"638 ÷ 3 = 212 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["636"],"explanation":["나누는 수 × 몫 = 3 × 212 = 636이에요.","여기에 나머지 2를 더하면 638이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 212","=",null],["□ + 2","=","638"]]},"variant_rule":{"alt":[{"stem":"861 ÷ 2 = 430 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["861"],"explanation":["나누는 수 × 몫 = 2 × 430 = 860이에요.","여기에 나머지 1을 더하면 861이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["2 × 430","=","860"],["860 + 1","=",null]]}},{"stem":"859 ÷ 2 = 429 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["858"],"explanation":["나누는 수 × 몫 = 2 × 429 = 858이에요.","여기에 나머지 1을 더하면 859예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["2 × 429","=",null],["□ + 1","=","859"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_basic#10','math',3,2,'u2','L08','g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',3,'error','auto','409 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X10','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C8","difficulty":3,"kind":"error","stem":"409 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「409 ÷ 4 = 12 … 1」","correct":true,"mis_target":"M3-2-u2-X10"},{"t":"도윤 — 「409 ÷ 4 = 102 … 1」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「나머지 1은 4보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2.","409 ÷ 4 = 102 … 1.","하린이 잘못 말했어요 — 나눌 수 없으면 몫에 0."],"variant_rule":{"alt":[{"stem":"657 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「657 ÷ 6 = 190 … 3」","correct":true,"mis_target":"M3-2-u2-X11"},{"t":"시우 — 「657 ÷ 6 = 109 … 3」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 6 × 109 + 3 = 657」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 5는 6으로 나눌 수 없어 몫 0, 5 남음 · 남은 5를 내려 57 ÷ 6 → 몫 9.","657 ÷ 6 = 109 … 3.","하린이 잘못 말했어요 — 0은 그 자리에."],"asset":null},{"stem":"604 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「604 ÷ 2 = 32야」","correct":true,"mis_target":"M3-2-u2-X10"},{"t":"도윤 — 「604 ÷ 2 = 302야」","mis":"M3-2-u2-X17"},{"t":"하랑 — 「604 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 4 ÷ 2 → 몫 2.","604 ÷ 2 = 302.","지유가 잘못 말했어요 — 나눌 수 없으면 몫에 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#1','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',2,'sa','auto','서윤이 409 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"서윤이 409 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["서윤 — 나눌 수 없는 가운데 자리의 몫 0을 빠뜨린다.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2.","바른 몫은 102 — 확인: 4 × 102 + 1 = 409예요."],"variant_rule":{"alt":[{"stem":"은우가 739 ÷ 7을 계산하고 몫을 15라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["은우 — 나눌 수 없는 가운데 자리의 몫 0을 빠뜨린다.","백의 자리 7 ÷ 7 → 몫 1 · 십의 자리 3은 7로 나눌 수 없어 몫 0, 3 남음 · 남은 3을 내려 39 ÷ 7 → 몫 5.","바른 몫은 105 — 확인: 7 × 105 + 4 = 739예요."],"asset":null},{"stem":"서윤이 959 ÷ 9를 계산하고 몫을 16이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["106"],"explanation":["서윤 — 나눌 수 없는 가운데 자리의 몫 0을 빠뜨린다.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 5는 9로 나눌 수 없어 몫 0, 5 남음 · 남은 5를 내려 59 ÷ 9 → 몫 6.","바른 몫은 106 — 확인: 9 × 106 + 5 = 959예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#2','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',2,'mc','auto','999 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":2,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"999 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"124 … 7","correct":true},{"t":"123 … 15","mis":"M3-2-u2-X05"},{"t":"7 … 124","mis":"M3-2-u2-X06"},{"t":"124","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 8 → 몫 2, 3 남음 · 남은 3을 내려 39 ÷ 8 → 몫 4.","999 ÷ 8 = 124 … 7 — 확인: 8 × 124 + 7 = 999예요."],"variant_rule":{"alt":[{"stem":"919 ÷ 2의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"459 … 1","correct":true},{"t":"458 … 3","mis":"M3-2-u2-X05"},{"t":"1 … 459","mis":"M3-2-u2-X06"},{"t":"459","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 11 ÷ 2 → 몫 5, 1 남음 · 남은 1을 내려 19 ÷ 2 → 몫 9.","919 ÷ 2 = 459 … 1 — 확인: 2 × 459 + 1 = 919예요."],"asset":null},{"stem":"949 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"316 … 1","correct":true},{"t":"315 … 4","mis":"M3-2-u2-X05"},{"t":"1 … 316","mis":"M3-2-u2-X06"},{"t":"316","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 3 → 몫 6.","949 ÷ 3 = 316 … 1 — 확인: 3 × 316 + 1 = 949예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#3','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'ox','auto','615 ÷ 6 = 120 … 3이에요.',ARRAY['M3-2-u2-X11']::text[],true,'{"seq":3,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"615 ÷ 6 = 120 … 3이에요.","answer":"X","reason_options":[{"t":"몫의 0은 나눌 수 없는 그 자리에 써야 해서","correct":true},{"t":"0은 끝에 붙이면 되어서","mis":"M3-2-u2-X11"}],"mis":"M3-2-u2-X11","explanation":["백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 1은 6으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 15 ÷ 6 → 몫 2.","바르게 계산하면 615 ÷ 6 = 102 … 3.","0은 그 자리에 — 확인: 6 × 102 + 3 = 615예요."],"variant_rule":{"alt":[{"stem":"828 ÷ 4 = 270이에요.","answer":"X","reason_options":[{"t":"몫의 0은 나눌 수 없는 그 자리에 써야 해서","correct":true},{"t":"0은 끝에 붙이면 되어서","mis":"M3-2-u2-X11"}],"explanation":["백의 자리 8 ÷ 4 → 몫 2 · 십의 자리 2는 4로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 28 ÷ 4 → 몫 7.","바르게 계산하면 828 ÷ 4 = 207.","0은 그 자리에 — 확인: 4 × 207 = 828이에요."],"asset":null},{"stem":"974 ÷ 9 = 180 … 2예요.","answer":"X","reason_options":[{"t":"몫의 0은 나눌 수 없는 그 자리에 써야 해서","correct":true},{"t":"0은 끝에 붙이면 되어서","mis":"M3-2-u2-X11"}],"explanation":["백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 7은 9로 나눌 수 없어 몫 0, 7 남음 · 남은 7을 내려 74 ÷ 9 → 몫 8.","바르게 계산하면 974 ÷ 9 = 108 … 2.","0은 그 자리에 — 확인: 9 × 108 + 2 = 974예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#4','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'match','auto','나눗셈식과 몫 … 나머지를 알맞게 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":3,"kind":"match","stem":"나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"745 ÷ 3","r":"248 … 1"},{"l":"757 ÷ 3","r":"252 … 1"},{"l":"713 ÷ 3","r":"237 … 2"}],"mis":"M3-2-u2-X03","explanation":["높은 자리부터 차례로 나누어요.","745 ÷ 3 = 248 … 1, 757 ÷ 3 = 252 … 1, 713 ÷ 3 = 237 … 2.","나누는 수 × 몫 + 나머지로 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"854 ÷ 6","r":"142 … 2"},{"l":"454 ÷ 3","r":"151 … 1"},{"l":"925 ÷ 7","r":"132 … 1"}],"explanation":["높은 자리부터 차례로 나누어요.","854 ÷ 6 = 142 … 2, 454 ÷ 3 = 151 … 1, 925 ÷ 7 = 132 … 1.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫 … 나머지를 알맞게 이으세요.","pairs":[{"l":"461 ÷ 3","r":"153 … 2"},{"l":"996 ÷ 2","r":"498"},{"l":"655 ÷ 3","r":"218 … 1"}],"explanation":["높은 자리부터 차례로 나누어요.","461 ÷ 3 = 153 … 2, 996 ÷ 2 = 498, 655 ÷ 3 = 218 … 1.","나누는 수 × 몫 + 나머지로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#5','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'sa','auto','약과 840개를 어르신 2분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C8","difficulty":3,"kind":"sa","stem":"약과 840개를 어르신 2분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요? 숫자로 쓰세요.","answer":["420"],"explanation":["똑같이 나누는 상황 — 나눗셈식 840 ÷ 2로 세워요.","백의 자리 8 ÷ 2 → 몫 4 · 십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 0 → 몫 0.","840 ÷ 2 = 420 — 420개예요."],"variant_rule":{"alt":[{"stem":"도서관 책 800권을 책장 4칸에 똑같이 나누어 꽂으려고 해요. 한 칸에 몇 권씩 꽂나요? 숫자로 쓰세요.","answer":["200"],"explanation":["똑같이 나누는 상황 — 나눗셈식 800 ÷ 4로 세워요.","나누어지는 수가 100배면 몫도 100배예요.","800 ÷ 4 = 200 — 200권이에요."],"asset":null},{"stem":"색종이 330장을 3모둠에 똑같이 나누어 주려고 해요. 한 모둠은 몇 장씩 받나요? 숫자로 쓰세요.","answer":["110"],"explanation":["똑같이 나누는 상황 — 나눗셈식 330 ÷ 3으로 세워요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 0 → 몫 0.","330 ÷ 3 = 110 — 110장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#6','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'mc','auto','몫을 견주어 ○ 안에 알맞은 것을 고르세요. 638 ÷ 3 ○ 398 ÷ 2',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C8","difficulty":3,"kind":"mc","stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 638 ÷ 3 ○ 398 ÷ 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["638 ÷ 3의 몫은 212예요.","398 ÷ 2의 몫은 199예요.","212 > 199 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 806 ÷ 5 ○ 622 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["806 ÷ 5의 몫은 161이에요.","622 ÷ 4의 몫은 155예요.","161 > 155 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"몫을 견주어 ○ 안에 알맞은 것을 고르세요. 942 ÷ 4 ○ 462 ÷ 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없다","mis":"M3-2-u2-X17"}],"explanation":["942 ÷ 4의 몫은 235예요.","462 ÷ 2의 몫은 231이에요.","235 > 231 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#7','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'error','auto','999 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C8","difficulty":3,"kind":"error","stem":"999 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「999 ÷ 8 = 111 … 7」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"은우 — 「999 ÷ 8 = 124 … 7」","mis":"M3-2-u2-X17"},{"t":"하린 — 「나머지 7은 8보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 8 → 몫 2, 3 남음 · 남은 3을 내려 39 ÷ 8 → 몫 4.","999 ÷ 8 = 124 … 7.","도윤이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"383 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「383 ÷ 2 = 192 — 나누어떨어져요」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「383 ÷ 2 = 191 … 1」","mis":"M3-2-u2-X17"},{"t":"하린 — 「확인하면 2 × 191 + 1 = 383」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 2 → 몫 9 · 일의 자리 3 ÷ 2 → 몫 1.","383 ÷ 2 = 191 … 1.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"584 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「584 ÷ 4 = 121이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지유 — 「584 ÷ 4 = 146이야」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「584 ÷ 4는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4, 2 남음 · 남은 2를 내려 24 ÷ 4 → 몫 6.","584 ÷ 4 = 146.","태오가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#8','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'essay','teacher','도서관 책 307권을 책장 3칸에 똑같이 나누어 꽂아요. 307 ÷ 3을 계산하는 방법을 쓰고, 몫의 0을 빠뜨리면 어떻게 되는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"도서관 책 307권을 책장 3칸에 똑같이 나누어 꽂아요. 307 ÷ 3을 계산하는 방법을 쓰고, 몫의 0을 빠뜨리면 어떻게 되는지 설명해 보세요.","answer_guide":{"answer":"예: 백의 자리 3 ÷ 3 = 1, 십의 자리 0은 3으로 나눌 수 없어 몫에 0을 쓰고, 일의 자리 7 ÷ 3 = 2 … 1이다. 307 ÷ 3 = 102 … 1이다. 0을 빠뜨려 12 … 1이라고 하면 3 × 12 + 1 = 37이 되어 307과 아주 달라진다.","scoring_points":["몫의 십의 자리에 0을 썼는가","102 … 1을 구했는가","0을 빠뜨리면 확인 값이 달라진다고 설명했는가"]},"explanation":["3 ÷ 3 = 1 · 십의 자리 0 → 몫 0 · 7 ÷ 3 = 2 … 1.","307 ÷ 3 = 102 … 1.","12 … 1 → 3 × 12 + 1 = 37 ≠ 307."],"asset":{"type":"ldiv","a":307,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#9','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'essay','teacher','800 ÷ 4와 840 ÷ 4의 몫을 각각 구하고, 두 몫이 얼마나 차이 나는지 그 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"800 ÷ 4와 840 ÷ 4의 몫을 각각 구하고, 두 몫이 얼마나 차이 나는지 그 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 8 ÷ 4 = 2이고 800은 8의 100배이므로 800 ÷ 4 = 200이다. 840 ÷ 4는 백의 자리 8 ÷ 4 = 2, 십의 자리 4 ÷ 4 = 1, 일의 자리 0이므로 210이다. 840은 800보다 40 크고 40 ÷ 4 = 10이므로 몫이 10 차이 난다.","scoring_points":["800 ÷ 4 = 200을 구했는가","840 ÷ 4 = 210을 구했는가","40 ÷ 4 = 10으로 차이를 설명했는가"]},"explanation":["800 ÷ 4 = 200.","840 ÷ 4 = 210.","차이 40 ÷ 4 = 10."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L08_challenge#10','math',3,2,'u2','L08','g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'sa','auto','어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C8","difficulty":4,"kind":"sa","stem":"어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["638"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","3 × 212 = 636, 636 + 2 = 638이에요.","확인: 638 ÷ 3 = 212 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 7로 나누었더니 몫이 122이고 나머지가 5가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["859"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","7 × 122 = 854, 854 + 5 = 859예요.","확인: 859 ÷ 7 = 122 … 5."],"asset":null},{"stem":"어떤 수를 5로 나누었더니 몫이 143이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["719"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","5 × 143 = 715, 715 + 4 = 719예요.","확인: 719 ÷ 5 = 143 … 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#1','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'sa','auto','258 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C9","difficulty":1,"kind":"sa","stem":"258 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","258 ÷ 4 = 64 … 2 — 확인: 4 × 64 + 2 = 258이에요."],"variant_rule":{"alt":[{"stem":"651 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 65로 보고 65 ÷ 7 → 몫 9, 2 남음 · 남은 2를 내려 21 ÷ 7 → 몫 3.","651 ÷ 7 = 93 — 확인: 7 × 93 = 651이에요."],"asset":null},{"stem":"268 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 26으로 보고 26 ÷ 8 → 몫 3, 2 남음 · 남은 2를 내려 28 ÷ 8 → 몫 3.","268 ÷ 8 = 33 … 4 — 확인: 8 × 33 + 4 = 268이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#2','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'sa','auto','197 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C9","difficulty":1,"kind":"sa","stem":"197 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 19로 보고 19 ÷ 3 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 3 → 몫 5.","197 ÷ 3 = 65 … 2 — 확인: 3 × 65 + 2 = 197이에요."],"variant_rule":{"alt":[{"stem":"211 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 21로 보고 21 ÷ 4 → 몫 5, 1 남음 · 남은 1을 내려 11 ÷ 4 → 몫 2.","211 ÷ 4 = 52 … 3 — 확인: 4 × 52 + 3 = 211이에요."],"asset":null},{"stem":"303 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 30으로 보고 30 ÷ 6 → 몫 5 · 일의 자리 3은 6으로 나눌 수 없어 몫 0.","303 ÷ 6 = 50 … 3 — 확인: 6 × 50 + 3 = 303이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#3','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'mc','auto','258 ÷ 4의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":3,"concept":"M3-2-u2-C9","difficulty":1,"kind":"mc","stem":"258 ÷ 4의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 2와 나누는 수 4와 견주어요.","2는 4보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","258 ÷ 4 = 64 … 2."],"variant_rule":{"alt":[{"stem":"168 ÷ 8의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 1과 나누는 수 8과 견주어요.","1은 8보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","168 ÷ 8 = 21."],"asset":null},{"stem":"339 ÷ 6의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 3과 나누는 수 6과 견주어요.","3은 6보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","339 ÷ 6 = 56 … 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#4','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C4',1,'mc','auto','258 ÷ 4를 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":4,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"258 ÷ 4를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"60과 70 사이","correct":true},{"t":"60보다 작아요","mis":"M3-2-u2-X16"},{"t":"70보다 커요","mis":"M3-2-u2-X16"},{"t":"600과 700 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","4 × 60 = 240, 4 × 70 = 280 — 258은 그 사이에 있어요.","그래서 몫은 60과 70 사이 — 실제 몫 64예요."],"variant_rule":{"alt":[{"stem":"207 ÷ 4를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"50과 60 사이","correct":true},{"t":"50보다 작아요","mis":"M3-2-u2-X16"},{"t":"60보다 커요","mis":"M3-2-u2-X16"},{"t":"500과 600 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","4 × 50 = 200, 4 × 60 = 240 — 207은 그 사이에 있어요.","그래서 몫은 50과 60 사이 — 실제 몫 51이에요."],"asset":null},{"stem":"163 ÷ 8을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"20과 30 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"30보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 300 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","8 × 20 = 160, 8 × 30 = 240 — 163은 그 사이에 있어요.","그래서 몫은 20과 30 사이 — 실제 몫 20이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#5','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'sa','auto','438 ÷ 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"438 ÷ 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 4는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 43으로 보고 43 ÷ 9 → 몫 4, 7 남음 · 남은 7을 내려 78 ÷ 9 → 몫 8.","438 ÷ 9 = 48 … 6 — 일의 자리 숫자는 8이에요."],"asset":{"type":"ldiv","a":438,"b":9,"hide":[["q",2]]},"variant_rule":{"alt":[{"stem":"504 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 5는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 50으로 보고 50 ÷ 6 → 몫 8, 2 남음 · 남은 2를 내려 24 ÷ 6 → 몫 4.","504 ÷ 6 = 84 — 일의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":504,"b":6,"hide":[["q",2]]}},{"stem":"468 ÷ 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 백의 자리 4는 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 46으로 보고 46 ÷ 8 → 몫 5, 6 남음 · 남은 6을 내려 68 ÷ 8 → 몫 8.","468 ÷ 8 = 58 … 4 — 십의 자리 숫자는 5예요."],"asset":{"type":"ldiv","a":468,"b":8,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#6','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'mc','auto','금잔화 모종 341개를 화단 4곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X14']::text[],true,'{"seq":6,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"금잔화 모종 341개를 화단 4곳에 똑같이 나누어 심으려고 해요. 한 화단에 몇 개씩 심나요?","options":[{"t":"85개","correct":true},{"t":"1개","mis":"M3-2-u2-X13"},{"t":"337개","mis":"M3-2-u2-X14"},{"t":"1364개","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 341 ÷ 4로 세워요.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 4 → 몫 8, 2 남음 · 남은 2를 내려 21 ÷ 4 → 몫 5.","341 ÷ 4 = 85 … 1 — 85개예요. (1개 남아요.)"],"variant_rule":{"alt":[{"stem":"손수건 454장을 9명이 똑같이 나누어 가지려고 해요. 한 명은 몇 장씩 가지나요?","options":[{"t":"50장","correct":true},{"t":"4장","mis":"M3-2-u2-X13"},{"t":"445장","mis":"M3-2-u2-X14"},{"t":"4086장","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 454 ÷ 9로 세워요.","백의 자리 4는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 45로 보고 45 ÷ 9 → 몫 5 · 일의 자리 4는 9로 나눌 수 없어 몫 0.","454 ÷ 9 = 50 … 4 — 50장이에요. (4장 남아요.)"],"asset":null},{"stem":"약과 390개를 어르신 7분께 똑같이 나누어 드리려고 해요. 한 분께 몇 개씩 드리나요?","options":[{"t":"55개","correct":true},{"t":"5개","mis":"M3-2-u2-X13"},{"t":"383개","mis":"M3-2-u2-X14"},{"t":"2730개","mis":"M3-2-u2-X14"}],"explanation":["똑같이 나누는 상황 — 나눗셈식 390 ÷ 7로 세워요.","백의 자리 3은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 39로 보고 39 ÷ 7 → 몫 5, 4 남음 · 남은 4를 내려 40 ÷ 7 → 몫 5.","390 ÷ 7 = 55 … 5 — 55개예요. (5개 남아요.)"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#7','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'ox','auto','485 ÷ 5는 세 자리 수를 나누는 것이니 몫도 세 자리 수예요.',ARRAY['M3-2-u2-X12']::text[],true,'{"seq":7,"concept":"M3-2-u2-C9","difficulty":2,"kind":"ox","stem":"485 ÷ 5는 세 자리 수를 나누는 것이니 몫도 세 자리 수예요.","answer":"X","reason_options":[{"t":"백의 자리 4가 나누는 수 5보다 작아서","correct":true},{"t":"나누어지는 수와 몫은 자리 수가 같아서","mis":"M3-2-u2-X12"}],"mis":"M3-2-u2-X12","explanation":["백의 자리 4는 5로 나눌 수 없어 십의 자리까지 함께 48로 봐요.","백의 자리 4는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 48로 보고 48 ÷ 5 → 몫 9, 3 남음 · 남은 3을 내려 35 ÷ 5 → 몫 7.","485 ÷ 5 = 97 — 몫은 두 자리예요."],"asset":{"type":"ldiv","a":485,"b":5,"upto":0},"variant_rule":{"alt":[{"stem":"229 ÷ 7은 세 자리 수를 나누는 것이니 몫도 세 자리 수예요.","answer":"X","reason_options":[{"t":"백의 자리 2가 나누는 수 7보다 작아서","correct":true},{"t":"나누어지는 수와 몫은 자리 수가 같아서","mis":"M3-2-u2-X12"}],"explanation":["백의 자리 2는 7로 나눌 수 없어 십의 자리까지 함께 22로 봐요.","백의 자리 2는 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 22로 보고 22 ÷ 7 → 몫 3, 1 남음 · 남은 1을 내려 19 ÷ 7 → 몫 2.","229 ÷ 7 = 32 … 5 — 몫은 두 자리예요."],"asset":{"type":"ldiv","a":229,"b":7,"upto":0}},{"stem":"697 ÷ 9는 세 자리 수를 나누는 것이니 몫도 세 자리 수예요.","answer":"X","reason_options":[{"t":"백의 자리 6이 나누는 수 9보다 작아서","correct":true},{"t":"나누어지는 수와 몫은 자리 수가 같아서","mis":"M3-2-u2-X12"}],"explanation":["백의 자리 6은 9로 나눌 수 없어 십의 자리까지 함께 69로 봐요.","백의 자리 6은 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 69로 보고 69 ÷ 9 → 몫 7, 6 남음 · 남은 6을 내려 67 ÷ 9 → 몫 7.","697 ÷ 9 = 77 … 4 — 몫은 두 자리예요."],"asset":{"type":"ldiv","a":697,"b":9,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#8','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'mc','auto','496 ÷ 6에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M3-2-u2-X12','M3-2-u2-X07','M3-2-u2-X05']::text[],true,'{"seq":8,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"496 ÷ 6에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"몫은 100보다 작아요","correct":true},{"t":"몫은 100보다 커요","mis":"M3-2-u2-X12"},{"t":"나누어떨어져요","mis":"M3-2-u2-X07"},{"t":"나머지는 6이에요","mis":"M3-2-u2-X05"}],"explanation":["6 × 100 = 600 — 496과 견주어요.","496은 600보다 작으니 몫은 100보다 작아요.","496 ÷ 6 = 82 … 4."],"variant_rule":{"alt":[{"stem":"446 ÷ 8에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"몫은 100보다 작아요","correct":true},{"t":"몫은 100보다 커요","mis":"M3-2-u2-X12"},{"t":"나누어떨어져요","mis":"M3-2-u2-X07"},{"t":"나머지는 8이에요","mis":"M3-2-u2-X05"}],"explanation":["8 × 100 = 800 — 446과 견주어요.","446은 800보다 작으니 몫은 100보다 작아요.","446 ÷ 8 = 55 … 6."],"asset":null},{"stem":"167 ÷ 8에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"몫은 100보다 작아요","correct":true},{"t":"몫은 100보다 커요","mis":"M3-2-u2-X12"},{"t":"나누어떨어져요","mis":"M3-2-u2-X07"},{"t":"나머지는 8이에요","mis":"M3-2-u2-X05"}],"explanation":["8 × 100 = 800 — 167과 견주어요.","167은 800보다 작으니 몫은 100보다 작아요.","167 ÷ 8 = 20 … 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#9','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'mc','auto','257 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"257 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"64 … 1","correct":true},{"t":"63 … 5","mis":"M3-2-u2-X05"},{"t":"1 … 64","mis":"M3-2-u2-X06"},{"t":"64","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 4 → 몫 4.","257 ÷ 4 = 64 … 1 — 확인: 4 × 64 + 1 = 257이에요."],"variant_rule":{"alt":[{"stem":"451 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"75 … 1","correct":true},{"t":"74 … 7","mis":"M3-2-u2-X05"},{"t":"1 … 75","mis":"M3-2-u2-X06"},{"t":"75","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 45로 보고 45 ÷ 6 → 몫 7, 3 남음 · 남은 3을 내려 31 ÷ 6 → 몫 5.","451 ÷ 6 = 75 … 1 — 확인: 6 × 75 + 1 = 451이에요."],"asset":null},{"stem":"867 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"96 … 3","correct":true},{"t":"95 … 12","mis":"M3-2-u2-X05"},{"t":"3 … 96","mis":"M3-2-u2-X06"},{"t":"96","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8은 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 86으로 보고 86 ÷ 9 → 몫 9, 5 남음 · 남은 5를 내려 57 ÷ 9 → 몫 6.","867 ÷ 9 = 96 … 3 — 확인: 9 × 96 + 3 = 867이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_basic#10','math',3,2,'u2','L09','g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',3,'error','auto','487 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C9","difficulty":3,"kind":"error","stem":"487 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「487 ÷ 5 = 97 … 3」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태오 — 「487 ÷ 5 = 97 … 2」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 5 × 97 + 2 = 487」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 4는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 48로 보고 48 ÷ 5 → 몫 9, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","487 ÷ 5 = 97 … 2.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"745 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「745 ÷ 8 = 930 … 1」","correct":true,"mis_target":"M3-2-u2-X12"},{"t":"하랑 — 「745 ÷ 8 = 93 … 1」","mis":"M3-2-u2-X17"},{"t":"하린 — 「나머지 1은 8보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 7은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 74로 보고 74 ÷ 8 → 몫 9, 2 남음 · 남은 2를 내려 25 ÷ 8 → 몫 3.","745 ÷ 8 = 93 … 1.","지유가 잘못 말했어요 — 백의 자리 < 나누는 수면 몫은 두 자리."],"asset":null},{"stem":"439 ÷ 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「439 ÷ 9 = 48 … 8」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"도윤 — 「439 ÷ 9 = 48 … 7」","mis":"M3-2-u2-X17"},{"t":"하린 — 「확인하면 9 × 48 + 7 = 439」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 4는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 43으로 보고 43 ÷ 9 → 몫 4, 7 남음 · 남은 7을 내려 79 ÷ 9 → 몫 8.","439 ÷ 9 = 48 … 7.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#1','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',2,'mc','auto','831 ÷ 7의 몫은 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":1,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"831 ÷ 7의 몫은 얼마인가요?","options":[{"t":"118","correct":true},{"t":"100","mis":"M3-2-u2-X03"},{"t":"811","mis":"M3-2-u2-X04"},{"t":"119","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 7 → 몫 1, 6 남음 · 남은 6을 내려 61 ÷ 7 → 몫 8.","831 ÷ 7 = 118 … 5 — 확인: 7 × 118 + 5 = 831이에요."],"variant_rule":{"alt":[{"stem":"350 ÷ 3의 몫은 얼마인가요?","options":[{"t":"116","correct":true},{"t":"110","mis":"M3-2-u2-X03"},{"t":"611","mis":"M3-2-u2-X04"},{"t":"117","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 5 ÷ 3 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 3 → 몫 6.","350 ÷ 3 = 116 … 2 — 확인: 3 × 116 + 2 = 350이에요."],"asset":null},{"stem":"589 ÷ 5의 몫은 얼마인가요?","options":[{"t":"117","correct":true},{"t":"111","mis":"M3-2-u2-X03"},{"t":"711","mis":"M3-2-u2-X04"},{"t":"118","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 39 ÷ 5 → 몫 7.","589 ÷ 5 = 117 … 4 — 확인: 5 × 117 + 4 = 589예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#2','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C4',2,'ox','auto','485 ÷ 5를 계산했더니 몫이 970이 나왔어요. 어림해 보면 알맞은 몫이에요.',ARRAY['M3-2-u2-X16']::text[],true,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":2,"kind":"ox","stem":"485 ÷ 5를 계산했더니 몫이 970이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"mis":"M3-2-u2-X16","explanation":["5 × 90 = 450, 5 × 100 = 500 — 몫은 90과 100 사이예요.","970은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 97 — 확인: 5 × 97 = 485예요."],"variant_rule":{"alt":[{"stem":"458 ÷ 5를 계산했더니 몫이 910이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["5 × 90 = 450, 5 × 100 = 500 — 몫은 90과 100 사이예요.","910은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 91 — 확인: 5 × 91 + 3 = 458이에요."],"asset":null},{"stem":"237 ÷ 3을 계산했더니 몫이 790이 나왔어요. 어림해 보면 알맞은 몫이에요.","answer":"X","reason_options":[{"t":"어림한 몫과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u2-X16"}],"explanation":["3 × 70 = 210, 3 × 80 = 240 — 몫은 70과 80 사이예요.","790은 그 사이에 있지 않아 틀린 몫이에요.","바른 몫은 79 — 확인: 3 × 79 = 237이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#3','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'ox','auto','258 ÷ 4 = 640 … 2예요.',ARRAY['M3-2-u2-X12']::text[],true,'{"seq":3,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"258 ÷ 4 = 640 … 2예요.","answer":"X","reason_options":[{"t":"백의 자리가 나누는 수보다 작으면 몫은 두 자리라서","correct":true},{"t":"세 자리 수를 나누면 몫도 세 자리라서","mis":"M3-2-u2-X12"}],"mis":"M3-2-u2-X12","explanation":["백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","바르게 계산하면 258 ÷ 4 = 64 … 2.","백의 자리 < 나누는 수면 몫은 두 자리 — 확인: 4 × 64 + 2 = 258이에요."],"asset":{"type":"ldiv","a":258,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"213 ÷ 7 = 300 … 3이에요.","answer":"X","reason_options":[{"t":"백의 자리가 나누는 수보다 작으면 몫은 두 자리라서","correct":true},{"t":"세 자리 수를 나누면 몫도 세 자리라서","mis":"M3-2-u2-X12"}],"explanation":["백의 자리 2는 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 21로 보고 21 ÷ 7 → 몫 3 · 일의 자리 3은 7로 나눌 수 없어 몫 0.","바르게 계산하면 213 ÷ 7 = 30 … 3.","백의 자리 < 나누는 수면 몫은 두 자리 — 확인: 7 × 30 + 3 = 213이에요."],"asset":{"type":"ldiv","a":213,"b":7,"upto":0}},{"stem":"322 ÷ 5 = 640 … 2예요.","answer":"X","reason_options":[{"t":"백의 자리가 나누는 수보다 작으면 몫은 두 자리라서","correct":true},{"t":"세 자리 수를 나누면 몫도 세 자리라서","mis":"M3-2-u2-X12"}],"explanation":["백의 자리 3은 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 32로 보고 32 ÷ 5 → 몫 6, 2 남음 · 남은 2를 내려 22 ÷ 5 → 몫 4.","바르게 계산하면 322 ÷ 5 = 64 … 2.","백의 자리 < 나누는 수면 몫은 두 자리 — 확인: 5 × 64 + 2 = 322예요."],"asset":{"type":"ldiv","a":322,"b":5,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#4','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'sa','auto','시우가 487 ÷ 5를 계산하고 몫을 79라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C9","difficulty":3,"kind":"sa","stem":"시우가 487 ÷ 5를 계산하고 몫을 79라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["시우 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","백의 자리 4는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 48로 보고 48 ÷ 5 → 몫 9, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","바른 몫은 97 — 확인: 5 × 97 + 2 = 487이에요."],"variant_rule":{"alt":[{"stem":"태오가 364 ÷ 7을 계산하고 몫을 25라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["태오 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","백의 자리 3은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 36으로 보고 36 ÷ 7 → 몫 5, 1 남음 · 남은 1을 내려 14 ÷ 7 → 몫 2.","바른 몫은 52 — 확인: 7 × 52 = 364예요."],"asset":null},{"stem":"지유가 392 ÷ 4를 계산하고 몫을 89라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["지유 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 39로 보고 39 ÷ 4 → 몫 9, 3 남음 · 남은 3을 내려 32 ÷ 4 → 몫 8.","바른 몫은 98 — 확인: 4 × 98 = 392예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#5','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'sa','auto','어떤 수를 9로 나누었더니 몫이 67이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C9","difficulty":3,"kind":"sa","stem":"어떤 수를 9로 나누었더니 몫이 67이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["605"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","9 × 67 = 603, 603 + 2 = 605예요.","확인: 605 ÷ 9 = 67 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 8로 나누었더니 몫이 13이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["106"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","8 × 13 = 104, 104 + 2 = 106이에요.","확인: 106 ÷ 8 = 13 … 2."],"asset":null},{"stem":"어떤 수를 5로 나누었더니 몫이 73이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["369"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","5 × 73 = 365, 365 + 4 = 369예요.","확인: 369 ÷ 5 = 73 … 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#6','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'ox','auto','257 ÷ 4 = 63 … 5예요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":6,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"257 ÷ 4 = 63 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 4 → 몫 4.","바르게 계산하면 257 ÷ 4 = 64 … 1.","나머지 < 나누는 수 — 확인: 4 × 64 + 1 = 257이에요."],"asset":{"type":"ldiv","a":257,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"130 ÷ 7 = 17 … 11이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 1은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 13으로 보고 13 ÷ 7 → 몫 1, 6 남음 · 남은 6을 내려 60 ÷ 7 → 몫 8.","바르게 계산하면 130 ÷ 7 = 18 … 4.","나머지 < 나누는 수 — 확인: 7 × 18 + 4 = 130이에요."],"asset":{"type":"ldiv","a":130,"b":7,"upto":0}},{"stem":"609 ÷ 9 = 66 … 15예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 6은 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 60으로 보고 60 ÷ 9 → 몫 6, 6 남음 · 남은 6을 내려 69 ÷ 9 → 몫 7.","바르게 계산하면 609 ÷ 9 = 67 … 6.","나머지 < 나누는 수 — 확인: 9 × 67 + 6 = 609예요."],"asset":{"type":"ldiv","a":609,"b":9,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#7','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'error','auto','526 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X11','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C9","difficulty":3,"kind":"error","stem":"526 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「526 ÷ 5 = 150 … 1」","correct":true,"mis_target":"M3-2-u2-X11"},{"t":"도윤 — 「526 ÷ 5 = 105 … 1」","mis":"M3-2-u2-X17"},{"t":"시우 — 「확인하면 5 × 105 + 1 = 526」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 2는 5로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 26 ÷ 5 → 몫 5.","526 ÷ 5 = 105 … 1.","지유가 잘못 말했어요 — 0은 그 자리에."],"variant_rule":{"alt":[{"stem":"730 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「730 ÷ 7 = 14 … 2」","correct":true,"mis_target":"M3-2-u2-X10"},{"t":"서윤 — 「730 ÷ 7 = 104 … 2」","mis":"M3-2-u2-X17"},{"t":"은우 — 「나머지 2는 7보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 7 ÷ 7 → 몫 1 · 십의 자리 3은 7로 나눌 수 없어 몫 0, 3 남음 · 남은 3을 내려 30 ÷ 7 → 몫 4.","730 ÷ 7 = 104 … 2.","태오가 잘못 말했어요 — 나눌 수 없으면 몫에 0."],"asset":null},{"stem":"613 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「613 ÷ 2 = 360 … 1」","correct":true,"mis_target":"M3-2-u2-X11"},{"t":"태오 — 「613 ÷ 2 = 306 … 1」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「확인하면 2 × 306 + 1 = 613」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 1은 2로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 13 ÷ 2 → 몫 6.","613 ÷ 2 = 306 … 1.","시우가 잘못 말했어요 — 0은 그 자리에."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#8','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'essay','teacher','종이 526장을 5모둠에 똑같이 나누어 줘요. 한 모둠이 받는 종이를 어림하고, 526 ÷ 5를 계산한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C9","difficulty":4,"kind":"essay","stem":"종이 526장을 5모둠에 똑같이 나누어 줘요. 한 모둠이 받는 종이를 어림하고, 526 ÷ 5를 계산한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 526은 500보다 조금 크고 500 ÷ 5 = 100이므로 약 100장이다. 백의 자리 5 ÷ 5 = 1, 십의 자리 2는 5로 나눌 수 없어 몫에 0, 남은 2를 내려 26 ÷ 5 = 5 … 1이다. 526 ÷ 5 = 105 … 1이므로 한 모둠이 105장씩 받고 1장이 남는다. 어림한 100장과 가깝다.","scoring_points":["500 ÷ 5 = 100으로 어림했는가","105 … 1을 구했는가","어림과 견주었는가"]},"explanation":["어림 500 ÷ 5 = 100.","5 ÷ 5 = 1 · 2 → 몫 0 · 26 ÷ 5 = 5 … 1.","526 ÷ 5 = 105 … 1 — 100과 가까워요."],"asset":{"type":"ldiv","a":526,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#9','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'essay','teacher','258 ÷ 4의 몫이 몇 자리 수인지 계산하기 전에 알아보는 방법을 설명하고, 몫과 나머지를 구해 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":4,"kind":"essay","stem":"258 ÷ 4의 몫이 몇 자리 수인지 계산하기 전에 알아보는 방법을 설명하고, 몫과 나머지를 구해 확인해 보세요.","answer_guide":{"answer":"예: 백의 자리 2는 4보다 작아 백의 자리에는 몫이 서지 않으므로 몫은 두 자리 수이다. 25 ÷ 4 = 6 … 1, 남은 1을 내려 18 ÷ 4 = 4 … 2이므로 258 ÷ 4 = 64 … 2이다. 확인: 4 × 64 + 2 = 258.","scoring_points":["백의 자리와 나누는 수를 견주어 두 자리라고 했는가","64 … 2를 구했는가","4 × 64 + 2 = 258로 확인했는가"]},"explanation":["2 < 4 → 몫은 두 자리.","25 ÷ 4 → 6, 1 남음 · 18 ÷ 4 → 4, 2 남음.","4 × 64 + 2 = 258."],"asset":{"type":"ldiv","a":258,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L09_challenge#10','math',3,2,'u2','L09','g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'sa','auto','어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1032가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u2-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1032가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["어떤 수 × 4 = 1032 → 어떤 수는 1032 ÷ 4 = 258이에요.","바르게 계산하면 258 ÷ 4.","258 ÷ 4 = 64 … 2 — 몫은 64예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1364가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["어떤 수 × 4 = 1364 → 어떤 수는 1364 ÷ 4 = 341이에요.","바르게 계산하면 341 ÷ 4.","341 ÷ 4 = 85 … 1 — 몫은 85예요."],"asset":null},{"stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 591이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["어떤 수 × 3 = 591 → 어떤 수는 591 ÷ 3 = 197이에요.","바르게 계산하면 197 ÷ 3.","197 ÷ 3 = 65 … 2 — 몫은 65예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#1','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["120"],"explanation":["블록 수 ÷ 열쇠고리 수 — 480 ÷ 4.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 0 → 몫 0.","480 ÷ 4 = 120 — 한 개에 120개씩."],"variant_rule":{"alt":[{"stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 노란색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["25"],"explanation":["블록 수 ÷ 열쇠고리 수 — 150 ÷ 6.","백의 자리 1은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 15로 보고 15 ÷ 6 → 몫 2, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","150 ÷ 6 = 25 — 한 개에 25개씩."],"asset":null},{"stem":"정후가 회색 블록 690개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 회색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["230"],"explanation":["블록 수 ÷ 열쇠고리 수 — 690 ÷ 3.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 0 → 몫 0.","690 ÷ 3 = 230 — 한 개에 230개씩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#2','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남는 블록은 나머지예요 — 687 ÷ 4.","백의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 28 ÷ 4 → 몫 7 · 일의 자리 7 ÷ 4 → 몫 1.","687 ÷ 4 = 171 … 3 — 남는 블록 3개."],"variant_rule":{"alt":[{"stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리를 만들고 남는 흰색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남는 블록은 나머지예요 — 341 ÷ 6.","백의 자리 3은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 6 → 몫 5, 4 남음 · 남은 4를 내려 41 ÷ 6 → 몫 6.","341 ÷ 6 = 56 … 5 — 남는 블록 5개."],"asset":null},{"stem":"정후가 검은색 블록 314개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남는 블록은 나머지예요 — 314 ÷ 3.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 14 ÷ 3 → 몫 4.","314 ÷ 3 = 104 … 2 — 남는 블록 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#3','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["85"],"explanation":["블록 수 ÷ 열쇠고리 수 — 341 ÷ 4.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 4 → 몫 8, 2 남음 · 남은 2를 내려 21 ÷ 4 → 몫 5.","341 ÷ 4 = 85 … 1 — 한 개에 85개씩, 1개 남아요."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 갈색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["15"],"explanation":["블록 수 ÷ 열쇠고리 수 — 92 ÷ 6.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 6 → 몫 5.","92 ÷ 6 = 15 … 2 — 한 개에 15개씩, 2개 남아요."],"asset":null},{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 분홍색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["28"],"explanation":["블록 수 ÷ 열쇠고리 수 — 85 ÷ 3.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 25 ÷ 3 → 몫 8.","85 ÷ 3 = 28 … 1 — 한 개에 28개씩, 1개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#4','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'mc','auto','태민이의 블록은 주황색 252개, 초록색 90개, 검은색 687개, 흰색 341개예요. 열쇠고리 4개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],true,'{"seq":4,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"태민이의 블록은 주황색 252개, 초록색 90개, 검은색 687개, 흰색 341개예요. 열쇠고리 4개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"주황색","correct":true},{"t":"초록색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"},{"t":"흰색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 4로 나누어 나머지를 봐요.","주황색 252 ÷ 4 → 나머지 0, 초록색 90 ÷ 4 → 나머지 2, 검은색 687 ÷ 4 → 나머지 3, 흰색 341 ÷ 4 → 나머지 1.","나머지가 0인 주황색이 남는 블록이 없어요."],"variant_rule":{"alt":[{"stem":"태민이의 블록은 노란색 150개, 흰색 341개, 갈색 92개, 검은색 687개예요. 열쇠고리 6개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"노란색","correct":true},{"t":"흰색","mis":"M3-2-u2-X07"},{"t":"갈색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 6으로 나누어 나머지를 봐요.","노란색 150 ÷ 6 → 나머지 0, 흰색 341 ÷ 6 → 나머지 5, 갈색 92 ÷ 6 → 나머지 2, 검은색 687 ÷ 6 → 나머지 3.","나머지가 0인 노란색이 남는 블록이 없어요."],"asset":null},{"stem":"정후의 블록은 분홍색 85개, 검은색 314개, 흰색 112개, 회색 690개예요. 열쇠고리 3개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"회색","correct":true},{"t":"분홍색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"},{"t":"흰색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 3으로 나누어 나머지를 봐요.","회색 690 ÷ 3 → 나머지 0, 분홍색 85 ÷ 3 → 나머지 1, 검은색 314 ÷ 3 → 나머지 2, 흰색 112 ÷ 3 → 나머지 1.","나머지가 0인 회색이 남는 블록이 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#5','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이 파란색 블록 48개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":5,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 파란색 블록 48개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 9개씩 쓰고 3개가 남아요","correct":true},{"t":"한 개에 8개씩 쓰고 8개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 3개씩 쓰고 9개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 9개씩 쓰고 4개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["48 ÷ 5 — 몫은 한 개에 쓰는 수, 나머지는 남는 수.","5 × 9 = 45 — 몫 9, 48 − 45 = 3이 남아요.","48 ÷ 5 = 9 … 3."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 18개씩 쓰고 2개가 남아요","correct":true},{"t":"한 개에 17개씩 쓰고 7개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 2개씩 쓰고 18개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 18개씩 쓰고 3개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["92 ÷ 5 — 몫은 한 개에 쓰는 수, 나머지는 남는 수.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 42 ÷ 5 → 몫 8.","92 ÷ 5 = 18 … 2."],"asset":null},{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 4개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 21개씩 쓰고 1개가 남아요","correct":true},{"t":"한 개에 20개씩 쓰고 5개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 1개씩 쓰고 21개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 21개씩 쓰고 2개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["85 ÷ 4 — 몫은 한 개에 쓰는 수, 나머지는 남는 수.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 5 ÷ 4 → 몫 1.","85 ÷ 4 = 21 … 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#6','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X03','M3-2-u2-X04']::text[],true,'{"seq":6,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요?","options":[{"t":"137개","correct":true},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"111개","mis":"M3-2-u2-X03"},{"t":"731개","mis":"M3-2-u2-X04"}],"explanation":["블록 수 ÷ 열쇠고리 수 — 687 ÷ 5.","백의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 5 → 몫 3, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","687 ÷ 5 = 137 … 2 — 한 개에 137개씩, 2개 남아요."],"variant_rule":{"alt":[{"stem":"태민이 주황색 블록 252개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 주황색 블록을 몇 개씩 쓸 수 있나요?","options":[{"t":"50개","correct":true},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"500개","mis":"M3-2-u2-X12"},{"t":"51개","mis":"M3-2-u2-X15"}],"explanation":["블록 수 ÷ 열쇠고리 수 — 252 ÷ 5.","백의 자리 2는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 5 → 몫 5 · 일의 자리 2는 5로 나눌 수 없어 몫 0.","252 ÷ 5 = 50 … 2 — 한 개에 50개씩, 2개 남아요."],"asset":null},{"stem":"정후가 흰색 블록 112개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요?","options":[{"t":"37개","correct":true},{"t":"1개","mis":"M3-2-u2-X13"},{"t":"370개","mis":"M3-2-u2-X12"},{"t":"38개","mis":"M3-2-u2-X15"}],"explanation":["블록 수 ÷ 열쇠고리 수 — 112 ÷ 3.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 11로 보고 11 ÷ 3 → 몫 3, 2 남음 · 남은 2를 내려 22 ÷ 3 → 몫 7.","112 ÷ 3 = 37 … 1 — 한 개에 37개씩, 1개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#7','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["341 ÷ 4 = 85 … 1 — 한 개에 85개씩 쓰고 1개가 남아요.","한 개에 86개씩 쓰려면 4 × 86 = 344개가 필요해요.","344 − 341 = 3 — 적어도 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"태민이 초록색 블록 90개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 초록색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["90 ÷ 4 = 22 … 2 — 한 개에 22개씩 쓰고 2개가 남아요.","한 개에 23개씩 쓰려면 4 × 23 = 92개가 필요해요.","92 − 90 = 2 — 적어도 2개 더 있어야 해요."],"asset":null},{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 분홍색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["85 ÷ 3 = 28 … 1 — 한 개에 28개씩 쓰고 1개가 남아요.","한 개에 29개씩 쓰려면 3 × 29 = 87개가 필요해요.","87 − 85 = 2 — 적어도 2개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#8','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','한 번에 5명씩 탈 수 있는 보트로 봉사 활동 학생 67명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":8,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"한 번에 5명씩 탈 수 있는 보트로 봉사 활동 학생 67명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"14번","correct":true},{"t":"13번","mis":"M3-2-u2-X13"},{"t":"2번","mis":"M3-2-u2-X13"},{"t":"15번","mis":"M3-2-u2-X15"}],"explanation":["67 ÷ 5 = 13 … 2.","13번으로는 2명이 남아요 — 남은 것도 옮겨야 해요.","그래서 13 + 1 = 14 — 적어도 14번이에요."],"variant_rule":{"alt":[{"stem":"한 상자에 7권씩 담을 수 있어요. 도서관 책 90권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"13개","correct":true},{"t":"12개","mis":"M3-2-u2-X13"},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"14개","mis":"M3-2-u2-X15"}],"explanation":["90 ÷ 7 = 12 … 6.","12개로는 6권이 남아요 — 남은 것도 옮겨야 해요.","그래서 12 + 1 = 13 — 적어도 13개예요."],"asset":null},{"stem":"한 대에 8명씩 탈 수 있는 차로 학생 87명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"11대","correct":true},{"t":"10대","mis":"M3-2-u2-X13"},{"t":"7대","mis":"M3-2-u2-X13"},{"t":"12대","mis":"M3-2-u2-X15"}],"explanation":["87 ÷ 8 = 10 … 7.","10대로는 7명이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#9','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리를 4개 또는 5개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":9,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리를 4개 또는 5개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["687 ÷ 4 = 171 … 3.","687 ÷ 5 = 137 … 2.","남는 블록 3개와 2개 — 5개 만들 때 더 적어요."],"variant_rule":{"alt":[{"stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리를 4개 또는 6개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["341 ÷ 4 = 85 … 1.","341 ÷ 6 = 56 … 5.","남는 블록 1개와 5개 — 4개 만들 때 더 적어요."],"asset":null},{"stem":"정후가 흰색 블록 112개로 똑같은 열쇠고리를 3개 또는 5개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"3개","correct":true},{"t":"5개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["112 ÷ 3 = 37 … 1.","112 ÷ 5 = 22 … 2.","남는 블록 1개와 2개 — 3개 만들 때 더 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_basic#10','math',3,2,'u2','L10','g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',3,'mc','auto','종이꽃 120개를 7개씩 묶어 꽃다발을 만들려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":10,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"종이꽃 120개를 7개씩 묶어 꽃다발을 만들려고 해요. 어떻게 되나요?","options":[{"t":"17다발, 1개 남아요","correct":true},{"t":"16다발, 8개 남아요","mis":"M3-2-u2-X05"},{"t":"1다발, 17개 남아요","mis":"M3-2-u2-X06"},{"t":"17다발, 2개 남아요","mis":"M3-2-u2-X15"}],"explanation":["120 ÷ 7 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 1은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 12로 보고 12 ÷ 7 → 몫 1, 5 남음 · 남은 5를 내려 50 ÷ 7 → 몫 7.","120 ÷ 7 = 17 … 1 — 17다발, 1개 남아요."],"variant_rule":{"alt":[{"stem":"클립 554개를 7명에게 똑같이 나누어 주려고 해요. 어떻게 되나요?","options":[{"t":"79개씩, 1개 남아요","correct":true},{"t":"78개씩, 8개 남아요","mis":"M3-2-u2-X05"},{"t":"1개씩, 79개 남아요","mis":"M3-2-u2-X06"},{"t":"79개씩, 2개 남아요","mis":"M3-2-u2-X15"}],"explanation":["554 ÷ 7 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 5는 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 55로 보고 55 ÷ 7 → 몫 7, 6 남음 · 남은 6을 내려 64 ÷ 7 → 몫 9.","554 ÷ 7 = 79 … 1 — 79개씩, 1개 남아요."],"asset":null},{"stem":"봉사 활동 배지 325개를 8모둠에 똑같이 나누어 주려고 해요. 어떻게 되나요?","options":[{"t":"40개씩, 5개 남아요","correct":true},{"t":"39개씩, 13개 남아요","mis":"M3-2-u2-X05"},{"t":"5개씩, 40개 남아요","mis":"M3-2-u2-X06"},{"t":"40개씩, 6개 남아요","mis":"M3-2-u2-X15"}],"explanation":["325 ÷ 8 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 3은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 32로 보고 32 ÷ 8 → 몫 4 · 일의 자리 5는 8로 나눌 수 없어 몫 0.","325 ÷ 8 = 40 … 5 — 40개씩, 5개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#1','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',2,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리를 만들고 남는 흰색 블록은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리를 만들고 남는 흰색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남는 블록은 나머지예요 — 341 ÷ 6.","백의 자리 3은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 6 → 몫 5, 4 남음 · 남은 4를 내려 41 ÷ 6 → 몫 6.","341 ÷ 6 = 56 … 5 — 남는 블록 5개."],"variant_rule":{"alt":[{"stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리를 만들고 남는 노란색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남는 블록은 나머지예요 — 150 ÷ 4.","백의 자리 1은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 15로 보고 15 ÷ 4 → 몫 3, 3 남음 · 남은 3을 내려 30 ÷ 4 → 몫 7.","150 ÷ 4 = 37 … 2 — 남는 블록 2개."],"asset":null},{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리를 만들고 남는 분홍색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["남는 블록은 나머지예요 — 85 ÷ 6.","십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 25 ÷ 6 → 몫 4.","85 ÷ 6 = 14 … 1 — 남는 블록 1개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#2','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',2,'mc','auto','한 대에 4명씩 탈 수 있는 차로 학생 30명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":2,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"한 대에 4명씩 탈 수 있는 차로 학생 30명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"8대","correct":true},{"t":"7대","mis":"M3-2-u2-X13"},{"t":"2대","mis":"M3-2-u2-X13"},{"t":"9대","mis":"M3-2-u2-X15"}],"explanation":["30 ÷ 4 = 7 … 2.","7대로는 2명이 남아요 — 남은 것도 옮겨야 해요.","그래서 7 + 1 = 8 — 적어도 8대예요."],"variant_rule":{"alt":[{"stem":"한 번에 9명씩 탈 수 있는 보트로 봉사 활동 학생 55명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"7번","correct":true},{"t":"6번","mis":"M3-2-u2-X13"},{"t":"1번","mis":"M3-2-u2-X13"},{"t":"8번","mis":"M3-2-u2-X15"}],"explanation":["55 ÷ 9 = 6 … 1.","6번으로는 1명이 남아요 — 남은 것도 옮겨야 해요.","그래서 6 + 1 = 7 — 적어도 7번이에요."],"asset":null},{"stem":"한 상자에 5권씩 담을 수 있어요. 도서관 책 32권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"7개","correct":true},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"8개","mis":"M3-2-u2-X15"}],"explanation":["32 ÷ 5 = 6 … 2.","6개로는 2권이 남아요 — 남은 것도 옮겨야 해요.","그래서 6 + 1 = 7 — 적어도 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#3','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 검은색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C10","difficulty":3,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 검은색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["687 ÷ 5 = 137 … 2 — 한 개에 137개씩 쓰고 2개가 남아요.","한 개에 138개씩 쓰려면 5 × 138 = 690개가 필요해요.","690 − 687 = 3 — 적어도 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 6개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 갈색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["92 ÷ 6 = 15 … 2 — 한 개에 15개씩 쓰고 2개가 남아요.","한 개에 16개씩 쓰려면 6 × 16 = 96개가 필요해요.","96 − 92 = 4 — 적어도 4개 더 있어야 해요."],"asset":null},{"stem":"정후가 검은색 블록 314개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 검은색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["314 ÷ 4 = 78 … 2 — 한 개에 78개씩 쓰고 2개가 남아요.","한 개에 79개씩 쓰려면 4 × 79 = 316개가 필요해요.","316 − 314 = 2 — 적어도 2개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#4','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'mc','auto','한 번에 4명씩 탈 수 있는 보트로 봉사 활동 학생 258명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":4,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 번에 4명씩 탈 수 있는 보트로 봉사 활동 학생 258명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"65번","correct":true},{"t":"64번","mis":"M3-2-u2-X13"},{"t":"2번","mis":"M3-2-u2-X13"},{"t":"66번","mis":"M3-2-u2-X15"}],"explanation":["258 ÷ 4 = 64 … 2.","64번으로는 2명이 남아요 — 남은 것도 옮겨야 해요.","그래서 64 + 1 = 65 — 적어도 65번이에요."],"variant_rule":{"alt":[{"stem":"한 상자에 8권씩 담을 수 있어요. 도서관 책 286권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"36개","correct":true},{"t":"35개","mis":"M3-2-u2-X13"},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"37개","mis":"M3-2-u2-X15"}],"explanation":["286 ÷ 8 = 35 … 6.","35개로는 6권이 남아요 — 남은 것도 옮겨야 해요.","그래서 35 + 1 = 36 — 적어도 36개예요."],"asset":null},{"stem":"한 대에 9명씩 탈 수 있는 차로 학생 112명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"13대","correct":true},{"t":"12대","mis":"M3-2-u2-X13"},{"t":"4대","mis":"M3-2-u2-X13"},{"t":"14대","mis":"M3-2-u2-X15"}],"explanation":["112 ÷ 9 = 12 … 4.","12대로는 4명이 남아요 — 남은 것도 옮겨야 해요.","그래서 12 + 1 = 13 — 적어도 13대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#5','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'sa','auto','수 카드 5, 7, 8을 한 번씩 써서 만들 수 있는 가장 큰 두 자리 수를 가장 작은 한 자리 수로 나눈 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C10","difficulty":3,"kind":"sa","stem":"수 카드 5, 7, 8을 한 번씩 써서 만들 수 있는 가장 큰 두 자리 수를 가장 작은 한 자리 수로 나눈 몫은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["가장 큰 두 자리 수는 큰 수부터 — 87이에요.","가장 작은 한 자리 수는 5예요.","87 ÷ 5 = 17 … 2 — 몫은 17이에요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 9, 6을 한 번씩 써서 만들 수 있는 가장 큰 두 자리 수를 가장 작은 한 자리 수로 나눈 몫은 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["가장 큰 두 자리 수는 큰 수부터 — 96이에요.","가장 작은 한 자리 수는 3이에요.","96 ÷ 3 = 32 — 몫은 32예요."],"asset":null},{"stem":"수 카드 4, 8, 2를 한 번씩 써서 만들 수 있는 가장 큰 두 자리 수를 가장 작은 한 자리 수로 나눈 몫은 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["가장 큰 두 자리 수는 큰 수부터 — 84예요.","가장 작은 한 자리 수는 2예요.","84 ÷ 2 = 42 — 몫은 42예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#6','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'mc','auto','정후가 회색 블록 690개로 똑같은 열쇠고리를 4개 또는 7개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":6,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"정후가 회색 블록 690개로 똑같은 열쇠고리를 4개 또는 7개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"4개","correct":true},{"t":"7개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["690 ÷ 4 = 172 … 2.","690 ÷ 7 = 98 … 4.","남는 블록 2개와 4개 — 4개 만들 때 더 적어요."],"variant_rule":{"alt":[{"stem":"태민이 빨간색 블록 480개로 똑같은 열쇠고리를 7개 또는 9개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"9개","correct":true},{"t":"7개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["480 ÷ 7 = 68 … 4.","480 ÷ 9 = 53 … 3.","남는 블록 4개와 3개 — 9개 만들 때 더 적어요."],"asset":null},{"stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리를 4개 또는 7개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"4개","correct":true},{"t":"7개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["150 ÷ 4 = 37 … 2.","150 ÷ 7 = 21 … 3.","남는 블록 2개와 3개 — 4개 만들 때 더 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#7','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'mc','auto','금잔화 모종 745개를 화단 3곳에 똑같이 나누어 심으려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"금잔화 모종 745개를 화단 3곳에 똑같이 나누어 심으려고 해요. 어떻게 되나요?","options":[{"t":"248개씩, 1개 남아요","correct":true},{"t":"247개씩, 4개 남아요","mis":"M3-2-u2-X05"},{"t":"1개씩, 248개 남아요","mis":"M3-2-u2-X06"},{"t":"248개씩, 2개 남아요","mis":"M3-2-u2-X15"}],"explanation":["745 ÷ 3 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 14 ÷ 3 → 몫 4, 2 남음 · 남은 2를 내려 25 ÷ 3 → 몫 8.","745 ÷ 3 = 248 … 1 — 248개씩, 1개 남아요."],"variant_rule":{"alt":[{"stem":"손수건 588장을 5명이 똑같이 나누어 가지려고 해요. 어떻게 되나요?","options":[{"t":"117장씩, 3장 남아요","correct":true},{"t":"116장씩, 8장 남아요","mis":"M3-2-u2-X05"},{"t":"3장씩, 117장 남아요","mis":"M3-2-u2-X06"},{"t":"117장씩, 4장 남아요","mis":"M3-2-u2-X15"}],"explanation":["588 ÷ 5 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 38 ÷ 5 → 몫 7.","588 ÷ 5 = 117 … 3 — 117장씩, 3장 남아요."],"asset":null},{"stem":"약과 992개를 어르신 5분께 똑같이 나누어 드리려고 해요. 어떻게 되나요?","options":[{"t":"198개씩, 2개 남아요","correct":true},{"t":"197개씩, 7개 남아요","mis":"M3-2-u2-X05"},{"t":"2개씩, 198개 남아요","mis":"M3-2-u2-X06"},{"t":"198개씩, 3개 남아요","mis":"M3-2-u2-X15"}],"explanation":["992 ÷ 5 — 몫은 한 묶음(한 사람) 몫, 나머지는 남는 것.","백의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 49 ÷ 5 → 몫 9, 4 남음 · 남은 4를 내려 42 ÷ 5 → 몫 8.","992 ÷ 5 = 198 … 2 — 198개씩, 2개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#8','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'essay','teacher','태민이의 블록은 빨간색 480개, 검은색 687개, 흰색 341개예요. 똑같은 열쇠고리 4개를 만들 때 색깔마다 한 개에 쓸 수 있는 블록 수와 남는 블록 수를 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"태민이의 블록은 빨간색 480개, 검은색 687개, 흰색 341개예요. 똑같은 열쇠고리 4개를 만들 때 색깔마다 한 개에 쓸 수 있는 블록 수와 남는 블록 수를 구해 보세요.","answer_guide":{"answer":"예: 빨간색 480 ÷ 4 = 120이므로 한 개에 120개씩 쓰고 남는 것이 없다. 검은색 687 ÷ 4 = 171 … 3이므로 171개씩 쓰고 3개가 남는다. 흰색 341 ÷ 4 = 85 … 1이므로 85개씩 쓰고 1개가 남는다.","scoring_points":["480 ÷ 4 = 120을 구했는가","687 ÷ 4 = 171 … 3을 구했는가","341 ÷ 4 = 85 … 1을 구하고 몫·나머지의 뜻을 썼는가"]},"explanation":["480 ÷ 4 = 120.","687 ÷ 4 = 171 … 3.","341 ÷ 4 = 85 … 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#9','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'essay','teacher','봉사 활동 학생 67명이 한 번에 5명씩 탈 수 있는 보트로 모두 강을 건너려고 해요. 보트가 적어도 몇 번 건너야 하는지 구하고, 몫에 1을 더하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"봉사 활동 학생 67명이 한 번에 5명씩 탈 수 있는 보트로 모두 강을 건너려고 해요. 보트가 적어도 몇 번 건너야 하는지 구하고, 몫에 1을 더하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 67 ÷ 5 = 13 … 2이다. 13번 건너면 65명이 건너고 2명이 남는다. 남은 2명도 건너야 하므로 한 번 더 건너 적어도 14번 건너야 한다.","scoring_points":["67 ÷ 5 = 13 … 2를 구했는가","남은 2명도 건너야 한다고 설명했는가","14번이라고 답했는가"]},"explanation":["67 ÷ 5 = 13 … 2.","13번 → 2명 남음.","13 + 1 = 14번."],"asset":{"type":"ldiv","a":67,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_L10_challenge#10','math',3,2,'u2','L10','g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'mc','auto','곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":10,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"50개","correct":true},{"t":"48개","mis":"M3-2-u2-X09"},{"t":"46개","mis":"M3-2-u2-X14"},{"t":"64개","mis":"M3-2-u2-X08"}],"explanation":["8접시에 6개씩 — 8 × 6 = 48개.","남은 2개를 더해요.","48 + 2 = 50 — 모두 50개예요."],"variant_rule":{"alt":[{"stem":"약과를 7봉지에 13개씩 담았더니 5개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"96개","correct":true},{"t":"91개","mis":"M3-2-u2-X09"},{"t":"86개","mis":"M3-2-u2-X14"},{"t":"126개","mis":"M3-2-u2-X08"}],"explanation":["7봉지에 13개씩 — 7 × 13 = 91개.","남은 5개를 더해요.","91 + 5 = 96 — 모두 96개예요."],"asset":null},{"stem":"종이꽃을 9바구니에 11개씩 담았더니 4개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"103개","correct":true},{"t":"99개","mis":"M3-2-u2-X09"},{"t":"95개","mis":"M3-2-u2-X14"},{"t":"135개","mis":"M3-2-u2-X08"}],"explanation":["9바구니에 11개씩 — 9 × 11 = 99개.","남은 4개를 더해요.","99 + 4 = 103 — 모두 103개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#1','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C1',1,'sa','auto','45 ÷ 9는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"45 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나누는 수 9의 단에서 45를 찾아요.","9 × 5 = 45 — 그래서 45 ÷ 9 = 5예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"10 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 5의 단에서 10을 찾아요.","5 × 2 = 10 — 그래서 10 ÷ 5 = 2예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null},{"stem":"21 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 7의 단에서 21을 찾아요.","7 × 3 = 21 — 그래서 21 ÷ 7 = 3이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#2','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C1',1,'sa','auto','4 ÷ 2 = 2예요. 그러면 40 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"4 ÷ 2 = 2예요. 그러면 40 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["40은 4의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 40 ÷ 2 = 20이에요."],"variant_rule":{"alt":[{"stem":"6 ÷ 3 = 2예요. 그러면 60 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 60 ÷ 3 = 20이에요."],"asset":null},{"stem":"4 ÷ 4 = 1이에요. 그러면 40 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["40은 4의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 40 ÷ 4 = 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#3','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C2',1,'sa','auto','50 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"50 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 확인: 2 × 25 = 50이에요."],"variant_rule":{"alt":[{"stem":"70 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 확인: 5 × 14 = 70이에요."],"asset":null},{"stem":"80 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 확인: 5 × 16 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#4','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C3',1,'sa','auto','63 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"63 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 3 ÷ 3 → 몫 1.","63 ÷ 3 = 21 — 확인: 3 × 21 = 63이에요."],"variant_rule":{"alt":[{"stem":"99 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 9 ÷ 9 → 몫 1.","99 ÷ 9 = 11 — 확인: 9 × 11 = 99예요."],"asset":null},{"stem":"24 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 4 ÷ 2 → 몫 2.","24 ÷ 2 = 12 — 확인: 2 × 12 = 24예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#5','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C5',1,'sa','auto','84 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"84 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 24 ÷ 3 → 몫 8.","84 ÷ 3 = 28 — 확인: 3 × 28 = 84예요."],"variant_rule":{"alt":[{"stem":"65 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 5 → 몫 3.","65 ÷ 5 = 13 — 확인: 5 × 13 = 65예요."],"asset":null},{"stem":"57 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 3 → 몫 1, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","57 ÷ 3 = 19 — 확인: 3 × 19 = 57이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#6','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',1,'sa','auto','46 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"46 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 6의 단에서 46보다 크지 않은 가장 큰 곱을 찾아요.","6 × 7 = 42 — 몫 7, 46 − 42 = 4가 남아요.","46 ÷ 6 = 7 … 4 — 나머지 4는 나누는 수 6보다 작아요."],"variant_rule":{"alt":[{"stem":"31 ÷ 5의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 5의 단에서 31보다 크지 않은 가장 큰 곱을 찾아요.","5 × 6 = 30 — 몫 6, 31 − 30 = 1이 남아요.","31 ÷ 5 = 6 … 1 — 나머지 1은 나누는 수 5보다 작아요."],"asset":null},{"stem":"32 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 6의 단에서 32보다 크지 않은 가장 큰 곱을 찾아요.","6 × 5 = 30 — 몫 5, 32 − 30 = 2가 남아요.","32 ÷ 6 = 5 … 2 — 나머지 2는 나누는 수 6보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#7','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',1,'sa','auto','33 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"33 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 2 → 몫 6.","33 ÷ 2 = 16 … 1 — 확인: 2 × 16 + 1 = 33이에요."],"variant_rule":{"alt":[{"stem":"37 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 7 ÷ 3 → 몫 2.","37 ÷ 3 = 12 … 1 — 확인: 3 × 12 + 1 = 37이에요."],"asset":null},{"stem":"97 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 8 → 몫 2.","97 ÷ 8 = 12 … 1 — 확인: 8 × 12 + 1 = 97이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#8','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',1,'sa','auto','988 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"988 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["109"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 8은 9로 나눌 수 없어 몫 0, 8 남음 · 남은 8을 내려 88 ÷ 9 → 몫 9.","988 ÷ 9 = 109 … 7 — 확인: 9 × 109 + 7 = 988이에요."],"variant_rule":{"alt":[{"stem":"437 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["109"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 3은 4로 나눌 수 없어 몫 0, 3 남음 · 남은 3을 내려 37 ÷ 4 → 몫 9.","437 ÷ 4 = 109 … 1 — 확인: 4 × 109 + 1 = 437이에요."],"asset":null},{"stem":"210 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2 ÷ 2 → 몫 1 · 십의 자리 1은 2로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","210 ÷ 2 = 105 — 확인: 2 × 105 = 210이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#9','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',2,'sa','auto','639 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"639 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["79"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 63으로 보고 63 ÷ 8 → 몫 7, 7 남음 · 남은 7을 내려 79 ÷ 8 → 몫 9.","639 ÷ 8 = 79 … 7 — 확인: 8 × 79 + 7 = 639예요."],"variant_rule":{"alt":[{"stem":"117 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 11로 보고 11 ÷ 8 → 몫 1, 3 남음 · 남은 3을 내려 37 ÷ 8 → 몫 4.","117 ÷ 8 = 14 … 5 — 확인: 8 × 14 + 5 = 117이에요."],"asset":null},{"stem":"718 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["89"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 7은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 71로 보고 71 ÷ 8 → 몫 8, 7 남음 · 남은 7을 내려 78 ÷ 8 → 몫 9.","718 ÷ 8 = 89 … 6 — 확인: 8 × 89 + 6 = 718이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#10','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C4',2,'mc','auto','54 ÷ 3을 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":10,"concept":"M3-2-u2-C4","difficulty":2,"kind":"mc","stem":"54 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 54는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 18이에요."],"variant_rule":{"alt":[{"stem":"32 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 10 = 20, 2 × 20 = 40 — 32는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 16이에요."],"asset":null},{"stem":"75 ÷ 5를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","5 × 10 = 50, 5 × 20 = 100 — 75는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 15예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#11','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',2,'mc','auto','31 ÷ 5의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":11,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"31 ÷ 5의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 1","correct":true},{"t":"5 … 6","mis":"M3-2-u2-X05"},{"t":"1 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 5의 단에서 31보다 크지 않은 가장 큰 곱을 찾아요.","5 × 6 = 30 — 몫 6, 31 − 30 = 1이 남아요.","31 ÷ 5 = 6 … 1 — 나머지 1은 나누는 수 5보다 작아요."],"variant_rule":{"alt":[{"stem":"39 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 3","correct":true},{"t":"5 … 9","mis":"M3-2-u2-X05"},{"t":"3 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 6의 단에서 39보다 크지 않은 가장 큰 곱을 찾아요.","6 × 6 = 36 — 몫 6, 39 − 36 = 3이 남아요.","39 ÷ 6 = 6 … 3 — 나머지 3은 나누는 수 6보다 작아요."],"asset":null},{"stem":"37 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 … 2","correct":true},{"t":"4 … 9","mis":"M3-2-u2-X05"},{"t":"2 … 5","mis":"M3-2-u2-X06"},{"t":"5","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 7의 단에서 37보다 크지 않은 가장 큰 곱을 찾아요.","7 × 5 = 35 — 몫 5, 37 − 35 = 2가 남아요.","37 ÷ 7 = 5 … 2 — 나머지 2는 나누는 수 7보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#12','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',2,'sa','auto','79 ÷ 4 = 19 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"79 ÷ 4 = 19 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["76"],"explanation":["나누는 수 × 몫 = 4 × 19 = 76이에요.","여기에 나머지 3을 더하면 79예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["4 × 19","=",null],["□ + 3","=","79"]]},"variant_rule":{"alt":[{"stem":"54 ÷ 5 = 10 … 4를 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["54"],"explanation":["나누는 수 × 몫 = 5 × 10 = 50이에요.","여기에 나머지 4를 더하면 54예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 10","=","50"],["50 + 4","=",null]]}},{"stem":"88 ÷ 5 = 17 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["85"],"explanation":["나누는 수 × 몫 = 5 × 17 = 85예요.","여기에 나머지 3을 더하면 88이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 17","=",null],["□ + 3","=","88"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#13','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',2,'sa','auto','899 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"899 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 백의 자리 8 ÷ 4 → 몫 2 · 십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 19 ÷ 4 → 몫 4.","899 ÷ 4 = 224 … 3 — 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":899,"b":4,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"869 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 백의 자리 8 ÷ 4 → 몫 2 · 십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 4 → 몫 7.","869 ÷ 4 = 217 … 1 — 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":869,"b":4,"hide":[["q",1]]}},{"stem":"668 ÷ 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 26 ÷ 4 → 몫 6, 2 남음 · 남은 2를 내려 28 ÷ 4 → 몫 7.","668 ÷ 4 = 167 — 일의 자리 숫자는 7이에요."],"asset":{"type":"ldiv","a":668,"b":4,"hide":[["q",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#14','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',2,'mc','auto','105 ÷ 6의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":14,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"105 ÷ 6의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 1과 나누는 수 6과 견주어요.","1은 6보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","105 ÷ 6 = 17 … 3."],"variant_rule":{"alt":[{"stem":"296 ÷ 8의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 2와 나누는 수 8과 견주어요.","2는 8보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","296 ÷ 8 = 37."],"asset":null},{"stem":"288 ÷ 8의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 2와 나누는 수 8과 견주어요.","2는 8보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","288 ÷ 8 = 36."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#15','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',2,'sa','auto','태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["120"],"explanation":["블록 수 ÷ 열쇠고리 수 — 480 ÷ 4.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 0 → 몫 0.","480 ÷ 4 = 120 — 한 개에 120개씩."],"variant_rule":{"alt":[{"stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 노란색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["25"],"explanation":["블록 수 ÷ 열쇠고리 수 — 150 ÷ 6.","백의 자리 1은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 15로 보고 15 ÷ 6 → 몫 2, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","150 ÷ 6 = 25 — 한 개에 25개씩."],"asset":null},{"stem":"정후가 회색 블록 690개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 회색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["230"],"explanation":["블록 수 ÷ 열쇠고리 수 — 690 ÷ 3.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 0 → 몫 0.","690 ÷ 3 = 230 — 한 개에 230개씩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#16','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C5',2,'sa','auto','52 ÷ 4를 40과 12로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"52 ÷ 4를 40과 12로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["13"],"explanation":["52를 40과 12로 갈라요 — 둘 다 4로 나누어떨어져요.","40 ÷ 4 = 10, 12 ÷ 4 = 3이에요.","10 + 3 = 13 — 52 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["40 ÷ 4","=","10"],["12 ÷ 4","=","3"],["10 + 3","=",null]]},"variant_rule":{"alt":[{"stem":"72 ÷ 2를 60과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["72를 60과 12로 갈라요 — 둘 다 2로 나누어떨어져요.","60 ÷ 2 = 30, 12 ÷ 2 = 6이에요.","30 + 6 = 36 — 72 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 2","=","30"],["12 ÷ 2","=",null],["30 + □","=","36"]]}},{"stem":"72 ÷ 6을 60과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["72를 60과 12로 갈라요 — 둘 다 6으로 나누어떨어져요.","60 ÷ 6 = 10, 12 ÷ 6 = 2예요.","10 + 2 = 12 — 72 ÷ 6의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 6","=",null],["12 ÷ 6","=","2"],["□ + 2","=","12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#17','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C2',3,'error','auto','60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":17,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「60 ÷ 5 = 13이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"시우 — 「60 ÷ 5 = 12야」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「확인하면 5 × 12 = 60이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","60 ÷ 5 = 12.","지유가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"80 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「80 ÷ 5 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"서윤 — 「80 ÷ 5 = 16이야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「80 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16.","도윤이 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null},{"stem":"90 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「90 ÷ 2 = 46이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"하랑 — 「90 ÷ 2 = 45야」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 2 × 45 = 90이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","90 ÷ 2 = 45.","도윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#18','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',3,'ox','auto','819 ÷ 4 = 24 … 3이에요.',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":18,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"819 ÷ 4 = 24 … 3이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 8 ÷ 4 → 몫 2 · 십의 자리 1은 4로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 19 ÷ 4 → 몫 4.","바르게 계산하면 819 ÷ 4 = 204 … 3.","나눌 수 없으면 몫에 0 — 확인: 4 × 204 + 3 = 819예요."],"asset":{"type":"ldiv","a":819,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"612 ÷ 2 = 36이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 1은 2로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","바르게 계산하면 612 ÷ 2 = 306.","나눌 수 없으면 몫에 0 — 확인: 2 × 306 = 612예요."],"asset":{"type":"ldiv","a":612,"b":2,"upto":0}},{"stem":"808 ÷ 8 = 11이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 8 ÷ 8 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 8 ÷ 8 → 몫 1.","바르게 계산하면 808 ÷ 8 = 101.","나눌 수 없으면 몫에 0 — 확인: 8 × 101 = 808이에요."],"asset":{"type":"ldiv","a":808,"b":8,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#19','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',3,'sa','auto','어떤 수를 9로 나누었더니 몫이 10이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 9로 나누었더니 몫이 10이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["92"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","9 × 10 = 90, 90 + 2 = 92예요.","확인: 92 ÷ 9 = 10 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 8로 나누었더니 몫이 11이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["89"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","8 × 11 = 88, 88 + 1 = 89예요.","확인: 89 ÷ 8 = 11 … 1."],"asset":null},{"stem":"어떤 수를 9로 나누었더니 몫이 10이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","9 × 10 = 90, 90 + 4 = 94예요.","확인: 94 ÷ 9 = 10 … 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#20','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',3,'ox','auto','204 ÷ 9 = 21 … 15예요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"204 ÷ 9 = 21 … 15예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 2는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 20으로 보고 20 ÷ 9 → 몫 2, 2 남음 · 남은 2를 내려 24 ÷ 9 → 몫 2.","바르게 계산하면 204 ÷ 9 = 22 … 6.","나머지 < 나누는 수 — 확인: 9 × 22 + 6 = 204예요."],"asset":{"type":"ldiv","a":204,"b":9,"upto":0},"variant_rule":{"alt":[{"stem":"113 ÷ 6 = 17 … 11이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 1은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 11로 보고 11 ÷ 6 → 몫 1, 5 남음 · 남은 5를 내려 53 ÷ 6 → 몫 8.","바르게 계산하면 113 ÷ 6 = 18 … 5.","나머지 < 나누는 수 — 확인: 6 × 18 + 5 = 113이에요."],"asset":{"type":"ldiv","a":113,"b":6,"upto":0}},{"stem":"305 ÷ 7 = 42 … 11이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 3은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 30으로 보고 30 ÷ 7 → 몫 4, 2 남음 · 남은 2를 내려 25 ÷ 7 → 몫 3.","바르게 계산하면 305 ÷ 7 = 43 … 4.","나머지 < 나누는 수 — 확인: 7 × 43 + 4 = 305예요."],"asset":{"type":"ldiv","a":305,"b":7,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#21','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',3,'mc','auto','한 상자에 7권씩 담을 수 있어요. 도서관 책 99권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":21,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 상자에 7권씩 담을 수 있어요. 도서관 책 99권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"15개","correct":true},{"t":"14개","mis":"M3-2-u2-X13"},{"t":"1개","mis":"M3-2-u2-X13"},{"t":"16개","mis":"M3-2-u2-X15"}],"explanation":["99 ÷ 7 = 14 … 1.","14개로는 1권이 남아요 — 남은 것도 옮겨야 해요.","그래서 14 + 1 = 15 — 적어도 15개예요."],"variant_rule":{"alt":[{"stem":"한 대에 7명씩 탈 수 있는 차로 학생 88명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"13대","correct":true},{"t":"12대","mis":"M3-2-u2-X13"},{"t":"4대","mis":"M3-2-u2-X13"},{"t":"14대","mis":"M3-2-u2-X15"}],"explanation":["88 ÷ 7 = 12 … 4.","12대로는 4명이 남아요 — 남은 것도 옮겨야 해요.","그래서 12 + 1 = 13 — 적어도 13대예요."],"asset":null},{"stem":"한 번에 2명씩 탈 수 있는 보트로 봉사 활동 학생 87명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"44번","correct":true},{"t":"43번","mis":"M3-2-u2-X13"},{"t":"1번","mis":"M3-2-u2-X13"},{"t":"45번","mis":"M3-2-u2-X15"}],"explanation":["87 ÷ 2 = 43 … 1.","43번으로는 1명이 남아요 — 남은 것도 옮겨야 해요.","그래서 43 + 1 = 44 — 적어도 44번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#22','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',3,'mc','auto','14 ÷ 5, 22 ÷ 4, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"14 ÷ 5, 22 ÷ 4, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"14 ÷ 5","correct":true},{"t":"22 ÷ 4","mis":"M3-2-u2-X15"},{"t":"64 ÷ 9","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","14 ÷ 5 = 2 … 4, 22 ÷ 4 = 5 … 2, 64 ÷ 9 = 7 … 1.","나머지가 가장 큰 것은 14 ÷ 5 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"19 ÷ 4, 29 ÷ 6, 52 ÷ 8 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"29 ÷ 6","correct":true},{"t":"19 ÷ 4","mis":"M3-2-u2-X15"},{"t":"52 ÷ 8","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","19 ÷ 4 = 4 … 3, 29 ÷ 6 = 4 … 5, 52 ÷ 8 = 6 … 4.","나머지가 가장 큰 것은 29 ÷ 6 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null},{"stem":"23 ÷ 6, 30 ÷ 4, 50 ÷ 7 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"23 ÷ 6","correct":true},{"t":"30 ÷ 4","mis":"M3-2-u2-X17"},{"t":"50 ÷ 7","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","23 ÷ 6 = 3 … 5, 30 ÷ 4 = 7 … 2, 50 ÷ 7 = 7 … 1.","나머지가 가장 큰 것은 23 ÷ 6 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#23','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',4,'mc','auto','곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":23,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"곶감을 8접시에 6개씩 담았더니 2개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"50개","correct":true},{"t":"48개","mis":"M3-2-u2-X09"},{"t":"46개","mis":"M3-2-u2-X14"},{"t":"64개","mis":"M3-2-u2-X08"}],"explanation":["8접시에 6개씩 — 8 × 6 = 48개.","남은 2개를 더해요.","48 + 2 = 50 — 모두 50개예요."],"variant_rule":{"alt":[{"stem":"약과를 7봉지에 9개씩 담았더니 3개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"66개","correct":true},{"t":"63개","mis":"M3-2-u2-X09"},{"t":"60개","mis":"M3-2-u2-X14"},{"t":"84개","mis":"M3-2-u2-X08"}],"explanation":["7봉지에 9개씩 — 7 × 9 = 63개.","남은 3개를 더해요.","63 + 3 = 66 — 모두 66개예요."],"asset":null},{"stem":"종이꽃을 6바구니에 12개씩 담았더니 4개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"76개","correct":true},{"t":"72개","mis":"M3-2-u2-X09"},{"t":"68개","mis":"M3-2-u2-X14"},{"t":"96개","mis":"M3-2-u2-X08"}],"explanation":["6바구니에 12개씩 — 6 × 12 = 72개.","남은 4개를 더해요.","72 + 4 = 76 — 모두 76개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#24','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',4,'sa','auto','어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1032가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u2-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1032가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["어떤 수 × 4 = 1032 → 어떤 수는 1032 ÷ 4 = 258이에요.","바르게 계산하면 258 ÷ 4.","258 ÷ 4 = 64 … 2 — 몫은 64예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 1364가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["어떤 수 × 4 = 1364 → 어떤 수는 1364 ÷ 4 = 341이에요.","바르게 계산하면 341 ÷ 4.","341 ÷ 4 = 85 … 1 — 몫은 85예요."],"asset":null},{"stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 591이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["어떤 수 × 3 = 591 → 어떤 수는 591 ÷ 3 = 197이에요.","바르게 계산하면 197 ÷ 3.","197 ÷ 3 = 65 … 2 — 몫은 65예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_a#25','math',3,2,'u2','','g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',4,'essay','teacher','친구가 615 ÷ 6을 계산하고 몫을 120, 나머지를 15라고 썼어요. 잘못된 점을 찾고 바르게 계산해 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"친구가 615 ÷ 6을 계산하고 몫을 120, 나머지를 15라고 썼어요. 잘못된 점을 찾고 바르게 계산해 확인해 보세요.","answer_guide":{"answer":"예: 십의 자리 1은 6으로 나눌 수 없으니 몫의 십의 자리에 0을 써야 하는데 0을 끝에 붙였고, 나머지 15도 6보다 크다. 6 ÷ 6 = 1, 1 → 몫 0, 남은 1을 내려 15 ÷ 6 = 2 … 3이므로 615 ÷ 6 = 102 … 3이다. 확인: 6 × 102 + 3 = 615.","scoring_points":["몫의 0 자리가 어긋났다고 찾았는가","102 … 3을 구했는가","6 × 102 + 3 = 615로 확인했는가"]},"explanation":["십의 자리 1 → 몫 0.","15 ÷ 6 = 2 … 3.","615 ÷ 6 = 102 … 3."],"asset":{"type":"ldiv","a":615,"b":6,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#1','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C1',1,'sa','auto','32 ÷ 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"32 ÷ 8은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 8의 단에서 32를 찾아요.","8 × 4 = 32 — 그래서 32 ÷ 8 = 4예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"72 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["나누는 수 9의 단에서 72를 찾아요.","9 × 8 = 72 — 그래서 72 ÷ 9 = 8이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null},{"stem":"10 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 5의 단에서 10을 찾아요.","5 × 2 = 10 — 그래서 10 ÷ 5 = 2예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#2','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C1',1,'sa','auto','6 ÷ 6 = 1이에요. 그러면 60 ÷ 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"6 ÷ 6 = 1이에요. 그러면 60 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 60 ÷ 6 = 10이에요."],"variant_rule":{"alt":[{"stem":"8 ÷ 2 = 4예요. 그러면 80 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["80은 8의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","4의 10배 — 80 ÷ 2 = 40이에요."],"asset":null},{"stem":"9 ÷ 9 = 1이에요. 그러면 90 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["90은 9의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 90 ÷ 9 = 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#3','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C2',1,'sa','auto','90 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"90 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","90 ÷ 2 = 45 — 확인: 2 × 45 = 90이에요."],"variant_rule":{"alt":[{"stem":"70 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 확인: 5 × 14 = 70이에요."],"asset":null},{"stem":"80 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 확인: 5 × 16 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#4','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C3',1,'sa','auto','82 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"82 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 2 ÷ 2 → 몫 1.","82 ÷ 2 = 41 — 확인: 2 × 41 = 82예요."],"variant_rule":{"alt":[{"stem":"63 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 3 ÷ 3 → 몫 1.","63 ÷ 3 = 21 — 확인: 3 × 21 = 63이에요."],"asset":null},{"stem":"66 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 6 ÷ 3 → 몫 2.","66 ÷ 3 = 22 — 확인: 3 × 22 = 66이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#5','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C5',1,'sa','auto','96 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"96 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 16 ÷ 4 → 몫 4.","96 ÷ 4 = 24 — 확인: 4 × 24 = 96이에요."],"variant_rule":{"alt":[{"stem":"45 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","45 ÷ 3 = 15 — 확인: 3 × 15 = 45예요."],"asset":null},{"stem":"72 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 4 → 몫 8.","72 ÷ 4 = 18 — 확인: 4 × 18 = 72예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#6','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',1,'sa','auto','22 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"22 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 4의 단에서 22보다 크지 않은 가장 큰 곱을 찾아요.","4 × 5 = 20 — 몫 5, 22 − 20 = 2가 남아요.","22 ÷ 4 = 5 … 2 — 나머지 2는 나누는 수 4보다 작아요."],"variant_rule":{"alt":[{"stem":"31 ÷ 5의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 5의 단에서 31보다 크지 않은 가장 큰 곱을 찾아요.","5 × 6 = 30 — 몫 6, 31 − 30 = 1이 남아요.","31 ÷ 5 = 6 … 1 — 나머지 1은 나누는 수 5보다 작아요."],"asset":null},{"stem":"33 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 6의 단에서 33보다 크지 않은 가장 큰 곱을 찾아요.","6 × 5 = 30 — 몫 5, 33 − 30 = 3이 남아요.","33 ÷ 6 = 5 … 3 — 나머지 3은 나누는 수 6보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#7','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',1,'sa','auto','76 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"76 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 7 → 몫 1 · 일의 자리 6은 7로 나눌 수 없어 몫 0.","76 ÷ 7 = 10 … 6 — 확인: 7 × 10 + 6 = 76이에요."],"variant_rule":{"alt":[{"stem":"75 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 6 → 몫 2.","75 ÷ 6 = 12 … 3 — 확인: 6 × 12 + 3 = 75예요."],"asset":null},{"stem":"92 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 6 → 몫 5.","92 ÷ 6 = 15 … 2 — 확인: 6 × 15 + 2 = 92예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#8','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',1,'sa','auto','318 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"318 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["106"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 18 ÷ 3 → 몫 6.","318 ÷ 3 = 106 — 확인: 3 × 106 = 318이에요."],"variant_rule":{"alt":[{"stem":"522 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["104"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 2는 5로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 22 ÷ 5 → 몫 4.","522 ÷ 5 = 104 … 2 — 확인: 5 × 104 + 2 = 522예요."],"asset":null},{"stem":"321 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["107"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 2는 3으로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 21 ÷ 3 → 몫 7.","321 ÷ 3 = 107 — 확인: 3 × 107 = 321이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#9','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',2,'sa','auto','552 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"552 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 5는 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 55로 보고 55 ÷ 8 → 몫 6, 7 남음 · 남은 7을 내려 72 ÷ 8 → 몫 9.","552 ÷ 8 = 69 — 확인: 8 × 69 = 552예요."],"variant_rule":{"alt":[{"stem":"145 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 2보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 14로 보고 14 ÷ 2 → 몫 7 · 일의 자리 5 ÷ 2 → 몫 2.","145 ÷ 2 = 72 … 1 — 확인: 2 × 72 + 1 = 145예요."],"asset":null},{"stem":"145 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 14로 보고 14 ÷ 6 → 몫 2, 2 남음 · 남은 2를 내려 25 ÷ 6 → 몫 4.","145 ÷ 6 = 24 … 1 — 확인: 6 × 24 + 1 = 145예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#10','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C4',2,'mc','auto','42 ÷ 3을 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":10,"concept":"M3-2-u2-C4","difficulty":2,"kind":"mc","stem":"42 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 42는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 14예요."],"variant_rule":{"alt":[{"stem":"57 ÷ 3을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","3 × 10 = 30, 3 × 20 = 60 — 57은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 19예요."],"asset":null},{"stem":"84 ÷ 7을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","7 × 10 = 70, 7 × 20 = 140 — 84는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 12예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#11','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',2,'mc','auto','41 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":11,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"41 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 5","correct":true},{"t":"5 … 11","mis":"M3-2-u2-X05"},{"t":"5 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 6의 단에서 41보다 크지 않은 가장 큰 곱을 찾아요.","6 × 6 = 36 — 몫 6, 41 − 36 = 5가 남아요.","41 ÷ 6 = 6 … 5 — 나머지 5는 나누는 수 6보다 작아요."],"variant_rule":{"alt":[{"stem":"50 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 … 1","correct":true},{"t":"6 … 8","mis":"M3-2-u2-X05"},{"t":"1 … 7","mis":"M3-2-u2-X06"},{"t":"7","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 7의 단에서 50보다 크지 않은 가장 큰 곱을 찾아요.","7 × 7 = 49 — 몫 7, 50 − 49 = 1이 남아요.","50 ÷ 7 = 7 … 1 — 나머지 1은 나누는 수 7보다 작아요."],"asset":null},{"stem":"39 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 … 7","correct":true},{"t":"3 … 15","mis":"M3-2-u2-X05"},{"t":"7 … 4","mis":"M3-2-u2-X06"},{"t":"4","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 8의 단에서 39보다 크지 않은 가장 큰 곱을 찾아요.","8 × 4 = 32 — 몫 4, 39 − 32 = 7이 남아요.","39 ÷ 8 = 4 … 7 — 나머지 7은 나누는 수 8보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#12','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',2,'sa','auto','51 ÷ 5 = 10 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"51 ÷ 5 = 10 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["51"],"explanation":["나누는 수 × 몫 = 5 × 10 = 50이에요.","여기에 나머지 1을 더하면 51이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 10","=","50"],["50 + 1","=",null]]},"variant_rule":{"alt":[{"stem":"75 ÷ 6 = 12 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["72"],"explanation":["나누는 수 × 몫 = 6 × 12 = 72예요.","여기에 나머지 3을 더하면 75예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["6 × 12","=",null],["□ + 3","=","75"]]}},{"stem":"91 ÷ 3 = 30 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["91"],"explanation":["나누는 수 × 몫 = 3 × 30 = 90이에요.","여기에 나머지 1을 더하면 91이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 30","=","90"],["90 + 1","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#13','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',2,'sa','auto','232 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"232 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 2 ÷ 2 → 몫 1 · 십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","232 ÷ 2 = 116 — 백의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":232,"b":2,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"734 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 6 → 몫 2, 1 남음 · 남은 1을 내려 14 ÷ 6 → 몫 2.","734 ÷ 6 = 122 … 2 — 백의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":734,"b":6,"hide":[["q",0]]}},{"stem":"766 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 6 → 몫 2, 4 남음 · 남은 4를 내려 46 ÷ 6 → 몫 7.","766 ÷ 6 = 127 … 4 — 백의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":766,"b":6,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#14','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',2,'mc','auto','214 ÷ 9의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":14,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"214 ÷ 9의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 2와 나누는 수 9와 견주어요.","2는 9보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","214 ÷ 9 = 23 … 7."],"variant_rule":{"alt":[{"stem":"855 ÷ 9의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 8과 나누는 수 9와 견주어요.","8은 9보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","855 ÷ 9 = 95."],"asset":null},{"stem":"458 ÷ 7의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 4와 나누는 수 7과 견주어요.","4는 7보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","458 ÷ 7 = 65 … 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#15','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',2,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["85"],"explanation":["블록 수 ÷ 열쇠고리 수 — 341 ÷ 4.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 4 → 몫 8, 2 남음 · 남은 2를 내려 21 ÷ 4 → 몫 5.","341 ÷ 4 = 85 … 1 — 한 개에 85개씩, 1개 남아요."],"variant_rule":{"alt":[{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 분홍색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["28"],"explanation":["블록 수 ÷ 열쇠고리 수 — 85 ÷ 3.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 25 ÷ 3 → 몫 8.","85 ÷ 3 = 28 … 1 — 한 개에 28개씩, 1개 남아요."],"asset":null},{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 갈색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["15"],"explanation":["블록 수 ÷ 열쇠고리 수 — 92 ÷ 6.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 6 → 몫 5.","92 ÷ 6 = 15 … 2 — 한 개에 15개씩, 2개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#16','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C5',2,'sa','auto','75 ÷ 5를 50과 25로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"75 ÷ 5를 50과 25로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["75를 50과 25로 갈라요 — 둘 다 5로 나누어떨어져요.","50 ÷ 5 = 10, 25 ÷ 5 = 5예요.","10 + 5 = 15 — 75 ÷ 5의 몫이에요."],"asset":{"type":"expr_grid","rows":[["50 ÷ 5","=","10"],["25 ÷ 5","=","5"],["10 + 5","=",null]]},"variant_rule":{"alt":[{"stem":"92 ÷ 4를 80과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["92를 80과 12로 갈라요 — 둘 다 4로 나누어떨어져요.","80 ÷ 4 = 20, 12 ÷ 4 = 3이에요.","20 + 3 = 23 — 92 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["80 ÷ 4","=","20"],["12 ÷ 4","=",null],["20 + □","=","23"]]}},{"stem":"96 ÷ 6을 60과 36으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["96을 60과 36으로 갈라요 — 둘 다 6으로 나누어떨어져요.","60 ÷ 6 = 10, 36 ÷ 6 = 6이에요.","10 + 6 = 16 — 96 ÷ 6의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 6","=",null],["36 ÷ 6","=","6"],["□ + 6","=","16"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#17','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C2',3,'error','auto','70 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":17,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"70 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「70 ÷ 5 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"은우 — 「70 ÷ 5 = 14야」","mis":"M3-2-u2-X17"},{"t":"하랑 — 「70 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14.","지유가 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"90 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「90 ÷ 5 = 19야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"서윤 — 「90 ÷ 5 = 18이야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「확인하면 5 × 18 = 90이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","90 ÷ 5 = 18.","하린이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"90 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「90 ÷ 6 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지유 — 「90 ÷ 6 = 15야」","mis":"M3-2-u2-X17"},{"t":"하린 — 「90 ÷ 6은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15.","은우가 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#18','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',3,'ox','auto','933 ÷ 9 = 13 … 6이에요.',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":18,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"933 ÷ 9 = 13 … 6이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 3은 9로 나눌 수 없어 몫 0, 3 남음 · 남은 3을 내려 33 ÷ 9 → 몫 3.","바르게 계산하면 933 ÷ 9 = 103 … 6.","나눌 수 없으면 몫에 0 — 확인: 9 × 103 + 6 = 933이에요."],"asset":{"type":"ldiv","a":933,"b":9,"upto":0},"variant_rule":{"alt":[{"stem":"603 ÷ 2 = 31 … 1이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 3 ÷ 2 → 몫 1.","바르게 계산하면 603 ÷ 2 = 301 … 1.","나눌 수 없으면 몫에 0 — 확인: 2 × 301 + 1 = 603이에요."],"asset":{"type":"ldiv","a":603,"b":2,"upto":0}},{"stem":"952 ÷ 9 = 15 … 7이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 5는 9로 나눌 수 없어 몫 0, 5 남음 · 남은 5를 내려 52 ÷ 9 → 몫 5.","바르게 계산하면 952 ÷ 9 = 105 … 7.","나눌 수 없으면 몫에 0 — 확인: 9 × 105 + 7 = 952예요."],"asset":{"type":"ldiv","a":952,"b":9,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#19','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',3,'sa','auto','어떤 수를 8로 나누었더니 몫이 12이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 8로 나누었더니 몫이 12이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","8 × 12 = 96, 96 + 2 = 98이에요.","확인: 98 ÷ 8 = 12 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 5로 나누었더니 몫이 17이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","5 × 17 = 85, 85 + 1 = 86이에요.","확인: 86 ÷ 5 = 17 … 1."],"asset":null},{"stem":"어떤 수를 8로 나누었더니 몫이 11이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","8 × 11 = 88, 88 + 6 = 94예요.","확인: 94 ÷ 8 = 11 … 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#20','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',3,'ox','auto','693 ÷ 8 = 85 … 13이에요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"693 ÷ 8 = 85 … 13이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 6은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 69로 보고 69 ÷ 8 → 몫 8, 5 남음 · 남은 5를 내려 53 ÷ 8 → 몫 6.","바르게 계산하면 693 ÷ 8 = 86 … 5.","나머지 < 나누는 수 — 확인: 8 × 86 + 5 = 693이에요."],"asset":{"type":"ldiv","a":693,"b":8,"upto":0},"variant_rule":{"alt":[{"stem":"199 ÷ 8 = 23 … 15예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 1은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 19로 보고 19 ÷ 8 → 몫 2, 3 남음 · 남은 3을 내려 39 ÷ 8 → 몫 4.","바르게 계산하면 199 ÷ 8 = 24 … 7.","나머지 < 나누는 수 — 확인: 8 × 24 + 7 = 199예요."],"asset":{"type":"ldiv","a":199,"b":8,"upto":0}},{"stem":"562 ÷ 8 = 69 … 10이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 5는 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 56으로 보고 56 ÷ 8 → 몫 7 · 일의 자리 2는 8로 나눌 수 없어 몫 0.","바르게 계산하면 562 ÷ 8 = 70 … 2.","나머지 < 나누는 수 — 확인: 8 × 70 + 2 = 562예요."],"asset":{"type":"ldiv","a":562,"b":8,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#21','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',3,'mc','auto','한 대에 6명씩 탈 수 있는 차로 학생 81명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":21,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 대에 6명씩 탈 수 있는 차로 학생 81명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"14대","correct":true},{"t":"13대","mis":"M3-2-u2-X13"},{"t":"3대","mis":"M3-2-u2-X13"},{"t":"15대","mis":"M3-2-u2-X15"}],"explanation":["81 ÷ 6 = 13 … 3.","13대로는 3명이 남아요 — 남은 것도 옮겨야 해요.","그래서 13 + 1 = 14 — 적어도 14대예요."],"variant_rule":{"alt":[{"stem":"한 번에 9명씩 탈 수 있는 보트로 봉사 활동 학생 98명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"11번","correct":true},{"t":"10번","mis":"M3-2-u2-X13"},{"t":"8번","mis":"M3-2-u2-X13"},{"t":"12번","mis":"M3-2-u2-X15"}],"explanation":["98 ÷ 9 = 10 … 8.","10번으로는 8명이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11번이에요."],"asset":null},{"stem":"한 상자에 8권씩 담을 수 있어요. 도서관 책 86권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"11개","correct":true},{"t":"10개","mis":"M3-2-u2-X13"},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"12개","mis":"M3-2-u2-X15"}],"explanation":["86 ÷ 8 = 10 … 6.","10개로는 6권이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#22','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',3,'mc','auto','27 ÷ 5, 33 ÷ 8, 46 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X15']::text[],true,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"27 ÷ 5, 33 ÷ 8, 46 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"27 ÷ 5","correct":true},{"t":"33 ÷ 8","mis":"M3-2-u2-X15"},{"t":"46 ÷ 9","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","27 ÷ 5 = 5 … 2, 33 ÷ 8 = 4 … 1, 46 ÷ 9 = 5 … 1.","나머지가 가장 큰 것은 27 ÷ 5 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"17 ÷ 3, 39 ÷ 7, 58 ÷ 8 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"39 ÷ 7","correct":true},{"t":"17 ÷ 3","mis":"M3-2-u2-X15"},{"t":"58 ÷ 8","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","17 ÷ 3 = 5 … 2, 39 ÷ 7 = 5 … 4, 58 ÷ 8 = 7 … 2.","나머지가 가장 큰 것은 39 ÷ 7 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null},{"stem":"26 ÷ 7, 45 ÷ 6, 31 ÷ 5 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"26 ÷ 7","correct":true},{"t":"45 ÷ 6","mis":"M3-2-u2-X17"},{"t":"31 ÷ 5","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","26 ÷ 7 = 3 … 5, 45 ÷ 6 = 7 … 3, 31 ÷ 5 = 6 … 1.","나머지가 가장 큰 것은 26 ÷ 7 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#23','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',4,'mc','auto','곶감을 9접시에 7개씩 담았더니 5개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":23,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"곶감을 9접시에 7개씩 담았더니 5개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"68개","correct":true},{"t":"63개","mis":"M3-2-u2-X09"},{"t":"58개","mis":"M3-2-u2-X14"},{"t":"108개","mis":"M3-2-u2-X08"}],"explanation":["9접시에 7개씩 — 9 × 7 = 63개.","남은 5개를 더해요.","63 + 5 = 68 — 모두 68개예요."],"variant_rule":{"alt":[{"stem":"약과를 6봉지에 14개씩 담았더니 3개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"87개","correct":true},{"t":"84개","mis":"M3-2-u2-X09"},{"t":"81개","mis":"M3-2-u2-X14"},{"t":"102개","mis":"M3-2-u2-X08"}],"explanation":["6봉지에 14개씩 — 6 × 14 = 84개.","남은 3개를 더해요.","84 + 3 = 87 — 모두 87개예요."],"asset":null},{"stem":"종이꽃을 8바구니에 11개씩 담았더니 6개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"94개","correct":true},{"t":"88개","mis":"M3-2-u2-X09"},{"t":"82개","mis":"M3-2-u2-X14"},{"t":"136개","mis":"M3-2-u2-X08"}],"explanation":["8바구니에 11개씩 — 8 × 11 = 88개.","남은 6개를 더해요.","88 + 6 = 94 — 모두 94개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#24','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',4,'sa','auto','어떤 수를 9로 나누어야 하는데 잘못하여 9를 곱했더니 3942가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u2-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 9로 나누어야 하는데 잘못하여 9를 곱했더니 3942가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["어떤 수 × 9 = 3942 → 어떤 수는 3942 ÷ 9 = 438이에요.","바르게 계산하면 438 ÷ 9.","438 ÷ 9 = 48 … 6 — 몫은 48이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 588이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["어떤 수 × 3 = 588 → 어떤 수는 588 ÷ 3 = 196이에요.","바르게 계산하면 196 ÷ 3.","196 ÷ 3 = 65 … 1 — 몫은 65예요."],"asset":null},{"stem":"어떤 수를 6으로 나누어야 하는데 잘못하여 6을 곱했더니 3162가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["어떤 수 × 6 = 3162 → 어떤 수는 3162 ÷ 6 = 527이에요.","바르게 계산하면 527 ÷ 6.","527 ÷ 6 = 87 … 5 — 몫은 87이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_b#25','math',3,2,'u2','','g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',4,'essay','teacher','어떤 수를 6으로 나누었더니 몫이 14이고 나머지가 5였어요. 어떤 수를 구하고, 구한 수를 6으로 나누어 맞는지 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"어떤 수를 6으로 나누었더니 몫이 14이고 나머지가 5였어요. 어떤 수를 구하고, 구한 수를 6으로 나누어 맞는지 확인해 보세요.","answer_guide":{"answer":"예: 어떤 수 = 6 × 14 + 5 = 84 + 5 = 89이다. 89 ÷ 6은 8 ÷ 6 = 1 … 2, 29 ÷ 6 = 4 … 5이므로 14 … 5가 되어 맞다.","scoring_points":["6 × 14 + 5로 식을 세웠는가","89를 구했는가","89 ÷ 6 = 14 … 5로 확인했는가"]},"explanation":["6 × 14 = 84.","84 + 5 = 89.","89 ÷ 6 = 14 … 5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#1','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C1',1,'sa','auto','56 ÷ 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"56 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["나누는 수 7의 단에서 56을 찾아요.","7 × 8 = 56 — 그래서 56 ÷ 7 = 8이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"24 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 6의 단에서 24를 찾아요.","6 × 4 = 24 — 그래서 24 ÷ 6 = 4예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null},{"stem":"54 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 9의 단에서 54를 찾아요.","9 × 6 = 54 — 그래서 54 ÷ 9 = 6이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#2','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C1',1,'sa','auto','5 ÷ 5 = 1이에요. 그러면 50 ÷ 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"5 ÷ 5 = 1이에요. 그러면 50 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["50은 5의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 50 ÷ 5 = 10이에요."],"variant_rule":{"alt":[{"stem":"6 ÷ 6 = 1이에요. 그러면 60 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 60 ÷ 6 = 10이에요."],"asset":null},{"stem":"9 ÷ 3 = 3이에요. 그러면 90 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["90은 9의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","3의 10배 — 90 ÷ 3 = 30이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#3','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C2',1,'sa','auto','90 ÷ 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"90 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 확인: 6 × 15 = 90이에요."],"variant_rule":{"alt":[{"stem":"70 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 확인: 5 × 14 = 70이에요."],"asset":null},{"stem":"90 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","90 ÷ 2 = 45 — 확인: 2 × 45 = 90이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#4','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C3',1,'sa','auto','86 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"86 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 6 ÷ 2 → 몫 3.","86 ÷ 2 = 43 — 확인: 2 × 43 = 86이에요."],"variant_rule":{"alt":[{"stem":"84 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 2 → 몫 4 · 일의 자리 4 ÷ 2 → 몫 2.","84 ÷ 2 = 42 — 확인: 2 × 42 = 84예요."],"asset":null},{"stem":"69 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 9 ÷ 3 → 몫 3.","69 ÷ 3 = 23 — 확인: 3 × 23 = 69예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#5','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C5',1,'sa','auto','56 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"56 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 4 → 몫 4.","56 ÷ 4 = 14 — 확인: 4 × 14 = 56이에요."],"variant_rule":{"alt":[{"stem":"58 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 18 ÷ 2 → 몫 9.","58 ÷ 2 = 29 — 확인: 2 × 29 = 58이에요."],"asset":null},{"stem":"96 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 16 ÷ 4 → 몫 4.","96 ÷ 4 = 24 — 확인: 4 × 24 = 96이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#6','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',1,'sa','auto','37 ÷ 9의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"37 ÷ 9의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 9의 단에서 37보다 크지 않은 가장 큰 곱을 찾아요.","9 × 4 = 36 — 몫 4, 37 − 36 = 1이 남아요.","37 ÷ 9 = 4 … 1 — 나머지 1은 나누는 수 9보다 작아요."],"variant_rule":{"alt":[{"stem":"15 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 4의 단에서 15보다 크지 않은 가장 큰 곱을 찾아요.","4 × 3 = 12 — 몫 3, 15 − 12 = 3이 남아요.","15 ÷ 4 = 3 … 3 — 나머지 3은 나누는 수 4보다 작아요."],"asset":null},{"stem":"19 ÷ 2의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 2의 단에서 19보다 크지 않은 가장 큰 곱을 찾아요.","2 × 9 = 18 — 몫 9, 19 − 18 = 1이 남아요.","19 ÷ 2 = 9 … 1 — 나머지 1은 나누는 수 2보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#7','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',1,'sa','auto','53 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"53 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 2 → 몫 6.","53 ÷ 2 = 26 … 1 — 확인: 2 × 26 + 1 = 53이에요."],"variant_rule":{"alt":[{"stem":"95 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 8 → 몫 1.","95 ÷ 8 = 11 … 7 — 확인: 8 × 11 + 7 = 95예요."],"asset":null},{"stem":"76 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 6 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 6 → 몫 2.","76 ÷ 6 = 12 … 4 — 확인: 6 × 12 + 4 = 76이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#8','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',1,'sa','auto','403 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"403 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 3은 4로 나눌 수 없어 몫 0.","403 ÷ 4 = 100 … 3 — 확인: 4 × 100 + 3 = 403이에요."],"variant_rule":{"alt":[{"stem":"979 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 7은 9로 나눌 수 없어 몫 0, 7 남음 · 남은 7을 내려 79 ÷ 9 → 몫 8.","979 ÷ 9 = 108 … 7 — 확인: 9 × 108 + 7 = 979예요."],"asset":null},{"stem":"607 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["202"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","607 ÷ 3 = 202 … 1 — 확인: 3 × 202 + 1 = 607이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#9','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',2,'sa','auto','559 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"559 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 5는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 55로 보고 55 ÷ 6 → 몫 9, 1 남음 · 남은 1을 내려 19 ÷ 6 → 몫 3.","559 ÷ 6 = 93 … 1 — 확인: 6 × 93 + 1 = 559예요."],"variant_rule":{"alt":[{"stem":"332 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 33으로 보고 33 ÷ 4 → 몫 8, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","332 ÷ 4 = 83 — 확인: 4 × 83 = 332예요."],"asset":null},{"stem":"291 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 29로 보고 29 ÷ 3 → 몫 9, 2 남음 · 남은 2를 내려 21 ÷ 3 → 몫 7.","291 ÷ 3 = 97 — 확인: 3 × 97 = 291이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#10','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C4',2,'mc','auto','84 ÷ 7을 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":10,"concept":"M3-2-u2-C4","difficulty":2,"kind":"mc","stem":"84 ÷ 7을 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","7 × 10 = 70, 7 × 20 = 140 — 84는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 12예요."],"variant_rule":{"alt":[{"stem":"54 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"20과 30 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"30보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 300 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 20 = 40, 2 × 30 = 60 — 54는 그 사이에 있어요.","그래서 몫은 20과 30 사이 — 실제 몫 27이에요."],"asset":null},{"stem":"36 ÷ 2를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","2 × 10 = 20, 2 × 20 = 40 — 36은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 18이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#11','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',2,'mc','auto','30 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":11,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"30 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 … 2","correct":true},{"t":"6 … 6","mis":"M3-2-u2-X05"},{"t":"2 … 7","mis":"M3-2-u2-X06"},{"t":"7","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 4의 단에서 30보다 크지 않은 가장 큰 곱을 찾아요.","4 × 7 = 28 — 몫 7, 30 − 28 = 2가 남아요.","30 ÷ 4 = 7 … 2 — 나머지 2는 나누는 수 4보다 작아요."],"variant_rule":{"alt":[{"stem":"26 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 2","correct":true},{"t":"5 … 6","mis":"M3-2-u2-X05"},{"t":"2 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 4의 단에서 26보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 26 − 24 = 2가 남아요.","26 ÷ 4 = 6 … 2 — 나머지 2는 나누는 수 4보다 작아요."],"asset":null},{"stem":"25 ÷ 4의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 1","correct":true},{"t":"5 … 5","mis":"M3-2-u2-X05"},{"t":"1 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 4의 단에서 25보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 나머지 1은 나누는 수 4보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#12','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',2,'sa','auto','79 ÷ 5 = 15 … 4를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"79 ÷ 5 = 15 … 4를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["75"],"explanation":["나누는 수 × 몫 = 5 × 15 = 75예요.","여기에 나머지 4를 더하면 79예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 15","=",null],["□ + 4","=","79"]]},"variant_rule":{"alt":[{"stem":"96 ÷ 9 = 10 … 6을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["96"],"explanation":["나누는 수 × 몫 = 9 × 10 = 90이에요.","여기에 나머지 6을 더하면 96이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["9 × 10","=","90"],["90 + 6","=",null]]}},{"stem":"81 ÷ 5 = 16 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["80"],"explanation":["나누는 수 × 몫 = 5 × 16 = 80이에요.","여기에 나머지 1을 더하면 81이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 16","=",null],["□ + 1","=","81"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#13','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',2,'sa','auto','965 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"965 ÷ 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 46 ÷ 5 → 몫 9, 1 남음 · 남은 1을 내려 15 ÷ 5 → 몫 3.","965 ÷ 5 = 193 — 일의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":965,"b":5,"hide":[["q",2]]},"variant_rule":{"alt":[{"stem":"882 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 28 ÷ 6 → 몫 4, 4 남음 · 남은 4를 내려 42 ÷ 6 → 몫 7.","882 ÷ 6 = 147 — 일의 자리 숫자는 7이에요."],"asset":{"type":"ldiv","a":882,"b":6,"hide":[["q",2]]}},{"stem":"803 ÷ 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 일의 자리 — 백의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 7 → 몫 1, 3 남음 · 남은 3을 내려 33 ÷ 7 → 몫 4.","803 ÷ 7 = 114 … 5 — 일의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":803,"b":7,"hide":[["q",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#14','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',2,'mc','auto','148 ÷ 5의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":14,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"148 ÷ 5의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 1과 나누는 수 5와 견주어요.","1은 5보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","148 ÷ 5 = 29 … 3."],"variant_rule":{"alt":[{"stem":"122 ÷ 6의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 1과 나누는 수 6과 견주어요.","1은 6보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","122 ÷ 6 = 20 … 2."],"asset":null},{"stem":"451 ÷ 9의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 4와 나누는 수 9와 견주어요.","4는 9보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","451 ÷ 9 = 50 … 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#15','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',2,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["137"],"explanation":["블록 수 ÷ 열쇠고리 수 — 687 ÷ 5.","백의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 5 → 몫 3, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","687 ÷ 5 = 137 … 2 — 한 개에 137개씩, 2개 남아요."],"variant_rule":{"alt":[{"stem":"정후가 흰색 블록 112개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["37"],"explanation":["블록 수 ÷ 열쇠고리 수 — 112 ÷ 3.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 11로 보고 11 ÷ 3 → 몫 3, 2 남음 · 남은 2를 내려 22 ÷ 3 → 몫 7.","112 ÷ 3 = 37 … 1 — 한 개에 37개씩, 1개 남아요."],"asset":null},{"stem":"태민이 주황색 블록 252개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 주황색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["50"],"explanation":["블록 수 ÷ 열쇠고리 수 — 252 ÷ 5.","백의 자리 2는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 5 → 몫 5 · 일의 자리 2는 5로 나눌 수 없어 몫 0.","252 ÷ 5 = 50 … 2 — 한 개에 50개씩, 2개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#16','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C5',2,'sa','auto','84 ÷ 6을 60과 24로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"84 ÷ 6을 60과 24로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["84를 60과 24로 갈라요 — 둘 다 6으로 나누어떨어져요.","60 ÷ 6 = 10, 24 ÷ 6 = 4예요.","10 + 4 = 14 — 84 ÷ 6의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 6","=","10"],["24 ÷ 6","=",null],["10 + □","=","14"]]},"variant_rule":{"alt":[{"stem":"76 ÷ 2를 60과 16으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["76을 60과 16으로 갈라요 — 둘 다 2로 나누어떨어져요.","60 ÷ 2 = 30, 16 ÷ 2 = 8이에요.","30 + 8 = 38 — 76 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 2","=",null],["16 ÷ 2","=","8"],["□ + 8","=","38"]]}},{"stem":"45 ÷ 3을 30과 15로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["45를 30과 15로 갈라요 — 둘 다 3으로 나누어떨어져요.","30 ÷ 3 = 10, 15 ÷ 3 = 5예요.","10 + 5 = 15 — 45 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["30 ÷ 3","=","10"],["15 ÷ 3","=","5"],["10 + 5","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#17','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C2',3,'error','auto','90 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":17,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"90 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「90 ÷ 2 = 46이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"도윤 — 「90 ÷ 2 = 45야」","mis":"M3-2-u2-X17"},{"t":"시우 — 「확인하면 2 × 45 = 90이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","90 ÷ 2 = 45.","태오가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"90 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「90 ÷ 6 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"서윤 — 「90 ÷ 6 = 15야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「90 ÷ 6은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15.","하린이 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null},{"stem":"60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「60 ÷ 5 = 13이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"지유 — 「60 ÷ 5 = 12야」","mis":"M3-2-u2-X17"},{"t":"은우 — 「확인하면 5 × 12 = 60이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","60 ÷ 5 = 12.","태오가 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#18','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',3,'ox','auto','629 ÷ 6 = 14 … 5예요.',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":18,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"629 ÷ 6 = 14 … 5예요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 2는 6으로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 29 ÷ 6 → 몫 4.","바르게 계산하면 629 ÷ 6 = 104 … 5.","나눌 수 없으면 몫에 0 — 확인: 6 × 104 + 5 = 629예요."],"asset":{"type":"ldiv","a":629,"b":6,"upto":0},"variant_rule":{"alt":[{"stem":"309 ÷ 3 = 13이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 3 → 몫 3.","바르게 계산하면 309 ÷ 3 = 103.","나눌 수 없으면 몫에 0 — 확인: 3 × 103 = 309예요."],"asset":{"type":"ldiv","a":309,"b":3,"upto":0}},{"stem":"909 ÷ 9 = 11이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 9 → 몫 1.","바르게 계산하면 909 ÷ 9 = 101.","나눌 수 없으면 몫에 0 — 확인: 9 × 101 = 909예요."],"asset":{"type":"ldiv","a":909,"b":9,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#19','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',3,'sa','auto','어떤 수를 4로 나누었더니 몫이 24이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 4로 나누었더니 몫이 24이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","4 × 24 = 96, 96 + 2 = 98이에요.","확인: 98 ÷ 4 = 24 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 5로 나누었더니 몫이 16이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","5 × 16 = 80, 80 + 4 = 84예요.","확인: 84 ÷ 5 = 16 … 4."],"asset":null},{"stem":"어떤 수를 9로 나누었더니 몫이 10이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","9 × 10 = 90, 90 + 6 = 96이에요.","확인: 96 ÷ 9 = 10 … 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#20','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',3,'ox','auto','467 ÷ 5 = 92 … 7이에요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"467 ÷ 5 = 92 … 7이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 4는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 46으로 보고 46 ÷ 5 → 몫 9, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","바르게 계산하면 467 ÷ 5 = 93 … 2.","나머지 < 나누는 수 — 확인: 5 × 93 + 2 = 467이에요."],"asset":{"type":"ldiv","a":467,"b":5,"upto":0},"variant_rule":{"alt":[{"stem":"763 ÷ 8 = 94 … 11이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 7은 8보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 76으로 보고 76 ÷ 8 → 몫 9, 4 남음 · 남은 4를 내려 43 ÷ 8 → 몫 5.","바르게 계산하면 763 ÷ 8 = 95 … 3.","나머지 < 나누는 수 — 확인: 8 × 95 + 3 = 763이에요."],"asset":{"type":"ldiv","a":763,"b":8,"upto":0}},{"stem":"205 ÷ 6 = 33 … 7이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 2는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 20으로 보고 20 ÷ 6 → 몫 3, 2 남음 · 남은 2를 내려 25 ÷ 6 → 몫 4.","바르게 계산하면 205 ÷ 6 = 34 … 1.","나머지 < 나누는 수 — 확인: 6 × 34 + 1 = 205예요."],"asset":{"type":"ldiv","a":205,"b":6,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#21','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',3,'mc','auto','한 번에 6명씩 탈 수 있는 보트로 봉사 활동 학생 62명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":21,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 번에 6명씩 탈 수 있는 보트로 봉사 활동 학생 62명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"11번","correct":true},{"t":"10번","mis":"M3-2-u2-X13"},{"t":"2번","mis":"M3-2-u2-X13"},{"t":"12번","mis":"M3-2-u2-X15"}],"explanation":["62 ÷ 6 = 10 … 2.","10번으로는 2명이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11번이에요."],"variant_rule":{"alt":[{"stem":"한 상자에 6권씩 담을 수 있어요. 도서관 책 64권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"11개","correct":true},{"t":"10개","mis":"M3-2-u2-X13"},{"t":"4개","mis":"M3-2-u2-X13"},{"t":"12개","mis":"M3-2-u2-X15"}],"explanation":["64 ÷ 6 = 10 … 4.","10개로는 4권이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11개예요."],"asset":null},{"stem":"한 대에 3명씩 탈 수 있는 차로 학생 40명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"14대","correct":true},{"t":"13대","mis":"M3-2-u2-X13"},{"t":"1대","mis":"M3-2-u2-X13"},{"t":"15대","mis":"M3-2-u2-X15"}],"explanation":["40 ÷ 3 = 13 … 1.","13대로는 1명이 남아요 — 남은 것도 옮겨야 해요.","그래서 13 + 1 = 14 — 적어도 14대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#22','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',3,'mc','auto','38 ÷ 6, 19 ÷ 2, 55 ÷ 7 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"38 ÷ 6, 19 ÷ 2, 55 ÷ 7 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"55 ÷ 7","correct":true},{"t":"38 ÷ 6","mis":"M3-2-u2-X15"},{"t":"19 ÷ 2","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","38 ÷ 6 = 6 … 2, 19 ÷ 2 = 9 … 1, 55 ÷ 7 = 7 … 6.","나머지가 가장 큰 것은 55 ÷ 7 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"29 ÷ 4, 47 ÷ 9, 34 ÷ 5 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"34 ÷ 5","correct":true},{"t":"29 ÷ 4","mis":"M3-2-u2-X17"},{"t":"47 ÷ 9","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","29 ÷ 4 = 7 … 1, 47 ÷ 9 = 5 … 2, 34 ÷ 5 = 6 … 4.","나머지가 가장 큰 것은 34 ÷ 5 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null},{"stem":"43 ÷ 5, 61 ÷ 8, 25 ÷ 3 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"61 ÷ 8","correct":true},{"t":"43 ÷ 5","mis":"M3-2-u2-X17"},{"t":"25 ÷ 3","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","43 ÷ 5 = 8 … 3, 61 ÷ 8 = 7 … 5, 25 ÷ 3 = 8 … 1.","나머지가 가장 큰 것은 61 ÷ 8 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#23','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',4,'mc','auto','곶감을 5접시에 13개씩 담았더니 4개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":23,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"곶감을 5접시에 13개씩 담았더니 4개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"69개","correct":true},{"t":"65개","mis":"M3-2-u2-X09"},{"t":"61개","mis":"M3-2-u2-X14"},{"t":"85개","mis":"M3-2-u2-X08"}],"explanation":["5접시에 13개씩 — 5 × 13 = 65개.","남은 4개를 더해요.","65 + 4 = 69 — 모두 69개예요."],"variant_rule":{"alt":[{"stem":"약과를 7봉지에 12개씩 담았더니 6개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"90개","correct":true},{"t":"84개","mis":"M3-2-u2-X09"},{"t":"78개","mis":"M3-2-u2-X14"},{"t":"126개","mis":"M3-2-u2-X08"}],"explanation":["7봉지에 12개씩 — 7 × 12 = 84개.","남은 6개를 더해요.","84 + 6 = 90 — 모두 90개예요."],"asset":null},{"stem":"종이꽃을 9바구니에 8개씩 담았더니 7개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"79개","correct":true},{"t":"72개","mis":"M3-2-u2-X09"},{"t":"65개","mis":"M3-2-u2-X14"},{"t":"135개","mis":"M3-2-u2-X08"}],"explanation":["9바구니에 8개씩 — 9 × 8 = 72개.","남은 7개를 더해요.","72 + 7 = 79 — 모두 79개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#24','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',4,'sa','auto','어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 740이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u2-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누어야 하는데 잘못하여 4를 곱했더니 740이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["어떤 수 × 4 = 740 → 어떤 수는 740 ÷ 4 = 185예요.","바르게 계산하면 185 ÷ 4.","185 ÷ 4 = 46 … 1 — 몫은 46이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 5로 나누어야 하는데 잘못하여 5를 곱했더니 1595가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["어떤 수 × 5 = 1595 → 어떤 수는 1595 ÷ 5 = 319예요.","바르게 계산하면 319 ÷ 5.","319 ÷ 5 = 63 … 4 — 몫은 63이에요."],"asset":null},{"stem":"어떤 수를 8로 나누어야 하는데 잘못하여 8을 곱했더니 1976이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["어떤 수 × 8 = 1976 → 어떤 수는 1976 ÷ 8 = 247이에요.","바르게 계산하면 247 ÷ 8.","247 ÷ 8 = 30 … 7 — 몫은 30이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_c#25','math',3,2,'u2','','g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',4,'essay','teacher','438 ÷ 9의 몫이 몇 자리 수인지 먼저 알아보고, 세로셈으로 몫과 나머지를 구해 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C9","difficulty":4,"kind":"essay","stem":"438 ÷ 9의 몫이 몇 자리 수인지 먼저 알아보고, 세로셈으로 몫과 나머지를 구해 확인해 보세요.","answer_guide":{"answer":"예: 백의 자리 4는 9보다 작아 몫은 두 자리 수이다. 43 ÷ 9 = 4 … 7, 남은 7을 내려 78 ÷ 9 = 8 … 6이므로 438 ÷ 9 = 48 … 6이다. 확인: 9 × 48 + 6 = 432 + 6 = 438.","scoring_points":["몫이 두 자리라고 했는가","48 … 6을 구했는가","9 × 48 + 6 = 438로 확인했는가"]},"explanation":["4 < 9 → 몫 두 자리.","43 ÷ 9 → 4, 7 남음 · 78 ÷ 9 → 8, 6 남음.","9 × 48 + 6 = 438."],"asset":{"type":"ldiv","a":438,"b":9,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#1','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C1',1,'sa','auto','30 ÷ 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"30 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 5의 단에서 30을 찾아요.","5 × 6 = 30 — 그래서 30 ÷ 5 = 6이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"56 ÷ 8은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나누는 수 8의 단에서 56을 찾아요.","8 × 7 = 56 — 그래서 56 ÷ 8 = 7이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null},{"stem":"54 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["나누는 수 6의 단에서 54를 찾아요.","6 × 9 = 54 — 그래서 54 ÷ 6 = 9예요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#2','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C1',1,'sa','auto','4 ÷ 2 = 2예요. 그러면 40 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"4 ÷ 2 = 2예요. 그러면 40 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["40은 4의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","2의 10배 — 40 ÷ 2 = 20이에요."],"variant_rule":{"alt":[{"stem":"7 ÷ 7 = 1이에요. 그러면 70 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["70은 7의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 70 ÷ 7 = 10이에요."],"asset":null},{"stem":"3 ÷ 3 = 1이에요. 그러면 30 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["30은 3의 10배예요.","나누어지는 수가 10배가 되면 몫도 10배가 돼요.","1의 10배 — 30 ÷ 3 = 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#3','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C2',1,'sa','auto','90 ÷ 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"90 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 확인: 6 × 15 = 90이에요."],"variant_rule":{"alt":[{"stem":"90 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","90 ÷ 5 = 18 — 확인: 5 × 18 = 90이에요."],"asset":null},{"stem":"60 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","60 ÷ 5 = 12 — 확인: 5 × 12 = 60이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#4','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C3',1,'sa','auto','77 ÷ 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"77 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 7 → 몫 1 · 일의 자리 7 ÷ 7 → 몫 1.","77 ÷ 7 = 11 — 확인: 7 × 11 = 77이에요."],"variant_rule":{"alt":[{"stem":"22 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 2 ÷ 2 → 몫 1.","22 ÷ 2 = 11 — 확인: 2 × 11 = 22예요."],"asset":null},{"stem":"66 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 6 ÷ 3 → 몫 2.","66 ÷ 3 = 22 — 확인: 3 × 22 = 66이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#5','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C5',1,'sa','auto','78 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"78 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 18 ÷ 3 → 몫 6.","78 ÷ 3 = 26 — 확인: 3 × 26 = 78이에요."],"variant_rule":{"alt":[{"stem":"64 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 4 → 몫 6.","64 ÷ 4 = 16 — 확인: 4 × 16 = 64예요."],"asset":null},{"stem":"72 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 4 → 몫 8.","72 ÷ 4 = 18 — 확인: 4 × 18 = 72예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#6','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',1,'sa','auto','15 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"15 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 7의 단에서 15보다 크지 않은 가장 큰 곱을 찾아요.","7 × 2 = 14 — 몫 2, 15 − 14 = 1이 남아요.","15 ÷ 7 = 2 … 1 — 나머지 1은 나누는 수 7보다 작아요."],"variant_rule":{"alt":[{"stem":"44 ÷ 5의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 5의 단에서 44보다 크지 않은 가장 큰 곱을 찾아요.","5 × 8 = 40 — 몫 8, 44 − 40 = 4가 남아요.","44 ÷ 5 = 8 … 4 — 나머지 4는 나누는 수 5보다 작아요."],"asset":null},{"stem":"30 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 7의 단에서 30보다 크지 않은 가장 큰 곱을 찾아요.","7 × 4 = 28 — 몫 4, 30 − 28 = 2가 남아요.","30 ÷ 7 = 4 … 2 — 나머지 2는 나누는 수 7보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#7','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',1,'sa','auto','77 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"77 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 17 ÷ 2 → 몫 8.","77 ÷ 2 = 38 … 1 — 확인: 2 × 38 + 1 = 77이에요."],"variant_rule":{"alt":[{"stem":"95 ÷ 8의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 8 → 몫 1.","95 ÷ 8 = 11 … 7 — 확인: 8 × 11 + 7 = 95예요."],"asset":null},{"stem":"99 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 7 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 7 → 몫 4.","99 ÷ 7 = 14 … 1 — 확인: 7 × 14 + 1 = 99예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#8','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',1,'sa','auto','614 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"614 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["204"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 14 ÷ 3 → 몫 4.","614 ÷ 3 = 204 … 2 — 확인: 3 × 204 + 2 = 614예요."],"variant_rule":{"alt":[{"stem":"743 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["106"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 7 ÷ 7 → 몫 1 · 십의 자리 4는 7로 나눌 수 없어 몫 0, 4 남음 · 남은 4를 내려 43 ÷ 7 → 몫 6.","743 ÷ 7 = 106 … 1 — 확인: 7 × 106 + 1 = 743이에요."],"asset":null},{"stem":"407 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["203"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4 ÷ 2 → 몫 2 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 2 → 몫 3.","407 ÷ 2 = 203 … 1 — 확인: 2 × 203 + 1 = 407이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#9','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',2,'sa','auto','438 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"438 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["73"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 43으로 보고 43 ÷ 6 → 몫 7, 1 남음 · 남은 1을 내려 18 ÷ 6 → 몫 3.","438 ÷ 6 = 73 — 확인: 6 × 73 = 438이에요."],"variant_rule":{"alt":[{"stem":"268 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 26으로 보고 26 ÷ 9 → 몫 2, 8 남음 · 남은 8을 내려 88 ÷ 9 → 몫 9.","268 ÷ 9 = 29 … 7 — 확인: 9 × 29 + 7 = 268이에요."],"asset":null},{"stem":"231 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 23으로 보고 23 ÷ 7 → 몫 3, 2 남음 · 남은 2를 내려 21 ÷ 7 → 몫 3.","231 ÷ 7 = 33 — 확인: 7 × 33 = 231이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#10','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C4',2,'mc','auto','52 ÷ 4를 어림하면 몫은 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":10,"concept":"M3-2-u2-C4","difficulty":2,"kind":"mc","stem":"52 ÷ 4를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","4 × 10 = 40, 4 × 20 = 80 — 52는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 13이에요."],"variant_rule":{"alt":[{"stem":"85 ÷ 5를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","5 × 10 = 50, 5 × 20 = 100 — 85는 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 17이에요."],"asset":null},{"stem":"76 ÷ 4를 어림하면 몫은 어느 사이에 있나요?","options":[{"t":"10과 20 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"20보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 200 사이","mis":"M3-2-u2-X02"}],"explanation":["나누는 수 × 몇십(몇백)으로 나누어지는 수를 감싸 봐요.","4 × 10 = 40, 4 × 20 = 80 — 76은 그 사이에 있어요.","그래서 몫은 10과 20 사이 — 실제 몫 19예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#11','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',2,'mc','auto','54 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":11,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"54 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 … 5","correct":true},{"t":"6 … 12","mis":"M3-2-u2-X05"},{"t":"5 … 7","mis":"M3-2-u2-X06"},{"t":"7","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 7의 단에서 54보다 크지 않은 가장 큰 곱을 찾아요.","7 × 7 = 49 — 몫 7, 54 − 49 = 5가 남아요.","54 ÷ 7 = 7 … 5 — 나머지 5는 나누는 수 7보다 작아요."],"variant_rule":{"alt":[{"stem":"20 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 … 2","correct":true},{"t":"5 … 5","mis":"M3-2-u2-X05"},{"t":"2 … 6","mis":"M3-2-u2-X06"},{"t":"6","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 3의 단에서 20보다 크지 않은 가장 큰 곱을 찾아요.","3 × 6 = 18 — 몫 6, 20 − 18 = 2가 남아요.","20 ÷ 3 = 6 … 2 — 나머지 2는 나누는 수 3보다 작아요."],"asset":null},{"stem":"41 ÷ 5의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 … 1","correct":true},{"t":"7 … 6","mis":"M3-2-u2-X05"},{"t":"1 … 8","mis":"M3-2-u2-X06"},{"t":"8","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 5의 단에서 41보다 크지 않은 가장 큰 곱을 찾아요.","5 × 8 = 40 — 몫 8, 41 − 40 = 1이 남아요.","41 ÷ 5 = 8 … 1 — 나머지 1은 나누는 수 5보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#12','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',2,'sa','auto','81 ÷ 6 = 13 … 3을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"81 ÷ 6 = 13 … 3을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["81"],"explanation":["나누는 수 × 몫 = 6 × 13 = 78이에요.","여기에 나머지 3을 더하면 81이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["6 × 13","=","78"],["78 + 3","=",null]]},"variant_rule":{"alt":[{"stem":"96 ÷ 9 = 10 … 6을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["90"],"explanation":["나누는 수 × 몫 = 9 × 10 = 90이에요.","여기에 나머지 6을 더하면 96이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["9 × 10","=",null],["□ + 6","=","96"]]}},{"stem":"98 ÷ 9 = 10 … 8을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["98"],"explanation":["나누는 수 × 몫 = 9 × 10 = 90이에요.","여기에 나머지 8을 더하면 98이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["9 × 10","=","90"],["90 + 8","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#13','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',2,'sa','auto','468 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"468 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 백의 자리 — 백의 자리 4 ÷ 2 → 몫 2 · 십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 8 ÷ 2 → 몫 4.","468 ÷ 2 = 234 — 백의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":468,"b":2,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"515 ÷ 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 백의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 11 ÷ 2 → 몫 5, 1 남음 · 남은 1을 내려 15 ÷ 2 → 몫 7.","515 ÷ 2 = 257 … 1 — 십의 자리 숫자는 5예요."],"asset":{"type":"ldiv","a":515,"b":2,"hide":[["q",1]]}},{"stem":"994 ÷ 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 위에 써요.","?는 몫의 십의 자리 — 백의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 39 ÷ 6 → 몫 6, 3 남음 · 남은 3을 내려 34 ÷ 6 → 몫 5.","994 ÷ 6 = 165 … 4 — 십의 자리 숫자는 6이에요."],"asset":{"type":"ldiv","a":994,"b":6,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#14','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',2,'mc','auto','316 ÷ 7의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":14,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"316 ÷ 7의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 3과 나누는 수 7과 견주어요.","3은 7보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","316 ÷ 7 = 45 … 1."],"variant_rule":{"alt":[{"stem":"853 ÷ 9의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 8과 나누는 수 9와 견주어요.","8은 9보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","853 ÷ 9 = 94 … 7."],"asset":null},{"stem":"343 ÷ 8의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 3과 나누는 수 8과 견주어요.","3은 8보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","343 ÷ 8 = 42 … 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#15','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',2,'sa','auto','정후가 검은색 블록 314개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"정후가 검은색 블록 314개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["104"],"explanation":["블록 수 ÷ 열쇠고리 수 — 314 ÷ 3.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 14 ÷ 3 → 몫 4.","314 ÷ 3 = 104 … 2 — 한 개에 104개씩, 2개 남아요."],"variant_rule":{"alt":[{"stem":"태민이 초록색 블록 90개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 초록색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["22"],"explanation":["블록 수 ÷ 열쇠고리 수 — 90 ÷ 4.","십의 자리 9 ÷ 4 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 4 → 몫 2.","90 ÷ 4 = 22 … 2 — 한 개에 22개씩, 2개 남아요."],"asset":null},{"stem":"태민이 파란색 블록 48개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 파란색 블록을 몇 개씩 쓸 수 있나요? 숫자로 쓰세요.","answer":["9"],"explanation":["블록 수 ÷ 열쇠고리 수 — 48 ÷ 5.","5 × 9 = 45 — 몫 9, 48 − 45 = 3이 남아요.","48 ÷ 5 = 9 … 3 — 한 개에 9개씩, 3개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#16','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C5',2,'sa','auto','42 ÷ 3을 30과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"42 ÷ 3을 30과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["42를 30과 12로 갈라요 — 둘 다 3으로 나누어떨어져요.","30 ÷ 3 = 10, 12 ÷ 3 = 4예요.","10 + 4 = 14 — 42 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["30 ÷ 3","=",null],["12 ÷ 3","=","4"],["□ + 4","=","14"]]},"variant_rule":{"alt":[{"stem":"54 ÷ 3을 30과 24로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["18"],"explanation":["54를 30과 24로 갈라요 — 둘 다 3으로 나누어떨어져요.","30 ÷ 3 = 10, 24 ÷ 3 = 8이에요.","10 + 8 = 18 — 54 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["30 ÷ 3","=","10"],["24 ÷ 3","=","8"],["10 + 8","=",null]]}},{"stem":"84 ÷ 7을 70과 14로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["84를 70과 14로 갈라요 — 둘 다 7로 나누어떨어져요.","70 ÷ 7 = 10, 14 ÷ 7 = 2예요.","10 + 2 = 12 — 84 ÷ 7의 몫이에요."],"asset":{"type":"expr_grid","rows":[["70 ÷ 7","=","10"],["14 ÷ 7","=",null],["10 + □","=","12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#17','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C2',3,'error','auto','70 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":17,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"70 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「70 ÷ 5 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지유 — 「70 ÷ 5 = 14야」","mis":"M3-2-u2-X17"},{"t":"시우 — 「70 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14.","도윤이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"90 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「90 ÷ 5 = 19야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태오 — 「90 ÷ 5 = 18이야」","mis":"M3-2-u2-X17"},{"t":"지유 — 「확인하면 5 × 18 = 90이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","90 ÷ 5 = 18.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"asset":null},{"stem":"30 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「30 ÷ 2 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"서윤 — 「30 ÷ 2 = 15야」","mis":"M3-2-u2-X17"},{"t":"태오 — 「30 ÷ 2는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15.","하랑이 잘못 말했어요 — 남은 수는 아래로 내리기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#18','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',3,'ox','auto','326 ÷ 3 = 18 … 2예요.',ARRAY['M3-2-u2-X10']::text[],true,'{"seq":18,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"326 ÷ 3 = 18 … 2예요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 2는 3으로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 26 ÷ 3 → 몫 8.","바르게 계산하면 326 ÷ 3 = 108 … 2.","나눌 수 없으면 몫에 0 — 확인: 3 × 108 + 2 = 326이에요."],"asset":{"type":"ldiv","a":326,"b":3,"upto":0},"variant_rule":{"alt":[{"stem":"216 ÷ 2 = 18이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 2 ÷ 2 → 몫 1 · 십의 자리 1은 2로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 16 ÷ 2 → 몫 8.","바르게 계산하면 216 ÷ 2 = 108.","나눌 수 없으면 몫에 0 — 확인: 2 × 108 = 216이에요."],"asset":{"type":"ldiv","a":216,"b":2,"upto":0}},{"stem":"921 ÷ 3 = 37이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"explanation":["백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 2는 3으로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 21 ÷ 3 → 몫 7.","바르게 계산하면 921 ÷ 3 = 307.","나눌 수 없으면 몫에 0 — 확인: 3 × 307 = 921이에요."],"asset":{"type":"ldiv","a":921,"b":3,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#19','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',3,'sa','auto','어떤 수를 4로 나누었더니 몫이 21이고 나머지가 3이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 4로 나누었더니 몫이 21이고 나머지가 3이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","4 × 21 = 84, 84 + 3 = 87이에요.","확인: 87 ÷ 4 = 21 … 3."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었더니 몫이 10이고 나머지가 5가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","6 × 10 = 60, 60 + 5 = 65예요.","확인: 65 ÷ 6 = 10 … 5."],"asset":null},{"stem":"어떤 수를 2로 나누었더니 몫이 36이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["73"],"explanation":["어떤 수 = 나누는 수 × 몫 + 나머지.","2 × 36 = 72, 72 + 1 = 73이에요.","확인: 73 ÷ 2 = 36 … 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#20','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',3,'ox','auto','473 ÷ 9 = 51 … 14예요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"473 ÷ 9 = 51 … 14예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 4는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 47로 보고 47 ÷ 9 → 몫 5, 2 남음 · 남은 2를 내려 23 ÷ 9 → 몫 2.","바르게 계산하면 473 ÷ 9 = 52 … 5.","나머지 < 나누는 수 — 확인: 9 × 52 + 5 = 473이에요."],"asset":{"type":"ldiv","a":473,"b":9,"upto":0},"variant_rule":{"alt":[{"stem":"613 ÷ 9 = 67 … 10이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 6은 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 61로 보고 61 ÷ 9 → 몫 6, 7 남음 · 남은 7을 내려 73 ÷ 9 → 몫 8.","바르게 계산하면 613 ÷ 9 = 68 … 1.","나머지 < 나누는 수 — 확인: 9 × 68 + 1 = 613이에요."],"asset":{"type":"ldiv","a":613,"b":9,"upto":0}},{"stem":"517 ÷ 6 = 85 … 7이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 5는 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 51로 보고 51 ÷ 6 → 몫 8, 3 남음 · 남은 3을 내려 37 ÷ 6 → 몫 6.","바르게 계산하면 517 ÷ 6 = 86 … 1.","나머지 < 나누는 수 — 확인: 6 × 86 + 1 = 517이에요."],"asset":{"type":"ldiv","a":517,"b":6,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#21','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',3,'mc','auto','한 상자에 5권씩 담을 수 있어요. 도서관 책 87권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15']::text[],true,'{"seq":21,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 상자에 5권씩 담을 수 있어요. 도서관 책 87권을 모두 담으려면 상자는 적어도 몇 개 필요한가요?","options":[{"t":"18개","correct":true},{"t":"17개","mis":"M3-2-u2-X13"},{"t":"2개","mis":"M3-2-u2-X13"},{"t":"19개","mis":"M3-2-u2-X15"}],"explanation":["87 ÷ 5 = 17 … 2.","17개로는 2권이 남아요 — 남은 것도 옮겨야 해요.","그래서 17 + 1 = 18 — 적어도 18개예요."],"variant_rule":{"alt":[{"stem":"한 대에 3명씩 탈 수 있는 차로 학생 58명이 모두 복지관에 가려고 해요. 차는 적어도 몇 대 필요한가요?","options":[{"t":"20대","correct":true},{"t":"19대","mis":"M3-2-u2-X13"},{"t":"1대","mis":"M3-2-u2-X13"},{"t":"21대","mis":"M3-2-u2-X15"}],"explanation":["58 ÷ 3 = 19 … 1.","19대로는 1명이 남아요 — 남은 것도 옮겨야 해요.","그래서 19 + 1 = 20 — 적어도 20대예요."],"asset":null},{"stem":"한 번에 8명씩 탈 수 있는 보트로 봉사 활동 학생 82명이 모두 강을 건너려고 해요. 보트는 적어도 몇 번 건너야 하나요?","options":[{"t":"11번","correct":true},{"t":"10번","mis":"M3-2-u2-X13"},{"t":"2번","mis":"M3-2-u2-X13"},{"t":"12번","mis":"M3-2-u2-X15"}],"explanation":["82 ÷ 8 = 10 … 2.","10번으로는 2명이 남아요 — 남은 것도 옮겨야 해요.","그래서 10 + 1 = 11 — 적어도 11번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#22','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',3,'mc','auto','35 ÷ 4, 53 ÷ 6, 70 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],true,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"35 ÷ 4, 53 ÷ 6, 70 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"70 ÷ 9","correct":true},{"t":"35 ÷ 4","mis":"M3-2-u2-X17"},{"t":"53 ÷ 6","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","35 ÷ 4 = 8 … 3, 53 ÷ 6 = 8 … 5, 70 ÷ 9 = 7 … 7.","나머지가 가장 큰 것은 70 ÷ 9 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"22 ÷ 5, 41 ÷ 7, 66 ÷ 8 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"41 ÷ 7","correct":true},{"t":"22 ÷ 5","mis":"M3-2-u2-X15"},{"t":"66 ÷ 8","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","22 ÷ 5 = 4 … 2, 41 ÷ 7 = 5 … 6, 66 ÷ 8 = 8 … 2.","나머지가 가장 큰 것은 41 ÷ 7 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null},{"stem":"37 ÷ 6, 58 ÷ 9, 29 ÷ 3 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"58 ÷ 9","correct":true},{"t":"37 ÷ 6","mis":"M3-2-u2-X15"},{"t":"29 ÷ 3","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","37 ÷ 6 = 6 … 1, 58 ÷ 9 = 6 … 4, 29 ÷ 3 = 9 … 2.","나머지가 가장 큰 것은 58 ÷ 9 — 몫이 큰 것과 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#23','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',4,'mc','auto','곶감을 6접시에 15개씩 담았더니 5개가 남았어요. 곶감은 모두 몇 개인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X14','M3-2-u2-X08']::text[],true,'{"seq":23,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"곶감을 6접시에 15개씩 담았더니 5개가 남았어요. 곶감은 모두 몇 개인가요?","options":[{"t":"95개","correct":true},{"t":"90개","mis":"M3-2-u2-X09"},{"t":"85개","mis":"M3-2-u2-X14"},{"t":"120개","mis":"M3-2-u2-X08"}],"explanation":["6접시에 15개씩 — 6 × 15 = 90개.","남은 5개를 더해요.","90 + 5 = 95 — 모두 95개예요."],"variant_rule":{"alt":[{"stem":"약과를 8봉지에 9개씩 담았더니 7개가 남았어요. 약과는 모두 몇 개인가요?","options":[{"t":"79개","correct":true},{"t":"72개","mis":"M3-2-u2-X09"},{"t":"65개","mis":"M3-2-u2-X14"},{"t":"128개","mis":"M3-2-u2-X08"}],"explanation":["8봉지에 9개씩 — 8 × 9 = 72개.","남은 7개를 더해요.","72 + 7 = 79 — 모두 79개예요."],"asset":null},{"stem":"종이꽃을 4바구니에 21개씩 담았더니 3개가 남았어요. 종이꽃은 모두 몇 개인가요?","options":[{"t":"87개","correct":true},{"t":"84개","mis":"M3-2-u2-X09"},{"t":"81개","mis":"M3-2-u2-X14"},{"t":"96개","mis":"M3-2-u2-X08"}],"explanation":["4바구니에 21개씩 — 4 × 21 = 84개.","남은 3개를 더해요.","84 + 3 = 87 — 모두 87개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#24','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',4,'sa','auto','어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 498이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u2-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 3으로 나누어야 하는데 잘못하여 3을 곱했더니 498이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["어떤 수 × 3 = 498 → 어떤 수는 498 ÷ 3 = 166이에요.","바르게 계산하면 166 ÷ 3.","166 ÷ 3 = 55 … 1 — 몫은 55예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 7로 나누어야 하는데 잘못하여 7을 곱했더니 2051이 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["어떤 수 × 7 = 2051 → 어떤 수는 2051 ÷ 7 = 293이에요.","바르게 계산하면 293 ÷ 7.","293 ÷ 7 = 41 … 6 — 몫은 41이에요."],"asset":null},{"stem":"어떤 수를 6으로 나누어야 하는데 잘못하여 6을 곱했더니 2724가 되었어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["어떤 수 × 6 = 2724 → 어떤 수는 2724 ÷ 6 = 454예요.","바르게 계산하면 454 ÷ 6.","454 ÷ 6 = 75 … 4 — 몫은 75예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u2_review_d#25','math',3,2,'u2','','g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',4,'essay','teacher','호두과자 120개를 7상자에 똑같이 나누어 담아요. 한 상자에 몇 개씩 담고 몇 개가 남는지 구하고, 남는 것 없이 한 상자에 하나씩 더 담으려면 적어도 몇 개가 더 있어야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"호두과자 120개를 7상자에 똑같이 나누어 담아요. 한 상자에 몇 개씩 담고 몇 개가 남는지 구하고, 남는 것 없이 한 상자에 하나씩 더 담으려면 적어도 몇 개가 더 있어야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 120 ÷ 7 = 17 … 1이므로 한 상자에 17개씩 담고 1개가 남는다. 한 상자에 18개씩 담으려면 7 × 18 = 126개가 필요하므로 126 − 120 = 6개가 더 있어야 한다.","scoring_points":["17 … 1을 구했는가","7 × 18 = 126을 구했는가","6개 더 필요하다고 답했는가"]},"explanation":["120 ÷ 7 = 17 … 1.","7 × 18 = 126.","126 − 120 = 6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
